select ac_cargar_unidad($ac${"slug":"movilidad-1","rama":"movilidad","orden":1,"nivel":1,"titulo_es":"Cómo nos movemos","bajada_es":"A pie, en bici, en colectivo, en tren o en auto: cuánto emite, cuánto espacio ocupa y cuánto cuesta en salud cada forma de moverse.","objetivos_es":["Describir los modos de transporte y por qué se eligen","Comparar las emisiones por persona y por kilómetro de cada modo","Explicar el efecto de la ocupación de un vehículo en su huella","Comparar el espacio urbano que ocupa cada modo","Relacionar el tránsito con la seguridad vial, el aire y la salud"],"repasa":["tronco-2","tronco-3"],"requiere_tronco":1,"fuentes":["owid-transporte","oms-seguridad-vial","oms-actividad-fisica","icct-ev","oms-aire-exterior"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"movilidad-1.s1","orden":1,"tipo":"leccion","titulo_es":"Por qué y cómo nos movemos","bajada_es":"Viajes, distancias y modos: lo que decide cómo se mueve una persona en su ciudad.","minutos":11,"pasos":[{"slug":"movilidad-1.s1.p1","orden":1,"grupo":"movilidad-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Moverse para llegar","cuerpo":["Casi nadie viaja por viajar: nos movemos para llegar al trabajo, a la escuela, al médico, a hacer compras o a ver a alguien. Por eso la movilidad depende de dónde están las cosas: si todo queda lejos, hay que viajar más.","Los modos de transporte se suelen agrupar en activos (caminar, bicicleta), colectivos (colectivo, tren, subte, tranvía) e individuales motorizados (auto, moto)."]},"solucion":{}},{"slug":"movilidad-1.s1.p2","orden":2,"grupo":"movilidad-1.s1.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué grupo pertenece cada modo?","grupos":[{"id":"g1","nombre":"Activo"},{"id":"g2","nombre":"Colectivo o público"},{"id":"g3","nombre":"Individual motorizado"}],"items":[{"id":"i1","texto":"Caminar"},{"id":"i2","texto":"Colectivo"},{"id":"i3","texto":"Auto"},{"id":"i4","texto":"Bicicleta"},{"id":"i5","texto":"Tren"},{"id":"i6","texto":"Moto"},{"id":"i7","texto":"Subte"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g2"},"explicacion":"Tres grandes grupos con impactos muy distintos en emisiones, espacio y salud."}},{"slug":"movilidad-1.s1.p3","orden":3,"grupo":"movilidad-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué decide cómo viajamos","cuerpo":["Cada persona elige cómo moverse según la distancia, el tiempo de viaje, el costo, la comodidad, la seguridad, el clima y lo que tiene disponible. Si no hay colectivo cerca o las calles son peligrosas para la bici, la opción de moverse de otra forma casi no existe.","Por eso cambiar la movilidad de una ciudad depende tanto de las decisiones personales como de la infraestructura: veredas, ciclovías, frecuencias del transporte público."]},"solucion":{}},{"slug":"movilidad-1.s1.p4","orden":4,"grupo":"movilidad-1.s1.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué factores influyen en cómo una persona decide viajar? Marcá todos.","opciones":[{"id":"o1","texto":"La distancia"},{"id":"o2","texto":"El tiempo de viaje"},{"id":"o3","texto":"El costo"},{"id":"o4","texto":"La seguridad del recorrido"},{"id":"o5","texto":"El color de la ropa que lleva puesta"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Distancia, tiempo, costo y seguridad pesan mucho. Y lo que la ciudad ofrece define las opciones."}},{"slug":"movilidad-1.s1.p5","orden":5,"grupo":"movilidad-1.s1.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué una ciudad dispersa genera más viajes en auto.","items":[{"id":"i1","texto":"La ciudad crece con barrios lejos del centro"},{"id":"i2","texto":"Las distancias a trabajos y comercios se alargan"},{"id":"i3","texto":"Caminar o pedalear deja de ser práctico"},{"id":"i4","texto":"El transporte público cubre mal las zonas nuevas"},{"id":"i5","texto":"Más personas dependen del auto"},{"id":"i6","texto":"El auto hace que la ciudad sea más compacta"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La forma de la ciudad decide buena parte de cómo nos movemos. Es un tema de sistema, como en el tronco."}},{"slug":"movilidad-1.s1.p6","orden":6,"grupo":"movilidad-1.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Distancias y tiempos","cuerpo":["Caminando se recorren unos 4 a 5 km por hora; en bicicleta, unos 12 a 18 km por hora en la ciudad. Para viajes de hasta 1 o 2 km, caminar suele ser competitivo; hasta 5 a 8 km, la bicicleta suele ser tan rápida como el auto en horas pico, sin contar el tiempo de estacionar."]},"solucion":{}},{"slug":"movilidad-1.s1.p7","orden":7,"grupo":"movilidad-1.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos tarda en bicicleta alguien que recorre 3 km a 15 km por hora?","unidad":"minutos","decimales":0},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"3 ÷ 15 = 0,2 horas, que son 12 minutos. En hora pico, muchas veces menos que el auto."}},{"slug":"movilidad-1.s1.p7.v2","orden":7,"grupo":"movilidad-1.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos tarda en bicicleta alguien que recorre 5 km a 15 km por hora?","unidad":"minutos","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"5 ÷ 15 = 0,333 horas, que son 20 minutos. En hora pico, muchas veces menos que el auto."}},{"slug":"movilidad-1.s1.p7.v3","orden":7,"grupo":"movilidad-1.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos tarda en bicicleta alguien que recorre 2 km a 12 km por hora?","unidad":"minutos","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"2 ÷ 12 = 0,167 horas, que son 10 minutos. En hora pico, muchas veces menos que el auto."}},{"slug":"movilidad-1.s1.p8","orden":8,"grupo":"movilidad-1.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos se tarda en caminar 1,5 km a 5 km por hora?","unidad":"minutos","decimales":0},"solucion":{"valor":18,"tolerancia":0.5,"explicacion":"1,5 ÷ 5 × 60 = 18 minutos. Muchos viajes cotidianos en auto son de estas distancias."}},{"slug":"movilidad-1.s1.p8.v2","orden":8,"grupo":"movilidad-1.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos se tarda en caminar 2 km a 5 km por hora?","unidad":"minutos","decimales":0},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"2 ÷ 5 × 60 = 24 minutos. Muchos viajes cotidianos en auto son de estas distancias."}},{"slug":"movilidad-1.s1.p8.v3","orden":8,"grupo":"movilidad-1.s1.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos se tarda en caminar 1 km a 5 km por hora?","unidad":"minutos","decimales":0},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"1 ÷ 5 × 60 = 12 minutos. Muchos viajes cotidianos en auto son de estas distancias."}},{"slug":"movilidad-1.s1.p9","orden":9,"grupo":"movilidad-1.s1.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada distancia con el modo que suele ser más práctico en la ciudad.","izquierda":[{"id":"a1","texto":"Menos de 1 km"},{"id":"a2","texto":"De 2 a 7 km"},{"id":"a3","texto":"De 10 a 30 km"},{"id":"a4","texto":"Entre ciudades lejanas"}],"derecha":[{"id":"b1","texto":"Caminar"},{"id":"b2","texto":"Bicicleta"},{"id":"b3","texto":"Tren o colectivo"},{"id":"b4","texto":"Micro de larga distancia o tren"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada modo tiene su distancia ideal. Combinarlos permite cubrir cualquier viaje."}},{"slug":"movilidad-1.s1.p10","orden":10,"grupo":"movilidad-1.s1.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una ciudad no tiene ciclovías ni veredas seguras, la gente no elige la bici o caminar solo por gusto.","razones":[{"id":"r1","texto":"Porque la infraestructura define qué opciones son seguras y prácticas"},{"id":"r2","texto":"Porque a nadie le gusta caminar"},{"id":"r3","texto":"Porque la bici solo sirve en el campo"}]},"solucion":{"valor":true,"explicacion":"La infraestructura define las opciones reales. Donde pedalear es peligroso, pocos lo eligen aunque quieran.","clave":["r1"]}},{"slug":"movilidad-1.s1.p11","orden":11,"grupo":"movilidad-1.s1.p11","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un vecino hace 800 metros en auto para comprar pan todos los días. ¿Qué alternativa es más razonable?","opciones":[{"id":"o1","texto":"Caminar: son unos 10 minutos"},{"id":"o2","texto":"Tomar un colectivo que pasa cada 20 minutos"},{"id":"o3","texto":"Seguir en auto, porque siempre es más rápido"},{"id":"o4","texto":"Pedir el pan por delivery en moto"}]},"solucion":{"clave":["o1"],"explicacion":"En distancias tan cortas, caminar es rápido, gratis y saludable.","por_opcion":{"o3":"En 800 metros, entre arrancar, estacionar y caminar hasta el local, el auto casi no ahorra tiempo."}}},{"slug":"movilidad-1.s1.p12","orden":12,"grupo":"movilidad-1.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Muchos viajes diarios en auto son de pocos kilómetros."},{"id":"s2","texto":"La bici siempre es más lenta que el auto en la ciudad."},{"id":"s3","texto":"La forma de la ciudad influye en cómo nos movemos."},{"id":"s4","texto":"Cómo viajamos depende solo de la voluntad de cada persona."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La movilidad es a la vez decisión personal y diseño de ciudad.","por_opcion":{"s2":"En distancias cortas y en horas pico, la bici suele ser tan rápida o más.","s4":"También depende de la infraestructura y las distancias: es un tema de sistema."}}},{"slug":"movilidad-1.s1.p13","orden":13,"grupo":"movilidad-1.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Caminar y pedalear son modos {{0}}; colectivo, tren y subte son modos {{1}}; y la forma de la {{2}} define buena parte de cómo nos movemos.","banco":[{"id":"w1","texto":"activos"},{"id":"w2","texto":"colectivos"},{"id":"w3","texto":"ciudad"},{"id":"w4","texto":"pasivos"},{"id":"w5","texto":"privados"},{"id":"w6","texto":"ropa"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los grandes grupos de modos y el papel del diseño urbano."}}]},{"slug":"movilidad-1.s2","orden":2,"tipo":"leccion","titulo_es":"La huella de cada viaje","bajada_es":"Gramos de CO₂ por persona y por kilómetro: cómo se comparan el avión, el auto, el colectivo, el tren y la bici.","minutos":9,"pasos":[{"slug":"movilidad-1.s2.p1","orden":1,"grupo":"movilidad-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una unidad para comparar","cuerpo":["Para comparar modos se usan las emisiones por pasajero y por kilómetro: cuántos gramos de CO₂e se emiten para mover a una persona un kilómetro. Así se puede comparar un auto con una persona con un colectivo lleno.","Con datos del gobierno británico que publica Nuestro Mundo en Datos, un auto mediano a nafta con una sola persona emite unos 190 g por kilómetro; un colectivo, en promedio, unos 100 g por pasajero y kilómetro; el tren, unos 40; un auto eléctrico, unos 50 con esa red; y la bicicleta y la caminata, prácticamente nada en el viaje."],"datos":{"tipo":"barras","titulo":"Emisiones por pasajero y por kilómetro (Reino Unido, aproximado)","unidad":"g CO₂e","filas":[{"etiqueta":"Avión (vuelo interno)","valor":246},{"etiqueta":"Auto a nafta, 1 persona","valor":192},{"etiqueta":"Colectivo (ocupación promedio)","valor":105},{"etiqueta":"Auto eléctrico, 1 persona","valor":53},{"etiqueta":"Tren","valor":41},{"etiqueta":"Bicicleta","valor":0}],"nota":"Nuestro Mundo en Datos, a partir de factores del gobierno británico. En Argentina cambian según la ocupación y la red eléctrica."}},"solucion":{}},{"slug":"movilidad-1.s2.p2","orden":2,"grupo":"movilidad-1.s2.p2","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos modos por emisiones por pasajero y kilómetro, de más a menos (valores de referencia).","items":[{"id":"i1","texto":"Avión en vuelo interno"},{"id":"i2","texto":"Auto a nafta con una persona"},{"id":"i3","texto":"Colectivo con ocupación promedio"},{"id":"i4","texto":"Tren"},{"id":"i5","texto":"Bicicleta"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los vuelos cortos y el auto con una sola persona encabezan la lista. Tren y bici, al fondo.","valores":{"i1":"≈ 246 g","i2":"≈ 192 g","i3":"≈ 105 g","i4":"≈ 41 g","i5":"≈ 0 g en el viaje"}}},{"slug":"movilidad-1.s2.p3","orden":3,"grupo":"movilidad-1.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona viaja 20 km por día en auto a nafta sola (192 g por km). ¿Cuántos kilos de CO₂e emite por día? Redondeá a un decimal.","unidad":"kg CO₂e","decimales":1},"solucion":{"valor":3.8,"tolerancia":0.1,"explicacion":"20 × 192 = 3.840 g = 3,8 kg por día. En 230 días laborales, más de 0,8 t por año."}},{"slug":"movilidad-1.s2.p3.v2","orden":3,"grupo":"movilidad-1.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona viaja 15 km por día en auto a nafta sola (192 g por km). ¿Cuántos kilos de CO₂e emite por día? Redondeá a un decimal.","unidad":"kg CO₂e","decimales":1},"solucion":{"valor":2.9,"tolerancia":0.1,"explicacion":"15 × 192 = 2.880 g = 2,9 kg por día. En 230 días laborales, más de 0,6 t por año."}},{"slug":"movilidad-1.s2.p3.v3","orden":3,"grupo":"movilidad-1.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona viaja 30 km por día en auto a nafta sola (192 g por km). ¿Cuántos kilos de CO₂e emite por día? Redondeá a un decimal.","unidad":"kg CO₂e","decimales":1},"solucion":{"valor":5.8,"tolerancia":0.1,"explicacion":"30 × 192 = 5.760 g = 5,8 kg por día. En 230 días laborales, más de 1,3 t por año."}},{"slug":"movilidad-1.s2.p4","orden":4,"grupo":"movilidad-1.s2.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa persona hace los 20 km en tren (41 g por km) en vez de auto (192 g por km), ¿cuántos gramos de CO₂e ahorra por día?","unidad":"g CO₂e","decimales":0},"solucion":{"valor":3020,"tolerancia":60.4,"explicacion":"20 × (192 − 41) = 3.020 g por día: casi el 80 % menos para el mismo viaje."}},{"slug":"movilidad-1.s2.p4.v2","orden":4,"grupo":"movilidad-1.s2.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa persona hace los 15 km en tren (41 g por km) en vez de auto (192 g por km), ¿cuántos gramos de CO₂e ahorra por día?","unidad":"g CO₂e","decimales":0},"solucion":{"valor":2265,"tolerancia":45.300000000000004,"explicacion":"15 × (192 − 41) = 2.265 g por día: casi el 80 % menos para el mismo viaje."}},{"slug":"movilidad-1.s2.p4.v3","orden":4,"grupo":"movilidad-1.s2.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa persona hace los 30 km en tren (41 g por km) en vez de auto (192 g por km), ¿cuántos gramos de CO₂e ahorra por día?","unidad":"g CO₂e","decimales":0},"solucion":{"valor":4530,"tolerancia":90.60000000000001,"explicacion":"30 × (192 − 41) = 4.530 g por día: casi el 80 % menos para el mismo viaje."}},{"slug":"movilidad-1.s2.p5","orden":5,"grupo":"movilidad-1.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El avión","cuerpo":["Por kilómetro, un vuelo de cabotaje emite por pasajero más que casi cualquier otro modo. Y como los vuelos recorren distancias largas, un solo viaje puede pesar tanto como meses de viajes cotidianos. Un vuelo de ida y vuelta de 1.000 km por tramo son unos 2.000 km: con 246 g por km, casi media tonelada de CO₂e por persona.","Para distancias medias, el tren o el micro de larga distancia suelen emitir mucho menos por pasajero."]},"solucion":{}},{"slug":"movilidad-1.s2.p6","orden":6,"grupo":"movilidad-1.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un vuelo de ida y vuelta tiene 1.000 km por tramo. Con 246 g de CO₂e por pasajero y km, ¿cuántos kg emite cada pasajero? Redondeá al entero.","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":492,"tolerancia":1,"explicacion":"2 × 1.000 × 246 = 492.000 g ≈ 492 kg. Un solo viaje puede equivaler a meses de trayectos diarios."}},{"slug":"movilidad-1.s2.p6.v2","orden":6,"grupo":"movilidad-1.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un vuelo de ida y vuelta tiene 700 km por tramo. Con 246 g de CO₂e por pasajero y km, ¿cuántos kg emite cada pasajero? Redondeá al entero.","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":344,"tolerancia":1,"explicacion":"2 × 700 × 246 = 344.400 g ≈ 344 kg. Un solo viaje puede equivaler a meses de trayectos diarios."}},{"slug":"movilidad-1.s2.p6.v3","orden":6,"grupo":"movilidad-1.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un vuelo de ida y vuelta tiene 1.500 km por tramo. Con 246 g de CO₂e por pasajero y km, ¿cuántos kg emite cada pasajero? Redondeá al entero.","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":738,"tolerancia":1,"explicacion":"2 × 1.500 × 246 = 738.000 g ≈ 738 kg. Un solo viaje puede equivaler a meses de trayectos diarios."}},{"slug":"movilidad-1.s2.p7","orden":7,"grupo":"movilidad-1.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un auto eléctrico no tiene ninguna emisión asociada a su uso.","razones":[{"id":"r1","texto":"Porque su electricidad tiene emisiones según cómo se genera"},{"id":"r2","texto":"Porque los autos eléctricos queman nafta"},{"id":"r3","texto":"Porque la electricidad siempre es 100 % limpia"}]},"solucion":{"valor":false,"explicacion":"No emite por el caño, pero su electricidad se genera en algún lado. Con una red con mucho gas o carbón, sus emisiones por km son mayores que con una red limpia, aunque suelen ser menores que las de un auto a nafta.","clave":["r1"]}},{"slug":"movilidad-1.s2.p8","orden":8,"grupo":"movilidad-1.s2.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este viaje tiene una huella alta o baja por persona?","grupos":[{"id":"g1","nombre":"Alta"},{"id":"g2","nombre":"Baja"}],"items":[{"id":"i1","texto":"Vuelo de 800 km para una reunión"},{"id":"i2","texto":"Tren eléctrico al trabajo"},{"id":"i3","texto":"Auto grande con una sola persona todos los días"},{"id":"i4","texto":"Bicicleta a la facultad"},{"id":"i5","texto":"Moto de alta cilindrada para viajes largos"},{"id":"i6","texto":"Colectivo lleno en hora pico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Avión y auto con una persona, arriba. Transporte público lleno y modos activos, abajo."}},{"slug":"movilidad-1.s2.p9","orden":9,"grupo":"movilidad-1.s2.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Para un viaje de 500 km entre dos ciudades, ¿qué opción suele tener menor huella por pasajero?","opciones":[{"id":"o1","texto":"Tren o micro de larga distancia"},{"id":"o2","texto":"Avión de cabotaje"},{"id":"o3","texto":"Auto con una sola persona"},{"id":"o4","texto":"Dos autos para llevar el equipaje aparte"}]},"solucion":{"clave":["o1"],"explicacion":"En distancias medias, tren y micro emiten mucho menos por persona que el avión o el auto con una persona.","por_opcion":{"o3":"Con una persona, el auto está entre las opciones de mayor huella por pasajero."}}},{"slug":"movilidad-1.s2.p10","orden":10,"grupo":"movilidad-1.s2.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El auto a nafta con una persona emite bastante por kilómetro."},{"id":"s2","texto":"El avión emite poco porque va rápido."},{"id":"s3","texto":"El tren emite mucho menos por pasajero que el auto."},{"id":"s4","texto":"El auto eléctrico tiene emisiones cero en cualquier país."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Comparar por pasajero y kilómetro desarma varias creencias.","por_opcion":{"s2":"Por pasajero y km, un vuelo corto emite más que casi cualquier modo.","s4":"Depende de cómo se genera la electricidad de la red."}}},{"slug":"movilidad-1.s2.p11","orden":11,"grupo":"movilidad-1.s2.p11","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para comparar modos se usan gramos de CO₂e por {{0}} y por kilómetro; los vuelos {{1}} y el auto con una persona están entre los que más emiten.","banco":[{"id":"w1","texto":"pasajero"},{"id":"w2","texto":"cortos"},{"id":"w3","texto":"litro"},{"id":"w4","texto":"largos"},{"id":"w5","texto":"hora"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La unidad para comparar y quiénes encabezan la lista."}},{"slug":"movilidad-1.s2.p12","orden":12,"grupo":"movilidad-1.s2.p12","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos gramos de CO₂e por kilómetro emite un auto a nafta que gasta 8 litros cada 100 km (2,3 kg de CO₂ por litro).","min":10,"max":1000,"paso":1,"unidad":"g por km","escala":"lineal"},"solucion":{"valor":184,"banda":"lineal","explicacion":"8 litros × 2,3 kg = 18,4 kg cada 100 km, o sea 184 g por km. Muy cerca del valor de referencia de 192 g."}}]},{"slug":"movilidad-1.s3","orden":3,"tipo":"leccion","titulo_es":"Ocupación: el mismo vehículo, distinta huella","bajada_es":"Un auto con cuatro personas o con una, un colectivo lleno o vacío: por qué la ocupación cambia todo.","minutos":11,"pasos":[{"slug":"movilidad-1.s3.p1","orden":1,"grupo":"movilidad-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dividir entre los que viajan","cuerpo":["Un auto emite más o menos lo mismo si lleva una persona o cuatro. Por eso, por persona, un auto con cuatro pasajeros emite la cuarta parte que uno con el conductor solo. Con un colectivo pasa lo mismo, a otra escala: lleno, emite muy poco por pasajero; casi vacío, bastante.","Los valores de referencia de los colectivos y trenes suponen una ocupación promedio. En horas pico, con vehículos llenos, la huella por pasajero es mucho menor."]},"solucion":{}},{"slug":"movilidad-1.s3.p2","orden":2,"grupo":"movilidad-1.s3.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El auto compartido","planteo":"Un auto emite 190 g de CO₂e por kilómetro.","pasos":["Con 1 persona: 190 ÷ 1 = 190 g por persona y km.","Con 2 personas: 190 ÷ 2 = 95 g.","Con 4 personas: 190 ÷ 4 = 47,5 g."],"resultado":"El mismo auto, cuatro veces menos por persona. Compartir el auto es una de las formas más simples de bajar la huella."},"solucion":{}},{"slug":"movilidad-1.s3.p3","orden":3,"grupo":"movilidad-1.s3.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto emite 190 g de CO₂e por km. Si viajan 4 personas, ¿cuántos gramos emite por persona y km? Redondeá a un decimal.","unidad":"g por persona y km","decimales":1},"solucion":{"valor":47.5,"tolerancia":0.9500000000000001,"explicacion":"190 ÷ 4 ≈ 47,5 g. Llenar el auto divide la huella entre más personas."}},{"slug":"movilidad-1.s3.p3.v2","orden":3,"grupo":"movilidad-1.s3.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto emite 170 g de CO₂e por km. Si viajan 3 personas, ¿cuántos gramos emite por persona y km? Redondeá a un decimal.","unidad":"g por persona y km","decimales":1},"solucion":{"valor":56.7,"tolerancia":1.1340000000000001,"explicacion":"170 ÷ 3 ≈ 56,7 g. Llenar el auto divide la huella entre más personas."}},{"slug":"movilidad-1.s3.p3.v3","orden":3,"grupo":"movilidad-1.s3.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto emite 220 g de CO₂e por km. Si viajan 2 personas, ¿cuántos gramos emite por persona y km? Redondeá a un decimal.","unidad":"g por persona y km","decimales":1},"solucion":{"valor":110,"tolerancia":2.2,"explicacion":"220 ÷ 2 ≈ 110 g. Llenar el auto divide la huella entre más personas."}},{"slug":"movilidad-1.s3.p4","orden":4,"grupo":"movilidad-1.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El colectivo","cuerpo":["Un colectivo urbano diésel emite, por kilómetro recorrido, varias veces más que un auto, porque es mucho más grande y pesado: del orden de 1.000 g de CO₂ por km. Pero si lleva 50 pasajeros, son unos 20 g por persona. Si lleva 5, son unos 200 g por persona: tanto como un auto con una persona.","Por eso el transporte público es eficiente cuando se usa mucho. Un sistema con buena frecuencia y recorridos útiles atrae más pasajeros y baja la huella de cada uno."]},"solucion":{}},{"slug":"movilidad-1.s3.p5","orden":5,"grupo":"movilidad-1.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un colectivo emite 1.000 g de CO₂ por km y lleva 50 pasajeros. ¿Cuántos gramos emite por pasajero y km?","unidad":"g por pasajero y km","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"1.000 ÷ 50 = 20 g. Con buena ocupación, muy por debajo de un auto con una persona."}},{"slug":"movilidad-1.s3.p5.v2","orden":5,"grupo":"movilidad-1.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un colectivo emite 1.000 g de CO₂ por km y lleva 20 pasajeros. ¿Cuántos gramos emite por pasajero y km?","unidad":"g por pasajero y km","decimales":0},"solucion":{"valor":50,"tolerancia":1,"explicacion":"1.000 ÷ 20 = 50 g. Con buena ocupación, muy por debajo de un auto con una persona."}},{"slug":"movilidad-1.s3.p5.v3","orden":5,"grupo":"movilidad-1.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un colectivo emite 1.000 g de CO₂ por km y lleva 5 pasajeros. ¿Cuántos gramos emite por pasajero y km?","unidad":"g por pasajero y km","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"1.000 ÷ 5 = 200 g. Casi vacío, tanto como un auto con una sola persona."}},{"slug":"movilidad-1.s3.p6","orden":6,"grupo":"movilidad-1.s3.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos viajes por emisiones por persona y km, de más a menos.","items":[{"id":"i1","texto":"Colectivo con 4 pasajeros (1.000 g por km)"},{"id":"i2","texto":"Auto con 1 persona (190 g por km)"},{"id":"i3","texto":"Auto con 4 personas (190 g por km)"},{"id":"i4","texto":"Colectivo con 50 pasajeros (1.000 g por km)"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un colectivo casi vacío puede emitir más por persona que un auto. Lleno, es de lo mejor. La ocupación manda.","valores":{"i1":"250 g","i2":"190 g","i3":"47,5 g","i4":"20 g"}}},{"slug":"movilidad-1.s3.p7","orden":7,"grupo":"movilidad-1.s3.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un colectivo siempre emite menos por pasajero que un auto.","razones":[{"id":"r1","texto":"Porque depende de cuántos pasajeros lleve"},{"id":"r2","texto":"Porque los colectivos no emiten"},{"id":"r3","texto":"Porque los autos emiten siempre más por kilómetro que los colectivos"}]},"solucion":{"valor":false,"explicacion":"Depende de la ocupación. Un colectivo casi vacío puede emitir más por pasajero que un auto con una persona. Lleno, emite mucho menos.","clave":["r1"]}},{"slug":"movilidad-1.s3.p8","orden":8,"grupo":"movilidad-1.s3.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué mejorar la frecuencia del colectivo puede bajar las emisiones por pasajero.","items":[{"id":"i1","texto":"El colectivo pasa más seguido"},{"id":"i2","texto":"Esperar deja de ser un problema"},{"id":"i3","texto":"Más personas lo eligen en vez del auto"},{"id":"i4","texto":"Cada colectivo va más lleno"},{"id":"i5","texto":"Bajan las emisiones por pasajero y los autos en la calle"},{"id":"i6","texto":"Más colectivos siempre significan más emisiones por pasajero"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un buen servicio atrae pasajeros, y los pasajeros hacen eficiente al servicio: un círculo virtuoso."}},{"slug":"movilidad-1.s3.p9","orden":9,"grupo":"movilidad-1.s3.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida aumenta la ocupación de los vehículos o no?","grupos":[{"id":"g1","nombre":"Aumenta la ocupación"},{"id":"g2","nombre":"No la aumenta"}],"items":[{"id":"i1","texto":"Compartir el auto con compañeros de trabajo"},{"id":"i2","texto":"Comprar un segundo auto para la familia"},{"id":"i3","texto":"Carriles exclusivos que hacen más rápido el colectivo"},{"id":"i4","texto":"Autos de alquiler con un solo pasajero"},{"id":"i5","texto":"Apps para coordinar viajes compartidos"},{"id":"i6","texto":"Llevar a cada hijo en un auto distinto"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Más personas por vehículo es menos huella por persona y menos autos en la calle."}},{"slug":"movilidad-1.s3.p10","orden":10,"grupo":"movilidad-1.s3.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ventajas tiene compartir el auto? Marcá todas.","opciones":[{"id":"o1","texto":"Menos emisiones por persona"},{"id":"o2","texto":"Se reparten los costos de combustible y estacionamiento"},{"id":"o3","texto":"Menos autos en la calle"},{"id":"o4","texto":"Menos congestión"},{"id":"o5","texto":"El auto pasa a emitir cero"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El auto emite lo mismo, pero se reparte entre más personas y hay menos autos circulando."}},{"slug":"movilidad-1.s3.p11","orden":11,"grupo":"movilidad-1.s3.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Cuatro compañeros viven cerca y trabajan en el mismo lugar, a 15 km. Hoy van en cuatro autos. ¿Qué cambio baja más la huella con menos esfuerzo?","opciones":[{"id":"o1","texto":"Ir los cuatro en un solo auto"},{"id":"o2","texto":"Que cada uno cambie su auto por uno un poco más chico"},{"id":"o3","texto":"Que cada uno maneje más despacio"},{"id":"o4","texto":"Que uno de los cuatro vaya en bici un día por mes"}]},"solucion":{"clave":["o1"],"explicacion":"Pasar de cuatro autos a uno baja la huella del viaje a una cuarta parte, sin comprar nada.","por_opcion":{"o3":"Ahorra algo, pero muchísimo menos que dejar tres autos en casa."}}},{"slug":"movilidad-1.s3.p12","orden":12,"grupo":"movilidad-1.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este razonamiento y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Un auto con cuatro personas emite por persona la cuarta parte que con una."},{"id":"s2","texto":"Un colectivo emite más por km que un auto, así que siempre es peor."},{"id":"s3","texto":"La ocupación cambia mucho la huella por persona."},{"id":"s4","texto":"Un colectivo vacío emite cero porque no lleva a nadie."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Por vehículo o por persona: la unidad cambia la conclusión.","por_opcion":{"s2":"Por pasajero, un colectivo con buena ocupación emite mucho menos.","s4":"Emite igual por km; al no llevar pasajeros, su huella por persona es altísima."}}},{"slug":"movilidad-1.s3.p13","orden":13,"grupo":"movilidad-1.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las emisiones por persona se calculan dividiendo las del vehículo por la cantidad de {{0}}; por eso compartir el auto {{1}} la huella de cada uno.","banco":[{"id":"w1","texto":"pasajeros"},{"id":"w2","texto":"reduce"},{"id":"w3","texto":"ruedas"},{"id":"w4","texto":"aumenta"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La idea central de la lección, resumida en una línea."}}]},{"slug":"movilidad-1.s4","orden":4,"tipo":"leccion","titulo_es":"El espacio que ocupa cada modo","bajada_es":"Cuánto lugar de la ciudad usa un auto, un colectivo o una bici, y por qué el espacio también es un recurso.","minutos":9,"pasos":[{"slug":"movilidad-1.s4.p1","orden":1,"grupo":"movilidad-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La calle es un recurso limitado","cuerpo":["El espacio de las calles de una ciudad es limitado y valioso. Un auto estacionado ocupa unos 10 a 12 metros cuadrados, más o menos lo que un dormitorio chico, y pasa estacionado la mayor parte del día. En movimiento, ocupa mucho más, porque necesita distancia con el de adelante.","Una bicicleta ocupa una fracción de ese espacio, y un colectivo lleno mueve a decenas de personas en el lugar de dos o tres autos."]},"solucion":{}},{"slug":"movilidad-1.s4.p2","orden":2,"grupo":"movilidad-1.s4.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una cuadra tiene lugar para estacionar 100 autos de 11 m² cada uno. ¿Cuántos metros cuadrados de calle se usan para estacionar?","unidad":"m²","decimales":0},"solucion":{"valor":1100,"tolerancia":22,"explicacion":"100 × 11 = 1.100 m². Espacio público que podría ser vereda, árboles, ciclovía o plaza."}},{"slug":"movilidad-1.s4.p2.v2","orden":2,"grupo":"movilidad-1.s4.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una cuadra tiene lugar para estacionar 250 autos de 11 m² cada uno. ¿Cuántos metros cuadrados de calle se usan para estacionar?","unidad":"m²","decimales":0},"solucion":{"valor":2750,"tolerancia":55,"explicacion":"250 × 11 = 2.750 m². Espacio público que podría ser vereda, árboles, ciclovía o plaza."}},{"slug":"movilidad-1.s4.p2.v3","orden":2,"grupo":"movilidad-1.s4.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una cuadra tiene lugar para estacionar 40 autos de 11 m² cada uno. ¿Cuántos metros cuadrados de calle se usan para estacionar?","unidad":"m²","decimales":0},"solucion":{"valor":440,"tolerancia":8.8,"explicacion":"40 × 11 = 440 m². Espacio público que podría ser vereda, árboles, ciclovía o plaza."}},{"slug":"movilidad-1.s4.p3","orden":3,"grupo":"movilidad-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Personas por carril","cuerpo":["Lo que importa para mover una ciudad no es cuántos vehículos pasan por un carril, sino cuántas personas. Un carril de autos, con una o dos personas por auto, mueve pocas personas por hora comparado con un carril exclusivo de colectivos o una vía de tren, que pueden mover varias veces más gente en el mismo ancho.","Por eso muchas ciudades dan prioridad al transporte público con carriles exclusivos o sistemas de colectivos rápidos: con el mismo espacio, mueven a muchas más personas."]},"solucion":{}},{"slug":"movilidad-1.s4.p4","orden":4,"grupo":"movilidad-1.s4.p4","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos usos de un carril por cuántas personas pueden mover por hora, de más a menos.","items":[{"id":"i1","texto":"Vía de tren o subte"},{"id":"i2","texto":"Carril exclusivo de colectivos"},{"id":"i3","texto":"Ciclovía"},{"id":"i4","texto":"Carril de autos particulares"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El auto es el modo que menos personas mueve por metro de calle. En ciudades densas, eso importa mucho.","valores":{"i1":"la mayor cantidad","i2":"mucha","i3":"bastante","i4":"la menor"}}},{"slug":"movilidad-1.s4.p5","orden":5,"grupo":"movilidad-1.s4.p5","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué ensanchar una avenida no siempre reduce los embotellamientos.","items":[{"id":"i1","texto":"Se ensancha una avenida congestionada"},{"id":"i2","texto":"Por un tiempo se circula más rápido"},{"id":"i3","texto":"Más personas eligen el auto porque ahora es más cómodo"},{"id":"i4","texto":"Aumenta la cantidad de autos"},{"id":"i5","texto":"La avenida vuelve a congestionarse"},{"id":"i6","texto":"Los autos se achican cuando la avenida es más ancha"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Se llama demanda inducida: más espacio para autos atrae más autos. Es un efecto de sistema."}},{"slug":"movilidad-1.s4.p6","orden":6,"grupo":"movilidad-1.s4.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Ensanchar las avenidas es la solución definitiva para los embotellamientos.","razones":[{"id":"r1","texto":"Porque más espacio para autos atrae más autos"},{"id":"r2","texto":"Porque los autos no necesitan espacio"},{"id":"r3","texto":"Porque las avenidas anchas prohíben los autos"}]},"solucion":{"valor":false,"explicacion":"Suele atraer más autos y, con el tiempo, la congestión vuelve. Priorizar el transporte público y los modos activos mueve más personas en el mismo espacio.","clave":["r1"]}},{"slug":"movilidad-1.s4.p7","orden":7,"grupo":"movilidad-1.s4.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada modo con cuánto espacio usa por persona.","izquierda":[{"id":"a1","texto":"Auto con una persona"},{"id":"a2","texto":"Colectivo lleno"},{"id":"a3","texto":"Bicicleta"},{"id":"a4","texto":"A pie"}],"derecha":[{"id":"b1","texto":"Mucho espacio por persona"},{"id":"b2","texto":"Poco espacio por persona"},{"id":"b3","texto":"Muy poco espacio por persona"},{"id":"b4","texto":"El mínimo espacio por persona"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"En una ciudad con poco espacio, los modos que usan poco lugar por persona hacen que entremos todos."}},{"slug":"movilidad-1.s4.p8","orden":8,"grupo":"movilidad-1.s4.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿En qué se podría usar el espacio que hoy ocupan autos estacionados? Marcá todo lo posible.","opciones":[{"id":"o1","texto":"Veredas más anchas"},{"id":"o2","texto":"Árboles y canteros"},{"id":"o3","texto":"Ciclovías"},{"id":"o4","texto":"Carriles para colectivos"},{"id":"o5","texto":"Nada, el espacio de la calle solo sirve para autos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La calle es espacio público. Qué se hace con él es una decisión de la ciudad."}},{"slug":"movilidad-1.s4.p9","orden":9,"grupo":"movilidad-1.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una avenida con un carril congestionado de autos y muchos colectivos atascados, ¿qué medida mueve más personas?","opciones":[{"id":"o1","texto":"Hacer un carril exclusivo para colectivos"},{"id":"o2","texto":"Agregar un carril más para autos"},{"id":"o3","texto":"Prohibir los colectivos para que haya más lugar"},{"id":"o4","texto":"Poner más semáforos en rojo largos"}]},"solucion":{"clave":["o1"],"explicacion":"Liberar a los colectivos del tránsito los hace más rápidos, más atractivos y más eficientes.","por_opcion":{"o3":"Los colectivos llevan a la mayoría de las personas: sacarlos empeora todo."}}},{"slug":"movilidad-1.s4.p10","orden":10,"grupo":"movilidad-1.s4.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta decisión prioriza a las personas o a los autos?","grupos":[{"id":"g1","nombre":"Prioriza a las personas"},{"id":"g2","nombre":"Prioriza a los autos"}],"items":[{"id":"i1","texto":"Carril exclusivo de colectivo"},{"id":"i2","texto":"Sacar un cantero para hacer estacionamiento"},{"id":"i3","texto":"Ensanchar veredas en una calle comercial"},{"id":"i4","texto":"Ensanchar la calle a costa de la vereda"},{"id":"i5","texto":"Ciclovía protegida"},{"id":"i6","texto":"Semáforos que dan poco tiempo para cruzar a pie"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cada metro de calle refleja una prioridad. Contarlo en personas cambia la mirada."}},{"slug":"movilidad-1.s4.p11","orden":11,"grupo":"movilidad-1.s4.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta de un candidato y marcá lo cuestionable.","segmentos":[{"id":"s1","texto":"Vamos a hacer un carril exclusivo de colectivos en la avenida principal."},{"id":"s2","texto":"Y vamos a ensanchar todas las avenidas para que se acaben los embotellamientos."},{"id":"s3","texto":"Sumaremos ciclovías protegidas."},{"id":"s4","texto":"Un auto estacionado no ocupa espacio público."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El espacio de la ciudad es un recurso: la pregunta es para quién se usa.","por_opcion":{"s2":"Por la demanda inducida, más espacio para autos suele atraer más autos.","s4":"Ocupa unos 10 a 12 m² de calle, que es espacio público."}}},{"slug":"movilidad-1.s4.p12","orden":12,"grupo":"movilidad-1.s4.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un auto estacionado ocupa unos {{0}} m²; ensanchar avenidas suele atraer más autos, un efecto llamado demanda {{1}}.","banco":[{"id":"w1","texto":"11"},{"id":"w2","texto":"inducida"},{"id":"w3","texto":"2"},{"id":"w4","texto":"reducida"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para pensar el espacio de la calle."}}]},{"slug":"movilidad-1.s5","orden":5,"tipo":"leccion","titulo_es":"Tránsito y salud","bajada_es":"Siniestros viales, aire, ruido y sedentarismo: lo que el tránsito le cuesta a la salud.","minutos":11,"pasos":[{"slug":"movilidad-1.s5.p1","orden":1,"grupo":"movilidad-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Siniestros viales","cuerpo":["Según la Organización Mundial de la Salud, los siniestros de tránsito causan alrededor de 1,2 millones de muertes por año en el mundo, y son la principal causa de muerte de niños y jóvenes de 5 a 29 años. En Argentina, cada año mueren miles de personas en el tránsito.","La mayoría de las víctimas son usuarios vulnerables: peatones, ciclistas y motociclistas. La velocidad es uno de los factores más importantes: a mayor velocidad, más probable el choque y más graves las lesiones."],"destacado":{"valor":"≈ 1,2 millones","texto":"de muertes por año causan los siniestros de tránsito en el mundo, según la OMS."}},"solucion":{}},{"slug":"movilidad-1.s5.p2","orden":2,"grupo":"movilidad-1.s5.p2","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas personas mueren por año en el mundo en siniestros de tránsito, según la OMS.","min":10000,"max":100000000,"paso":1,"unidad":"personas","escala":"log"},"solucion":{"valor":1200000,"banda":"log","explicacion":"Alrededor de 1,2 millones. Además, decenas de millones resultan heridas."}},{"slug":"movilidad-1.s5.p3","orden":3,"grupo":"movilidad-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La velocidad","cuerpo":["Un peatón atropellado a 30 km/h tiene muchas más chances de sobrevivir que uno atropellado a 50 km/h: la energía del choque crece con el cuadrado de la velocidad. Por eso muchas ciudades bajan a 30 km/h la velocidad máxima en calles con mucha gente caminando.","Además, a menor velocidad el conductor ve más, frena en menos distancia y reacciona mejor."]},"solucion":{}},{"slug":"movilidad-1.s5.p4","orden":4,"grupo":"movilidad-1.s5.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué bajar la velocidad a 30 km/h en un barrio salva vidas.","items":[{"id":"i1","texto":"Se baja la velocidad máxima a 30 km/h"},{"id":"i2","texto":"Los autos frenan en menos distancia"},{"id":"i3","texto":"Hay menos choques"},{"id":"i4","texto":"Los choques que ocurren tienen menos energía"},{"id":"i5","texto":"Hay menos muertes y heridos graves"},{"id":"i6","texto":"A 30 km/h los autos no pueden chocar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Velocidad más baja: menos choques y menos graves. Una de las medidas más efectivas de seguridad vial."}},{"slug":"movilidad-1.s5.p5","orden":5,"grupo":"movilidad-1.s5.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía de un choque crece con el cuadrado de la velocidad. ¿Cuántas veces más energía tiene un choque a 60 km/h que a 30 km/h?","unidad":"veces","decimales":0},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"(60 ÷ 30)² = 2² = 4. El doble de velocidad es cuatro veces la energía."}},{"slug":"movilidad-1.s5.p5.v2","orden":5,"grupo":"movilidad-1.s5.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía de un choque crece con el cuadrado de la velocidad. ¿Cuántas veces más energía tiene un choque a 80 km/h que a 40 km/h?","unidad":"veces","decimales":0},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"(80 ÷ 40)² = 2² = 4. El doble de velocidad es cuatro veces la energía."}},{"slug":"movilidad-1.s5.p5.v3","orden":5,"grupo":"movilidad-1.s5.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía de un choque crece con el cuadrado de la velocidad. ¿Cuántas veces más energía tiene un choque a 60 km/h que a 20 km/h?","unidad":"veces","decimales":0},"solucion":{"valor":9,"tolerancia":0.5,"explicacion":"(60 ÷ 20)² = 3² = 9. Por eso la velocidad pesa tanto en la gravedad de las lesiones."}},{"slug":"movilidad-1.s5.p6","orden":6,"grupo":"movilidad-1.s5.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Ir el doble de rápido duplica la energía de un choque.","razones":[{"id":"r1","texto":"Porque la energía crece con el cuadrado de la velocidad"},{"id":"r2","texto":"Porque la energía no depende de la velocidad"},{"id":"r3","texto":"Porque la energía se reduce a la mitad"}]},"solucion":{"valor":false,"explicacion":"La energía crece con el cuadrado de la velocidad: el doble de velocidad es cuatro veces más energía. Por eso la velocidad es tan peligrosa.","clave":["r1"]}},{"slug":"movilidad-1.s5.p7","orden":7,"grupo":"movilidad-1.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Aire, ruido y sedentarismo","cuerpo":["El tránsito también afecta la salud de otras formas. Los motores, sobre todo los diésel viejos, contaminan el aire que se respira en las calles, como viste en la rama de Aire y Suelo. El ruido del tránsito altera el sueño y aumenta el estrés.","Y moverse siempre en auto contribuye al sedentarismo. La OMS recomienda que las personas adultas hagan al menos 150 minutos semanales de actividad física moderada: caminar o pedalear para ir al trabajo o la escuela puede cubrirlo sin buscar tiempo extra."]},"solucion":{}},{"slug":"movilidad-1.s5.p8","orden":8,"grupo":"movilidad-1.s5.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿De qué formas afecta el tránsito motorizado a la salud? Marcá todas.","opciones":[{"id":"o1","texto":"Siniestros viales"},{"id":"o2","texto":"Contaminación del aire"},{"id":"o3","texto":"Ruido que altera el sueño"},{"id":"o4","texto":"Sedentarismo"},{"id":"o5","texto":"Más árboles en las veredas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuatro efectos distintos. Los modos activos y el transporte público reducen los cuatro."}},{"slug":"movilidad-1.s5.p9","orden":9,"grupo":"movilidad-1.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alguien camina 15 minutos de ida y 15 de vuelta al trabajo, 5 días por semana. ¿Cuántos minutos de actividad física suma por semana?","unidad":"minutos","decimales":0},"solucion":{"valor":150,"tolerancia":3,"explicacion":"15 × 2 × 5 = 150 minutos. Cumple la recomendación de la OMS de 150 minutos semanales solo con ir y volver."}},{"slug":"movilidad-1.s5.p9.v2","orden":9,"grupo":"movilidad-1.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alguien camina 10 minutos de ida y 10 de vuelta al trabajo, 5 días por semana. ¿Cuántos minutos de actividad física suma por semana?","unidad":"minutos","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"10 × 2 × 5 = 100 minutos. Le falta poco para los 150 minutos semanales que recomienda la OMS."}},{"slug":"movilidad-1.s5.p9.v3","orden":9,"grupo":"movilidad-1.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alguien camina 20 minutos de ida y 20 de vuelta al trabajo, 5 días por semana. ¿Cuántos minutos de actividad física suma por semana?","unidad":"minutos","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"20 × 2 × 5 = 200 minutos. Cumple la recomendación de la OMS de 150 minutos semanales solo con ir y volver."}},{"slug":"movilidad-1.s5.p10","orden":10,"grupo":"movilidad-1.s5.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema de salud con una medida de movilidad que lo reduce.","izquierda":[{"id":"a1","texto":"Siniestros viales"},{"id":"a2","texto":"Contaminación del aire"},{"id":"a3","texto":"Sedentarismo"},{"id":"a4","texto":"Ruido"}],"derecha":[{"id":"b1","texto":"Velocidad máxima de 30 km/h en barrios"},{"id":"b2","texto":"Colectivos eléctricos"},{"id":"b3","texto":"Veredas y ciclovías seguras"},{"id":"b4","texto":"Menos autos y motos en calles residenciales"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Muchas medidas de movilidad son, en realidad, medidas de salud pública."}},{"slug":"movilidad-1.s5.p11","orden":11,"grupo":"movilidad-1.s5.p11","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Quién es un usuario vulnerable de la vía pública?","grupos":[{"id":"g1","nombre":"Vulnerable"},{"id":"g2","nombre":"Menos vulnerable"}],"items":[{"id":"i1","texto":"Peatón"},{"id":"i2","texto":"Conductor de camión"},{"id":"i3","texto":"Ciclista"},{"id":"i4","texto":"Pasajero de un auto con cinturón"},{"id":"i5","texto":"Motociclista"},{"id":"i6","texto":"Niño que cruza la calle"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g1"},"explicacion":"Los que no tienen una carrocería que los proteja son los que más sufren en un choque."}},{"slug":"movilidad-1.s5.p12","orden":12,"grupo":"movilidad-1.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La velocidad es un factor clave en la gravedad de los choques."},{"id":"s2","texto":"Bajar a 30 km/h no cambia nada porque igual hay choques."},{"id":"s3","texto":"Caminar al trabajo puede cubrir la actividad física recomendada."},{"id":"s4","texto":"El tránsito solo afecta a la salud cuando hay choques."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El tránsito es un tema de salud, no solo de tiempo de viaje.","por_opcion":{"s2":"Reduce la cantidad y la gravedad de los choques: salva vidas.","s4":"También por el aire, el ruido y el sedentarismo."}}},{"slug":"movilidad-1.s5.p13","orden":13,"grupo":"movilidad-1.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La energía de un choque crece con el {{0}} de la velocidad; la OMS recomienda al menos {{1}} minutos semanales de actividad física.","banco":[{"id":"w1","texto":"cuadrado"},{"id":"w2","texto":"150"},{"id":"w3","texto":"doble"},{"id":"w4","texto":"30"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos números que conectan movilidad y salud."}}]},{"slug":"movilidad-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: cómo nos movemos","bajada_es":"Modos, emisiones, ocupación, espacio y salud, mezclados.","minutos":8,"pasos":[{"slug":"movilidad-1.s6.p1","orden":1,"grupo":"movilidad-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Cómo nos movemos». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"movilidad-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el viaje de Tomás","bajada_es":"Tomás va a la facultad en auto todos los días. Con los números, compará opciones y armá su plan. Aprobalo para hacer crecer la rama.","minutos":10,"pasos":[{"slug":"movilidad-1.s7.p1","orden":1,"grupo":"movilidad-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["Tomás vive a 12 km de la facultad y va solo en auto, ida y vuelta, 4 días por semana, durante 32 semanas al año. Su auto emite unos 190 g de CO₂e por km. Hay un tren que lo deja a 800 metros de la facultad (41 g por pasajero y km) y su casa está a 600 metros de la estación.","Un compañero vive a dos cuadras y va a la misma facultad en su propio auto."]},"solucion":{}},{"slug":"movilidad-1.s7.p2","orden":2,"grupo":"movilidad-1.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kilómetros recorre Tomás por año para ir y volver de la facultad?","unidad":"km","decimales":0,"contexto":"12 km por tramo, ida y vuelta, 4 días por semana, 32 semanas."},"solucion":{"valor":3072,"tolerancia":61.44,"explicacion":"12 × 2 × 4 × 32 = 3.072 km por año: ida y vuelta, cuatro días, 32 semanas."}},{"slug":"movilidad-1.s7.p3","orden":3,"grupo":"movilidad-1.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de CO₂e emite por año yendo solo en auto? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"3.072 km por año a 190 g por km."},"solucion":{"valor":584,"tolerancia":1,"explicacion":"3.072 × 190 = 583.680 g ≈ 584 kg por año."}},{"slug":"movilidad-1.s7.p4","orden":4,"grupo":"movilidad-1.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si va en tren (41 g por km) y camina el resto, ¿cuántos kg de CO₂e emitiría por año? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"3.072 km por año a 41 g por km en tren."},"solucion":{"valor":126,"tolerancia":1,"explicacion":"3.072 × 41 = 125.952 g ≈ 126 kg por año: casi un 80 % menos. Y suma unos 20 minutos de caminata por día."}},{"slug":"movilidad-1.s7.p5","orden":5,"grupo":"movilidad-1.s7.p5","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las opciones de Tomás por emisiones por año, de más a menos.","items":[{"id":"i1","texto":"Seguir yendo solo en auto"},{"id":"i2","texto":"Compartir el auto con su compañero"},{"id":"i3","texto":"Ir en tren y caminar"},{"id":"i4","texto":"Ir en bici (si hubiera ciclovía segura)"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Compartir el auto ya reduce a la mitad. El tren, casi un 80 %. La bici, casi todo, si la infraestructura lo permite.","valores":{"i1":"≈ 584 kg","i2":"≈ 292 kg por persona","i3":"≈ 126 kg","i4":"≈ 0 kg en el viaje"}}},{"slug":"movilidad-1.s7.p6","orden":6,"grupo":"movilidad-1.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tomás dice que el tren no le conviene porque tiene que caminar 1,4 km en total. ¿Qué dato puede ayudarlo a decidir?","opciones":[{"id":"o1","texto":"Son unos 17 minutos de caminata que cuentan como actividad física"},{"id":"o2","texto":"Que caminar 1,4 km es imposible para una persona sana"},{"id":"o3","texto":"Que el tren emite más que el auto"},{"id":"o4","texto":"Que caminando se gasta más plata que en auto"}]},"solucion":{"clave":["o1"],"explicacion":"1,4 km a 5 km/h son unos 17 minutos: más de la mitad de la actividad diaria que recomienda la OMS, sin buscar tiempo extra.","por_opcion":{"o3":"Emite mucho menos por pasajero: 41 contra 190 g por km."}}},{"slug":"movilidad-1.s7.p7","orden":7,"grupo":"movilidad-1.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá los argumentos que escucha Tomás.","grupos":[{"id":"g1","nombre":"Son válidos para decidir"},{"id":"g2","nombre":"No son válidos"}],"items":[{"id":"i1","texto":"El tren tarda 35 minutos y el auto 30 en hora pico"},{"id":"i2","texto":"El tren no emite porque es eléctrico, así que da igual"},{"id":"i3","texto":"Caminar a la estación suma actividad física"},{"id":"i4","texto":"Si uno solo cambia no sirve para nada"},{"id":"i5","texto":"Compartir el auto divide la nafta y el estacionamiento"},{"id":"i6","texto":"El auto es siempre más rápido que cualquier otra opción"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Decidir con datos: tiempo real, costo, salud y emisiones. Los mitos no ayudan."}},{"slug":"movilidad-1.s7.p8","orden":8,"grupo":"movilidad-1.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Tomás escribe su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Tres días por semana voy en tren y camino a la facultad."},{"id":"s2","texto":"El día que voy en auto, lo comparto con mi compañero."},{"id":"s3","texto":"Como el tren emite algo, da lo mismo que el auto."},{"id":"s4","texto":"Para compensar, compro un segundo auto más chico para los días de lluvia."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Un buen plan combina opciones realistas y compara con números.","por_opcion":{"s3":"El tren emite unas cuatro veces menos por km: no da lo mismo.","s4":"Fabricar y mantener otro auto suma impacto; mejor combinar tren y auto compartido."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"movilidad-2","rama":"movilidad","orden":2,"nivel":1,"titulo_es":"Caminar y pedalear","bajada_es":"La forma de moverse más eficiente que existe funciona con tus piernas. Cómo usarla en la ciudad con seguridad, y por qué te hace bien.","objetivos_es":["Evaluar la bicicleta como medio de transporte cotidiano","Relacionar la movilidad activa con las recomendaciones de actividad física de la OMS","Aplicar pautas de seguridad para peatones y ciclistas","Describir las características de una ciudad caminable","Planificar viajes que combinen modos activos y transporte público"],"repasa":["movilidad-1","tronco-3"],"requiere_tronco":1,"fuentes":["oms-actividad-fisica","oms-seguridad-vial","owid-transporte","oms-aire-exterior"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"movilidad-2.s1","orden":1,"tipo":"leccion","titulo_es":"La bici como transporte","bajada_es":"Velocidad, alcance, costo y eficiencia: por qué la bicicleta es una de las mejores máquinas que se inventaron.","minutos":11,"pasos":[{"slug":"movilidad-2.s1.p1","orden":1,"grupo":"movilidad-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una máquina muy eficiente","cuerpo":["La bicicleta es uno de los medios de transporte más eficientes que existen: con la energía de un sándwich, una persona puede recorrer varios kilómetros. No emite gases al andar, casi no hace ruido, ocupa poco lugar y es barata de mantener.","En la ciudad, una bici se mueve a unos 12 a 18 km por hora. Para trayectos de hasta 5 a 8 km suele ser tan rápida como el auto o el colectivo en horas pico, puerta a puerta."]},"solucion":{}},{"slug":"movilidad-2.s1.p2","orden":2,"grupo":"movilidad-2.s1.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ventajas tiene la bicicleta en la ciudad? Marcá todas.","opciones":[{"id":"o1","texto":"No emite gases al andar"},{"id":"o2","texto":"Ocupa poco espacio"},{"id":"o3","texto":"Es barata de mantener"},{"id":"o4","texto":"Suma actividad física"},{"id":"o5","texto":"Protege de la lluvia como un auto"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Tiene muchas ventajas; la lluvia y las distancias largas son sus límites, que se resuelven combinando modos o con la ropa adecuada."}},{"slug":"movilidad-2.s1.p3","orden":3,"grupo":"movilidad-2.s1.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos tarda en bici alguien que hace 4 km a 15 km por hora?","unidad":"minutos","decimales":0},"solucion":{"valor":16,"tolerancia":0.5,"explicacion":"4 ÷ 15 × 60 = 16 minutos, puerta a puerta y sin buscar estacionamiento."}},{"slug":"movilidad-2.s1.p3.v2","orden":3,"grupo":"movilidad-2.s1.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos tarda en bici alguien que hace 6 km a 15 km por hora?","unidad":"minutos","decimales":0},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"6 ÷ 15 × 60 = 24 minutos, puerta a puerta y sin buscar estacionamiento."}},{"slug":"movilidad-2.s1.p3.v3","orden":3,"grupo":"movilidad-2.s1.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos tarda en bici alguien que hace 8 km a 15 km por hora?","unidad":"minutos","decimales":0},"solucion":{"valor":32,"tolerancia":0.64,"explicacion":"8 ÷ 15 × 60 = 32 minutos, puerta a puerta y sin buscar estacionamiento."}},{"slug":"movilidad-2.s1.p4","orden":4,"grupo":"movilidad-2.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto cuesta","cuerpo":["Mantener una bicicleta cuesta una fracción de lo que cuesta un auto: no usa combustible, no paga estacionamiento y los repuestos son baratos. Para muchas personas, pedalear también reemplaza el pasaje del colectivo en trayectos cortos.","Existen sistemas de bicicletas públicas en varias ciudades argentinas, que permiten usar una bici sin comprarla."]},"solucion":{}},{"slug":"movilidad-2.s1.p5","orden":5,"grupo":"movilidad-2.s1.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alguien paga $700 por pasaje y hace 2 viajes por día, 20 días por mes. Si reemplaza esos viajes por la bici, ¿cuánto ahorra por mes?","unidad":"$","decimales":0},"solucion":{"valor":28000,"tolerancia":560,"explicacion":"700 × 2 × 20 = $28.000 por mes. En pocos meses puede pagar una bici usada."}},{"slug":"movilidad-2.s1.p5.v2","orden":5,"grupo":"movilidad-2.s1.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alguien paga $900 por pasaje y hace 2 viajes por día, 22 días por mes. Si reemplaza esos viajes por la bici, ¿cuánto ahorra por mes?","unidad":"$","decimales":0},"solucion":{"valor":39600,"tolerancia":792,"explicacion":"900 × 2 × 22 = $39.600 por mes. En pocos meses puede pagar una bici usada."}},{"slug":"movilidad-2.s1.p5.v3","orden":5,"grupo":"movilidad-2.s1.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alguien paga $500 por pasaje y hace 2 viajes por día, 18 días por mes. Si reemplaza esos viajes por la bici, ¿cuánto ahorra por mes?","unidad":"$","decimales":0},"solucion":{"valor":18000,"tolerancia":360,"explicacion":"500 × 2 × 18 = $18.000 por mes. En pocos meses puede pagar una bici usada."}},{"slug":"movilidad-2.s1.p6","orden":6,"grupo":"movilidad-2.s1.p6","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Para qué viaje suele ser buena la bici y para cuál no tanto?","grupos":[{"id":"g1","nombre":"Buena opción"},{"id":"g2","nombre":"No tanto"}],"items":[{"id":"i1","texto":"5 km a la escuela por una ciclovía"},{"id":"i2","texto":"Mudanza con muebles"},{"id":"i3","texto":"Compras chicas en el barrio"},{"id":"i4","texto":"60 km por ruta sin banquina"},{"id":"i5","texto":"Ir hasta la estación de tren"},{"id":"i6","texto":"Llevar a tres chicos chicos a la vez sin equipamiento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La bici es ideal para trayectos cortos y medianos. Para otros viajes, conviene combinar."}},{"slug":"movilidad-2.s1.p7","orden":7,"grupo":"movilidad-2.s1.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La bicicleta solo sirve para hacer deporte, no para moverse en la ciudad.","razones":[{"id":"r1","texto":"Porque en trayectos cortos y medianos es rápida y barata"},{"id":"r2","texto":"Porque las bicis no pueden andar en la ciudad"},{"id":"r3","texto":"Porque la bici es más lenta que caminar"}]},"solucion":{"valor":false,"explicacion":"En muchas ciudades del mundo es un medio de transporte cotidiano. En trayectos cortos y medianos es rápida, barata y eficiente.","clave":["r1"]}},{"slug":"movilidad-2.s1.p8","orden":8,"grupo":"movilidad-2.s1.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué hace falta para pedalear","cuerpo":["Para que la bici sea una opción real hacen falta varias cosas: ciclovías seguras y conectadas, lugares donde estacionarla sin que la roben, poder llevarla en el tren o dejarla en la estación, y lugares para cambiarse o higienizarse en trabajos y escuelas.","Cuando esas condiciones existen, mucha más gente pedalea."]},"solucion":{}},{"slug":"movilidad-2.s1.p9","orden":9,"grupo":"movilidad-2.s1.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que más personas usen la bici para ir al trabajo? Marcá todo.","opciones":[{"id":"o1","texto":"Ciclovías seguras y conectadas"},{"id":"o2","texto":"Bicicleteros seguros en el destino"},{"id":"o3","texto":"Poder combinarla con el tren"},{"id":"o4","texto":"Vestuarios o lugares para cambiarse"},{"id":"o5","texto":"Que no haya ciclovías para que los autos vayan más rápido"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La infraestructura convierte la bici de opción teórica en opción real."}},{"slug":"movilidad-2.s1.p10","orden":10,"grupo":"movilidad-2.s1.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué una ciclovía conectada aumenta el uso de la bici.","items":[{"id":"i1","texto":"Se construye una ciclovía protegida y continua"},{"id":"i2","texto":"Pedalear se vuelve más seguro"},{"id":"i3","texto":"Más personas se animan a usar la bici"},{"id":"i4","texto":"Más gente pedaleando hace que los conductores estén más atentos"},{"id":"i5","texto":"Pedalear se vuelve todavía más seguro y común"},{"id":"i6","texto":"La ciclovía hace que las bicis vayan a 60 km/h"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un círculo virtuoso: más seguridad, más ciclistas, más seguridad. Se lo llama \"seguridad en números\"."}},{"slug":"movilidad-2.s1.p11","orden":11,"grupo":"movilidad-2.s1.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una empresa quiere que más empleados vayan en bici. ¿Qué medida conviene primero?","opciones":[{"id":"o1","texto":"Poner un bicicletero seguro y techado"},{"id":"o2","texto":"Pedirles que vengan en bici sin cambiar nada"},{"id":"o3","texto":"Comprarles cascos a todos"},{"id":"o4","texto":"Ampliar el estacionamiento de autos"}]},"solucion":{"clave":["o1"],"explicacion":"Sin un lugar seguro donde dejarla, pocos se arriesgan a que les roben la bici.","por_opcion":{"o3":"El casco ayuda, pero si no hay dónde dejar la bici segura, casi nadie la usa."}}},{"slug":"movilidad-2.s1.p12","orden":12,"grupo":"movilidad-2.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La bici no emite gases al andar."},{"id":"s2","texto":"Pedalear 5 km lleva más de una hora."},{"id":"s3","texto":"Hacen falta bicicleteros seguros para que la gente pedalee."},{"id":"s4","texto":"Si hay más ciclistas, las calles son más peligrosas para ellos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La bici es más rápida y más segura de lo que muchos creen, cuando la ciudad acompaña.","por_opcion":{"s2":"A 15 km/h, 5 km son unos 20 minutos.","s4":"Suele ser al revés: con más ciclistas, los conductores están más atentos."}}},{"slug":"movilidad-2.s1.p13","orden":13,"grupo":"movilidad-2.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En la ciudad, una bici se mueve a unos {{0}} km por hora; para que la gente la use hacen falta ciclovías {{1}} y bicicleteros {{2}}.","banco":[{"id":"w1","texto":"15"},{"id":"w2","texto":"conectadas"},{"id":"w3","texto":"seguros"},{"id":"w4","texto":"60"},{"id":"w5","texto":"aisladas"},{"id":"w6","texto":"pintados"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Velocidad y condiciones para pedalear en la ciudad."}}]},{"slug":"movilidad-2.s2","orden":2,"tipo":"leccion","titulo_es":"Moverse es salud","bajada_es":"Actividad física, recomendaciones de la OMS y por qué los beneficios de pedalear superan los riesgos.","minutos":11,"pasos":[{"slug":"movilidad-2.s2.p1","orden":1,"grupo":"movilidad-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que recomienda la OMS","cuerpo":["La Organización Mundial de la Salud recomienda que las personas adultas hagan entre 150 y 300 minutos semanales de actividad física moderada (como caminar rápido o pedalear tranquilo), o entre 75 y 150 minutos de actividad intensa. Para niños, niñas y adolescentes, un promedio de 60 minutos por día.","Sin embargo, en el mundo casi un tercio de las personas adultas no llega a esos niveles."],"destacado":{"valor":"150-300 min","texto":"por semana de actividad moderada recomienda la OMS para las personas adultas."}},"solucion":{}},{"slug":"movilidad-2.s2.p2","orden":2,"grupo":"movilidad-2.s2.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada grupo con lo que recomienda la OMS.","izquierda":[{"id":"a1","texto":"Personas adultas (moderada)"},{"id":"a2","texto":"Personas adultas (intensa)"},{"id":"a3","texto":"Niños, niñas y adolescentes"}],"derecha":[{"id":"b1","texto":"150 a 300 minutos por semana"},{"id":"b2","texto":"75 a 150 minutos por semana"},{"id":"b3","texto":"Un promedio de 60 minutos por día"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Recomendaciones simples que la movilidad activa puede cubrir sin buscar tiempo extra."}},{"slug":"movilidad-2.s2.p3","orden":3,"grupo":"movilidad-2.s2.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alguien pedalea 12 minutos de ida y 12 de vuelta al trabajo, 5 días por semana. ¿Cuántos minutos de actividad suma por semana?","unidad":"minutos","decimales":0},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"12 × 2 × 5 = 120 minutos. Le faltan 30 minutos para los 150 semanales."}},{"slug":"movilidad-2.s2.p3.v2","orden":3,"grupo":"movilidad-2.s2.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alguien pedalea 20 minutos de ida y 20 de vuelta al trabajo, 5 días por semana. ¿Cuántos minutos de actividad suma por semana?","unidad":"minutos","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"20 × 2 × 5 = 200 minutos. Cumple la recomendación mínima de la OMS solo con ir y volver."}},{"slug":"movilidad-2.s2.p3.v3","orden":3,"grupo":"movilidad-2.s2.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alguien pedalea 8 minutos de ida y 8 de vuelta al trabajo, 4 días por semana. ¿Cuántos minutos de actividad suma por semana?","unidad":"minutos","decimales":0},"solucion":{"valor":64,"tolerancia":1.28,"explicacion":"8 × 2 × 4 = 64 minutos. Le faltan 86 minutos para los 150 semanales."}},{"slug":"movilidad-2.s2.p4","orden":4,"grupo":"movilidad-2.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Beneficios","cuerpo":["La actividad física regular reduce el riesgo de enfermedades del corazón, accidentes cerebrovasculares, diabetes tipo 2, varios tipos de cáncer, depresión y ansiedad, y mejora el sueño y la memoria. En niños y adolescentes, ayuda al desarrollo de huesos y músculos y al rendimiento escolar.","La inactividad física, en cambio, está entre los principales factores de riesgo de muerte prematura en el mundo."]},"solucion":{}},{"slug":"movilidad-2.s2.p5","orden":5,"grupo":"movilidad-2.s2.p5","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios tiene la actividad física regular según la OMS? Marcá todos.","opciones":[{"id":"o1","texto":"Menos riesgo de enfermedades del corazón"},{"id":"o2","texto":"Menos riesgo de diabetes tipo 2"},{"id":"o3","texto":"Mejor salud mental"},{"id":"o4","texto":"Mejor sueño"},{"id":"o5","texto":"Inmunidad total a cualquier enfermedad"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Muchos beneficios comprobados, sin ser una vacuna contra todo."}},{"slug":"movilidad-2.s2.p6","orden":6,"grupo":"movilidad-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"¿Y el aire contaminado?","cuerpo":["Una duda común: si se pedalea entre autos, ¿no se respira más contaminación? Es cierto que se respira más aire al hacer ejercicio. Pero los estudios encuentran que, en la gran mayoría de las ciudades, los beneficios de la actividad física superan con creces el daño del aire contaminado que se respira en el camino.","Además, elegir calles con menos tránsito, paralelas a las avenidas, reduce mucho la exposición."]},"solucion":{}},{"slug":"movilidad-2.s2.p7","orden":7,"grupo":"movilidad-2.s2.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como en la calle hay contaminación, pedalear hace más daño que bien a la salud.","razones":[{"id":"r1","texto":"Porque los beneficios de la actividad superan el daño del aire en casi todas las ciudades"},{"id":"r2","texto":"Porque el aire de las calles es siempre limpio"},{"id":"r3","texto":"Porque los ciclistas no respiran mientras pedalean"}]},"solucion":{"valor":false,"explicacion":"En la gran mayoría de las ciudades, los beneficios de la actividad física superan el daño del aire. Y elegir calles tranquilas reduce la exposición.","clave":["r1"]}},{"slug":"movilidad-2.s2.p8","orden":8,"grupo":"movilidad-2.s2.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Para ir en bici al trabajo respirando menos contaminación, ¿qué conviene?","opciones":[{"id":"o1","texto":"Elegir calles paralelas a las avenidas"},{"id":"o2","texto":"Ir pegado a los caños de escape de los colectivos"},{"id":"o3","texto":"Pedalear más rápido para llegar antes"},{"id":"o4","texto":"Ir por la avenida con más tránsito porque es más directa"}]},"solucion":{"clave":["o1"],"explicacion":"A pocas cuadras de una avenida, la contaminación baja mucho. El recorrido importa.","por_opcion":{"o3":"Pedalear más fuerte aumenta la respiración; lo que más cambia la exposición es el recorrido."}}},{"slug":"movilidad-2.s2.p9","orden":9,"grupo":"movilidad-2.s2.p9","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta forma de viajar cuenta como actividad física?","grupos":[{"id":"g1","nombre":"Cuenta"},{"id":"g2","nombre":"No cuenta"}],"items":[{"id":"i1","texto":"Caminar 15 minutos hasta la estación"},{"id":"i2","texto":"Ir sentado en el auto"},{"id":"i3","texto":"Pedalear a la escuela"},{"id":"i4","texto":"Esperar el colectivo sentado"},{"id":"i5","texto":"Subir escaleras en vez de tomar el ascensor"},{"id":"i6","texto":"Usar un monopatín eléctrico sin pedalear"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La movilidad activa suma minutos sin buscar tiempo extra en el día."}},{"slug":"movilidad-2.s2.p10","orden":10,"grupo":"movilidad-2.s2.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo ir en bici a la escuela afecta la salud de un adolescente.","items":[{"id":"i1","texto":"Va en bici 15 minutos de ida y 15 de vuelta"},{"id":"i2","texto":"Suma 30 minutos diarios de actividad física"},{"id":"i3","texto":"Se acerca a los 60 minutos que recomienda la OMS"},{"id":"i4","texto":"Mejora su salud física y mental"},{"id":"i5","texto":"Llega tan cansado que no puede estudiar"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un hábito de transporte que es también un hábito de salud. Como viste en el tronco: disparador, rutina, recompensa."}},{"slug":"movilidad-2.s2.p11","orden":11,"grupo":"movilidad-2.s2.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La OMS recomienda al menos 150 minutos semanales de actividad moderada para adultos."},{"id":"s2","texto":"Caminar a la estación no cuenta como actividad física."},{"id":"s3","texto":"Pedalear por calles tranquilas reduce la contaminación que se respira."},{"id":"s4","texto":"Los chicos no necesitan actividad física diaria."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Moverse para llegar es también moverse para estar bien.","por_opcion":{"s2":"Caminar a paso ligero cuenta como actividad moderada.","s4":"La OMS recomienda un promedio de 60 minutos por día para niños y adolescentes."}}},{"slug":"movilidad-2.s2.p12","orden":12,"grupo":"movilidad-2.s2.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La OMS recomienda a los adultos entre {{0}} y 300 minutos semanales de actividad moderada, y a los chicos un promedio de {{1}} minutos por día.","banco":[{"id":"w1","texto":"150"},{"id":"w2","texto":"60"},{"id":"w3","texto":"15"},{"id":"w4","texto":"6"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos números para recordar sobre actividad física."}},{"slug":"movilidad-2.s2.p13","orden":13,"grupo":"movilidad-2.s2.p13","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las personas adultas del mundo no llega a la actividad física recomendada por la OMS.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":31,"banda":"lineal","explicacion":"Alrededor de un tercio, según la OMS. La movilidad activa es una de las formas más simples de cambiarlo."}}]},{"slug":"movilidad-2.s3","orden":3,"tipo":"leccion","titulo_es":"Seguridad para peatones y ciclistas","bajada_es":"Velocidad, puntos ciegos, luces y ciclovías: cómo moverse más seguro y qué hace una ciudad segura.","minutos":11,"pasos":[{"slug":"movilidad-2.s3.p1","orden":1,"grupo":"movilidad-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La velocidad otra vez","cuerpo":["Según la OMS, cada kilómetro por hora de aumento de la velocidad media aumenta alrededor de un 3 % el riesgo de choques con heridos y entre un 4 y un 5 % el de choques con víctimas fatales. Por eso bajar la velocidad en zonas con peatones y ciclistas es una de las medidas más efectivas.","Pero la seguridad no depende solo de cada persona: el diseño de las calles —cruces cortos, ciclovías separadas, reductores de velocidad— evita que los errores humanos terminen en muertes."]},"solucion":{}},{"slug":"movilidad-2.s3.p2","orden":2,"grupo":"movilidad-2.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada 1 km/h de aumento de la velocidad media sube alrededor de un 4 % el riesgo de choques fatales, ¿aproximadamente cuánto sube ese riesgo con 10 km/h más? (Sumá simple, sin interés compuesto)","unidad":"%","decimales":0},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"10 × 4 = 40 %. Es una aproximación, pero muestra por qué unos pocos km/h importan tanto."}},{"slug":"movilidad-2.s3.p2.v2","orden":2,"grupo":"movilidad-2.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada 1 km/h de aumento de la velocidad media sube alrededor de un 4 % el riesgo de choques fatales, ¿aproximadamente cuánto sube ese riesgo con 5 km/h más? (Sumá simple, sin interés compuesto)","unidad":"%","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"5 × 4 = 20 %. Es una aproximación, pero muestra por qué unos pocos km/h importan tanto."}},{"slug":"movilidad-2.s3.p2.v3","orden":2,"grupo":"movilidad-2.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada 1 km/h de aumento de la velocidad media sube alrededor de un 4 % el riesgo de choques fatales, ¿aproximadamente cuánto sube ese riesgo con 20 km/h más? (Sumá simple, sin interés compuesto)","unidad":"%","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"20 × 4 = 80 %. Es una aproximación, pero muestra por qué unos pocos km/h importan tanto."}},{"slug":"movilidad-2.s3.p3","orden":3,"grupo":"movilidad-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El punto ciego","cuerpo":["Los colectivos y los camiones tienen puntos ciegos: zonas alrededor del vehículo que el conductor no ve, ni siquiera con los espejos. Son especialmente peligrosos al costado derecho y justo adelante. Muchos siniestros graves con ciclistas ocurren cuando un camión o colectivo dobla a la derecha.","Regla práctica: si no ves los ojos del conductor en su espejo, él no te ve."]},"solucion":{}},{"slug":"movilidad-2.s3.p4","orden":4,"grupo":"movilidad-2.s3.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Estás en bici junto a un colectivo detenido en un semáforo que va a doblar a la derecha. ¿Qué es lo más seguro?","opciones":[{"id":"o1","texto":"Quedarte detrás hasta que doble"},{"id":"o2","texto":"Ponerte a su derecha para arrancar primero"},{"id":"o3","texto":"Pasarlo rápido por la derecha antes de que arranque"},{"id":"o4","texto":"Tocar timbre y confiar en que te vea"}]},"solucion":{"clave":["o1"],"explicacion":"Nunca te quedes al costado derecho de un vehículo grande que puede doblar: es su punto ciego.","por_opcion":{"o3":"Es la zona del punto ciego: el conductor puede no verte al doblar."}}},{"slug":"movilidad-2.s3.p5","orden":5,"grupo":"movilidad-2.s3.p5","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más visible y seguro a un ciclista? Marcá todo.","opciones":[{"id":"o1","texto":"Luz blanca adelante y roja atrás de noche"},{"id":"o2","texto":"Ropa o elementos reflectivos"},{"id":"o3","texto":"Casco bien colocado"},{"id":"o4","texto":"Señalizar con el brazo antes de doblar"},{"id":"o5","texto":"Andar con auriculares a todo volumen"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Ver y ser visto, y avisar lo que vas a hacer. Los auriculares a todo volumen quitan un sentido clave."}},{"slug":"movilidad-2.s3.p6","orden":6,"grupo":"movilidad-2.s3.p6","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una práctica segura o riesgosa para un ciclista?","grupos":[{"id":"g1","nombre":"Segura"},{"id":"g2","nombre":"Riesgosa"}],"items":[{"id":"i1","texto":"Circular en el sentido del tránsito"},{"id":"i2","texto":"Ir de contramano por la calle"},{"id":"i3","texto":"Usar la ciclovía cuando existe"},{"id":"i4","texto":"Zigzaguear entre autos en movimiento"},{"id":"i5","texto":"Frenar antes de cruzar una bocacalle"},{"id":"i6","texto":"Cruzar en rojo porque \"no viene nadie\""}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Ser predecible es la mejor protección: que los demás sepan qué vas a hacer."}},{"slug":"movilidad-2.s3.p7","orden":7,"grupo":"movilidad-2.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Peatones","cuerpo":["Los peatones son los usuarios más vulnerables. Cruzar por la senda peatonal y con el semáforo, mirar a ambos lados aunque la calle sea de una mano, no cruzar mirando el celular y hacerse visible de noche reducen los riesgos.","Del lado de la ciudad, las esquinas con veredas ensanchadas, las sendas bien pintadas, los semáforos con tiempo suficiente para cruzar y los reductores de velocidad protegen a todos, sobre todo a chicos y personas mayores."]},"solucion":{}},{"slug":"movilidad-2.s3.p8","orden":8,"grupo":"movilidad-2.s3.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada elemento de la calle con cómo protege al peatón.","izquierda":[{"id":"a1","texto":"Esquina con vereda ensanchada"},{"id":"a2","texto":"Reductor de velocidad"},{"id":"a3","texto":"Semáforo con tiempo suficiente"},{"id":"a4","texto":"Isla en el medio de la avenida"}],"derecha":[{"id":"b1","texto":"Acorta el cruce y hace doblar más despacio"},{"id":"b2","texto":"Obliga a los autos a ir más lento"},{"id":"b3","texto":"Permite cruzar sin correr"},{"id":"b4","texto":"Permite cruzar en dos etapas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El diseño de la calle puede perdonar errores humanos. Es la idea de \"sistema seguro\"."}},{"slug":"movilidad-2.s3.p9","orden":9,"grupo":"movilidad-2.s3.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La seguridad vial depende solo de que cada persona tenga cuidado.","razones":[{"id":"r1","texto":"Porque el diseño de las calles y la velocidad también la determinan"},{"id":"r2","texto":"Porque los accidentes son inevitables"},{"id":"r3","texto":"Porque solo los conductores de camiones son responsables"}]},"solucion":{"valor":false,"explicacion":"El comportamiento importa, pero el diseño de las calles y los límites de velocidad hacen que los errores no terminen en muertes. Es la idea de sistema seguro.","clave":["r1"]}},{"slug":"movilidad-2.s3.p10","orden":10,"grupo":"movilidad-2.s3.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una esquina con vereda ensanchada protege a un chico que cruza.","items":[{"id":"i1","texto":"Se ensancha la vereda en la esquina"},{"id":"i2","texto":"La distancia para cruzar se acorta"},{"id":"i3","texto":"Los autos doblan más cerrados y más despacio"},{"id":"i4","texto":"El chico está menos tiempo en la calzada"},{"id":"i5","texto":"Baja el riesgo de que lo atropellen"},{"id":"i6","texto":"La vereda ancha hace que los autos no puedan doblar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Pequeños cambios de diseño con grandes efectos en la seguridad."}},{"slug":"movilidad-2.s3.p11","orden":11,"grupo":"movilidad-2.s3.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de un folleto y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Usá luces adelante y atrás si pedaleás de noche."},{"id":"s2","texto":"Andá de contramano para ver venir a los autos."},{"id":"s3","texto":"Nunca te quedes al costado derecho de un camión que va a doblar."},{"id":"s4","texto":"Si la calle es de una mano, alcanza con mirar para un solo lado."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Ser visible, predecible y atento, en calles diseñadas para perdonar errores.","por_opcion":{"s2":"Ir de contramano es impredecible y aumenta mucho el riesgo de choque.","s4":"Puede venir una bici de contramano o un vehículo en reversa: siempre mirar a ambos lados."}}},{"slug":"movilidad-2.s3.p12","orden":12,"grupo":"movilidad-2.s3.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Si no ves los ojos del conductor en su {{0}}, él no te ve; en bici hay que circular en el {{1}} del tránsito.","banco":[{"id":"w1","texto":"espejo"},{"id":"w2","texto":"sentido"},{"id":"w3","texto":"celular"},{"id":"w4","texto":"contrario"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos reglas simples que evitan muchos siniestros."}},{"slug":"movilidad-2.s3.p13","orden":13,"grupo":"movilidad-2.s3.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas medidas por su efecto sobre la seguridad de peatones y ciclistas en un barrio, de más a menos.","items":[{"id":"i1","texto":"Bajar la velocidad máxima a 30 km/h y hacerla cumplir"},{"id":"i2","texto":"Ciclovías separadas del tránsito"},{"id":"i3","texto":"Mejorar la iluminación de las esquinas"},{"id":"i4","texto":"Carteles que piden \"precaución\""}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las medidas que cambian la velocidad y el espacio funcionan mucho más que los carteles.","valores":{"i1":"efecto muy grande","i2":"efecto grande","i3":"efecto moderado","i4":"efecto chico"}}}]},{"slug":"movilidad-2.s4","orden":4,"tipo":"leccion","titulo_es":"Ciudades caminables","bajada_es":"Veredas, sombra, cruces y cercanía: qué hace que una ciudad invite a caminar, y la idea de la ciudad de 15 minutos.","minutos":11,"pasos":[{"slug":"movilidad-2.s4.p1","orden":1,"grupo":"movilidad-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué hace caminable a una ciudad","cuerpo":["Una ciudad es caminable cuando caminar es seguro, cómodo e interesante. Eso depende de veredas anchas y sin obstáculos, cruces seguros y cortos, sombra de árboles, bancos para descansar, buena iluminación y, sobre todo, de que haya cosas cerca: comercios, escuelas, plazas y servicios a distancias caminables.","Las personas mayores, los chicos y quienes usan silla de ruedas o cochecito son los que más dependen de una ciudad caminable."]},"solucion":{}},{"slug":"movilidad-2.s4.p2","orden":2,"grupo":"movilidad-2.s4.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que una calle invite a caminar? Marcá todo.","opciones":[{"id":"o1","texto":"Veredas anchas y sin pozos"},{"id":"o2","texto":"Árboles que den sombra"},{"id":"o3","texto":"Comercios y servicios cerca"},{"id":"o4","texto":"Cruces seguros"},{"id":"o5","texto":"Autos estacionados sobre la vereda"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Comodidad, seguridad y cosas interesantes cerca: la receta de una calle caminable."}},{"slug":"movilidad-2.s4.p3","orden":3,"grupo":"movilidad-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La ciudad de 15 minutos","cuerpo":["La idea de la \"ciudad de 15 minutos\", propuesta por el urbanista Carlos Moreno, plantea que las necesidades cotidianas —trabajo, escuela, comercios, salud, plazas, cultura— deberían estar a unos 15 minutos a pie o en bici desde cada casa.","Para lograrlo, las ciudades mezclan usos (viviendas, comercios y servicios en los mismos barrios) en lugar de separarlos en zonas lejanas, y distribuyen escuelas, centros de salud y plazas en todos los barrios."]},"solucion":{}},{"slug":"movilidad-2.s4.p4","orden":4,"grupo":"movilidad-2.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"A 5 km por hora, ¿cuántos kilómetros se recorren caminando en 15 minutos? Redondeá a dos decimales.","unidad":"km","decimales":2},"solucion":{"valor":1.25,"tolerancia":0.02,"explicacion":"5 × 15 ÷ 60 ≈ 1,25 km. Ese es el radio de una \"ciudad de 15 minutos\" a pie."}},{"slug":"movilidad-2.s4.p4.v2","orden":4,"grupo":"movilidad-2.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"A 5 km por hora, ¿cuántos kilómetros se recorren caminando en 10 minutos? Redondeá a dos decimales.","unidad":"km","decimales":2},"solucion":{"valor":0.83,"tolerancia":0.02,"explicacion":"5 × 10 ÷ 60 ≈ 0,83 km. Ese es el radio de una \"ciudad de 10 minutos\" a pie."}},{"slug":"movilidad-2.s4.p4.v3","orden":4,"grupo":"movilidad-2.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"A 5 km por hora, ¿cuántos kilómetros se recorren caminando en 20 minutos? Redondeá a dos decimales.","unidad":"km","decimales":2},"solucion":{"valor":1.67,"tolerancia":0.02,"explicacion":"5 × 20 ÷ 60 ≈ 1,67 km. Ese es el radio de una \"ciudad de 20 minutos\" a pie."}},{"slug":"movilidad-2.s4.p5","orden":5,"grupo":"movilidad-2.s4.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué mezclar usos en un barrio reduce los viajes en auto.","items":[{"id":"i1","texto":"Se permiten comercios y servicios entre las viviendas"},{"id":"i2","texto":"Las cosas cotidianas quedan cerca"},{"id":"i3","texto":"Muchos viajes se vuelven caminables"},{"id":"i4","texto":"Menos personas necesitan el auto para lo diario"},{"id":"i5","texto":"Mezclar usos hace que las casas queden más lejos"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La distancia es la variable que más influye en cómo nos movemos. Acercar las cosas cambia todo."}},{"slug":"movilidad-2.s4.p6","orden":6,"grupo":"movilidad-2.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Separar las zonas de vivienda, de comercio y de trabajo reduce los viajes.","razones":[{"id":"r1","texto":"Porque separar usos alarga las distancias"},{"id":"r2","texto":"Porque las personas nunca van de compras"},{"id":"r3","texto":"Porque separar usos acorta todos los viajes"}]},"solucion":{"valor":false,"explicacion":"Al separar los usos, las distancias crecen y los viajes se alargan, sobre todo en auto. Mezclarlos acerca las cosas.","clave":["r1"]}},{"slug":"movilidad-2.s4.p7","orden":7,"grupo":"movilidad-2.s4.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esto hace a un barrio más caminable o menos?","grupos":[{"id":"g1","nombre":"Más caminable"},{"id":"g2","nombre":"Menos caminable"}],"items":[{"id":"i1","texto":"Una verdulería a dos cuadras"},{"id":"i2","texto":"Un shopping al que solo se llega por autopista"},{"id":"i3","texto":"Árboles en todas las veredas"},{"id":"i4","texto":"Veredas ocupadas por autos estacionados"},{"id":"i5","texto":"Esquinas con rampas"},{"id":"i6","texto":"Cuadras de 400 metros sin cruces"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cercanía, comodidad y continuidad hacen que caminar sea la opción obvia."}},{"slug":"movilidad-2.s4.p8","orden":8,"grupo":"movilidad-2.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Accesibilidad universal","cuerpo":["Una ciudad caminable tiene que serlo para todos: personas con discapacidad, personas mayores, familias con cochecitos. Eso requiere rampas en las esquinas, veredas sin escalones ni pozos, semáforos con sonido para personas ciegas y transporte público accesible.","Lo que se diseña pensando en quien tiene más dificultades termina siendo mejor para todos."]},"solucion":{}},{"slug":"movilidad-2.s4.p9","orden":9,"grupo":"movilidad-2.s4.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada elemento de accesibilidad con a quién ayuda más.","izquierda":[{"id":"a1","texto":"Rampa en la esquina"},{"id":"a2","texto":"Semáforo sonoro"},{"id":"a3","texto":"Bancos cada pocas cuadras"},{"id":"a4","texto":"Colectivo de piso bajo"}],"derecha":[{"id":"b1","texto":"Personas en silla de ruedas y con cochecitos"},{"id":"b2","texto":"Personas ciegas"},{"id":"b3","texto":"Personas mayores"},{"id":"b4","texto":"Personas con movilidad reducida"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Diseñar para todos es, al final, diseñar mejor para cada persona."}},{"slug":"movilidad-2.s4.p10","orden":10,"grupo":"movilidad-2.s4.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un barrio, las veredas están rotas y llenas de autos estacionados. ¿Qué es lo primero que conviene pedir al municipio?","opciones":[{"id":"o1","texto":"Reparar las veredas y controlar el estacionamiento"},{"id":"o2","texto":"Construir un estacionamiento más grande"},{"id":"o3","texto":"Pintar las veredas de colores"},{"id":"o4","texto":"Poner más carteles de \"respete al peatón\""}]},"solucion":{"clave":["o1"],"explicacion":"Las veredas son la infraestructura básica de la movilidad. Sin ellas, caminar es difícil y peligroso.","por_opcion":{"o3":"Puede ser lindo, pero no resuelve que no se pueda caminar."}}},{"slug":"movilidad-2.s4.p11","orden":11,"grupo":"movilidad-2.s4.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta vecinal y marcá lo que no ayuda a caminar.","segmentos":[{"id":"s1","texto":"Plantar árboles en las veredas para tener sombra."},{"id":"s2","texto":"Permitir estacionar sobre la vereda para que no se llene la calle."},{"id":"s3","texto":"Hacer rampas en todas las esquinas."},{"id":"s4","texto":"Cerrar la verdulería del barrio y abrir un hipermercado a 5 km."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una ciudad caminable acerca las cosas y cuida las veredas.","por_opcion":{"s2":"Las veredas son para las personas: estacionar ahí las bloquea.","s4":"Alejar los comercios obliga a viajar más, y en auto."}}},{"slug":"movilidad-2.s4.p12","orden":12,"grupo":"movilidad-2.s4.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La idea de la ciudad de {{0}} minutos propone tener lo cotidiano cerca; para eso se {{1}} usos en los barrios.","banco":[{"id":"w1","texto":"15"},{"id":"w2","texto":"mezclan"},{"id":"w3","texto":"60"},{"id":"w4","texto":"separan"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La propuesta central de la lección, en una línea."}},{"slug":"movilidad-2.s4.p13","orden":13,"grupo":"movilidad-2.s4.p13","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas distancias a la escuela según qué tan probable es que un chico vaya caminando, de más a menos.","items":[{"id":"i1","texto":"300 metros por veredas buenas"},{"id":"i2","texto":"1 km con un cruce de avenida con semáforo"},{"id":"i3","texto":"2 km por calles sin veredas"},{"id":"i4","texto":"5 km cruzando una autopista"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Distancia y seguridad del recorrido deciden si caminar es una opción.","valores":{"i1":"muy probable","i2":"probable","i3":"poco probable","i4":"casi imposible"}}}]},{"slug":"movilidad-2.s5","orden":5,"tipo":"leccion","titulo_es":"Combinar modos","bajada_es":"Bici más tren, caminar más colectivo: cómo armar viajes largos con modos de baja huella.","minutos":9,"pasos":[{"slug":"movilidad-2.s5.p1","orden":1,"grupo":"movilidad-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La intermodalidad","cuerpo":["Muchos viajes son demasiado largos para hacerlos solo a pie o en bici, pero se pueden combinar: caminar o pedalear hasta la estación, tomar el tren y caminar el último tramo. Combinar modos se llama intermodalidad.","Funciona bien cuando las estaciones tienen bicicleteros seguros, cuando se puede subir la bici al tren, cuando los horarios coinciden y cuando un mismo medio de pago sirve para todo."]},"solucion":{}},{"slug":"movilidad-2.s5.p2","orden":2,"grupo":"movilidad-2.s5.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená un viaje intermodal típico al trabajo.","items":[{"id":"i1","texto":"Pedalear de casa a la estación"},{"id":"i2","texto":"Dejar la bici en el bicicletero"},{"id":"i3","texto":"Viajar en tren"},{"id":"i4","texto":"Caminar desde la estación de destino"},{"id":"i5","texto":"Llegar al trabajo"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Tres modos, un solo viaje. Cada tramo con el modo que mejor le queda."}},{"slug":"movilidad-2.s5.p3","orden":3,"grupo":"movilidad-2.s5.p3","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué facilita combinar la bici con el tren? Marcá todo.","opciones":[{"id":"o1","texto":"Bicicleteros seguros en las estaciones"},{"id":"o2","texto":"Permitir subir la bici al tren"},{"id":"o3","texto":"Ciclovías que lleguen a las estaciones"},{"id":"o4","texto":"Horarios frecuentes"},{"id":"o5","texto":"Estaciones sin ningún acceso para bicis"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La intermodalidad es un sistema: cada pieza tiene que estar."}},{"slug":"movilidad-2.s5.p4","orden":4,"grupo":"movilidad-2.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un viaje combina 3 km en bici, 20 km en tren y 0,8 km a pie. Si el tren emite 41 g por pasajero y km, ¿cuántos gramos de CO₂e emite el viaje?","unidad":"g CO₂e","decimales":0},"solucion":{"valor":820,"tolerancia":16.4,"explicacion":"Solo emite el tramo en tren: 20 × 41 = 820 g. La bici y la caminata no emiten en el viaje."}},{"slug":"movilidad-2.s5.p4.v2","orden":4,"grupo":"movilidad-2.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un viaje combina 2 km en bici, 25 km en tren y 0,5 km a pie. Si el tren emite 41 g por pasajero y km, ¿cuántos gramos de CO₂e emite el viaje?","unidad":"g CO₂e","decimales":0},"solucion":{"valor":1025,"tolerancia":20.5,"explicacion":"Solo emite el tramo en tren: 25 × 41 = 1.025 g. La bici y la caminata no emiten en el viaje."}},{"slug":"movilidad-2.s5.p4.v3","orden":4,"grupo":"movilidad-2.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un viaje combina 4 km en bici, 15 km en tren y 1 km a pie. Si el tren emite 41 g por pasajero y km, ¿cuántos gramos de CO₂e emite el viaje?","unidad":"g CO₂e","decimales":0},"solucion":{"valor":615,"tolerancia":12.3,"explicacion":"Solo emite el tramo en tren: 15 × 41 = 615 g. La bici y la caminata no emiten en el viaje."}},{"slug":"movilidad-2.s5.p5","orden":5,"grupo":"movilidad-2.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si ese mismo viaje de 23,8 km se hiciera solo en auto (192 g por km), ¿cuántos gramos de CO₂e emitiría? Redondeá al entero.","unidad":"g CO₂e","decimales":0},"solucion":{"valor":4570,"tolerancia":2,"explicacion":"23,8 × 192 ≈ 4.570 g, varias veces más que el viaje combinado."}},{"slug":"movilidad-2.s5.p5.v2","orden":5,"grupo":"movilidad-2.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si ese mismo viaje de 27,5 km se hiciera solo en auto (192 g por km), ¿cuántos gramos de CO₂e emitiría? Redondeá al entero.","unidad":"g CO₂e","decimales":0},"solucion":{"valor":5280,"tolerancia":2,"explicacion":"27,5 × 192 ≈ 5.280 g, varias veces más que el viaje combinado."}},{"slug":"movilidad-2.s5.p5.v3","orden":5,"grupo":"movilidad-2.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si ese mismo viaje de 20 km se hiciera solo en auto (192 g por km), ¿cuántos gramos de CO₂e emitiría? Redondeá al entero.","unidad":"g CO₂e","decimales":0},"solucion":{"valor":3840,"tolerancia":2,"explicacion":"20 × 192 ≈ 3.840 g, varias veces más que el viaje combinado."}},{"slug":"movilidad-2.s5.p6","orden":6,"grupo":"movilidad-2.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La última milla","cuerpo":["El último tramo de un viaje, desde la estación o la parada hasta el destino, se llama \"última milla\". Si es largo, incómodo o inseguro, muchas personas prefieren el auto para todo el viaje.","Mejorar la última milla —veredas, ciclovías, bicis públicas, colectivos de conexión— hace que el transporte público sea una opción real para mucha más gente."]},"solucion":{}},{"slug":"movilidad-2.s5.p7","orden":7,"grupo":"movilidad-2.s5.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué una mala última milla hace que se elija el auto.","items":[{"id":"i1","texto":"La estación queda a 2 km del trabajo sin colectivo de conexión"},{"id":"i2","texto":"El último tramo es largo e incómodo"},{"id":"i3","texto":"El viaje en tren pierde atractivo"},{"id":"i4","texto":"La persona elige ir en auto todo el trayecto"},{"id":"i5","texto":"El tren llega más rápido porque la estación está lejos"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un eslabón débil arruina toda la cadena. Por eso se mejora la conexión con la estación."}},{"slug":"movilidad-2.s5.p8","orden":8,"grupo":"movilidad-2.s5.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida mejora la última milla o no?","grupos":[{"id":"g1","nombre":"La mejora"},{"id":"g2","nombre":"No la mejora"}],"items":[{"id":"i1","texto":"Estación de bicis públicas en la salida del tren"},{"id":"i2","texto":"Estacionamiento más grande para autos en el centro"},{"id":"i3","texto":"Vereda ancha e iluminada hasta el polo industrial"},{"id":"i4","texto":"Cerrar la salida lateral de la estación"},{"id":"i5","texto":"Colectivo de conexión que espera al tren"},{"id":"i6","texto":"Quitar la parada de colectivo frente a la estación"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La última milla es donde se gana o se pierde a un pasajero."}},{"slug":"movilidad-2.s5.p9","orden":9,"grupo":"movilidad-2.s5.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el tren es rápido, no importa cómo se llega a la estación.","razones":[{"id":"r1","texto":"Porque la experiencia de todo el viaje decide qué modo se elige"},{"id":"r2","texto":"Porque los trenes llegan a la puerta de cada casa"},{"id":"r3","texto":"Porque nadie camina hasta las estaciones"}]},"solucion":{"valor":false,"explicacion":"Si llegar a la estación o del tren al destino es difícil, muchas personas eligen el auto. La calidad de todo el recorrido cuenta.","clave":["r1"]}},{"slug":"movilidad-2.s5.p10","orden":10,"grupo":"movilidad-2.s5.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una persona vive a 2,5 km de la estación de tren y hoy va en auto al centro. ¿Qué combinación le conviene explorar?","opciones":[{"id":"o1","texto":"Bici hasta la estación y tren al centro"},{"id":"o2","texto":"Caminar los 25 km completos hasta el centro"},{"id":"o3","texto":"Auto hasta el centro, porque la estación está lejos"},{"id":"o4","texto":"Remís hasta la estación todos los días"}]},"solucion":{"clave":["o1"],"explicacion":"La bici acerca estaciones que parecen lejanas a pie: 2,5 km son unos 10 minutos pedaleando.","por_opcion":{"o3":"2,5 km en bici son unos 10 minutos: la estación no está tan lejos."}}},{"slug":"movilidad-2.s5.p11","orden":11,"grupo":"movilidad-2.s5.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan municipal y marcá lo que no ayuda a combinar modos.","segmentos":[{"id":"s1","texto":"Instalaremos bicicleteros techados en las estaciones."},{"id":"s2","texto":"Prohibiremos subir bicis al tren en todos los horarios."},{"id":"s3","texto":"Habrá una ciclovía desde el barrio hasta la estación."},{"id":"s4","texto":"Eliminaremos la parada de colectivo frente a la estación."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Combinar modos requiere que cada pieza encaje con la siguiente.","por_opcion":{"s2":"Impedir llevar la bici limita la intermodalidad; se puede regular por horario.","s4":"Empeora la conexión entre modos."}}},{"slug":"movilidad-2.s5.p12","orden":12,"grupo":"movilidad-2.s5.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Combinar modos en un viaje se llama {{0}}; el último tramo hasta el destino es la {{1}} milla.","banco":[{"id":"w1","texto":"intermodalidad"},{"id":"w2","texto":"última"},{"id":"w3","texto":"congestión"},{"id":"w4","texto":"primera"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para armar viajes largos con baja huella."}}]},{"slug":"movilidad-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: caminar y pedalear","bajada_es":"Bici, salud, seguridad, ciudad caminable y combinación de modos, mezclados.","minutos":8,"pasos":[{"slug":"movilidad-2.s6.p1","orden":1,"grupo":"movilidad-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Caminar y pedalear». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"movilidad-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el plan de Carla","bajada_es":"Carla quiere dejar el auto para ir al trabajo. Con datos de tiempos, costos, salud y seguridad, armá el mejor plan.","minutos":10,"pasos":[{"slug":"movilidad-2.s7.p1","orden":1,"grupo":"movilidad-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación de Carla","cuerpo":["Carla vive a 3 km de una estación de tren. El tren la deja a 1 km de su trabajo, en un viaje de 25 minutos. En auto tarda 45 minutos en hora pico y paga estacionamiento. Hay una ciclovía que llega a la estación, que tiene bicicletero techado. Del tren al trabajo hay veredas buenas.","Carla hoy casi no hace actividad física y trabaja 5 días por semana."]},"solucion":{}},{"slug":"movilidad-2.s7.p2","orden":2,"grupo":"movilidad-2.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos tarda en bici hasta la estación, a 15 km por hora?","unidad":"minutos","decimales":0,"contexto":"Carla pedalea 3 km hasta la estación a 15 km/h."},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"3 ÷ 15 × 60 = 12 minutos de pedaleo hasta la estación."}},{"slug":"movilidad-2.s7.p3","orden":3,"grupo":"movilidad-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuánto tarda el viaje completo: 12 minutos en bici, 3 de dejar la bici, 25 de tren y 12 caminando?","unidad":"minutos","decimales":0,"contexto":"Bici 12 min, bicicletero 3, tren 25, caminata 12."},"solucion":{"valor":52,"tolerancia":1.04,"explicacion":"12 + 3 + 25 + 12 = 52 minutos, contra 45 en auto: solo 7 minutos más, con 24 minutos de actividad física incluidos."}},{"slug":"movilidad-2.s7.p4","orden":4,"grupo":"movilidad-2.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos minutos de actividad física suma por semana (bici y caminata, ida y vuelta, 5 días)?","unidad":"minutos","decimales":0,"contexto":"12 min de bici y 12 de caminata por tramo, ida y vuelta, 5 días."},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"(12 + 12) × 2 × 5 = 240 minutos por semana: más que los 150 que recomienda la OMS como mínimo."}},{"slug":"movilidad-2.s7.p5","orden":5,"grupo":"movilidad-2.s7.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las ventajas y desventajas del nuevo plan.","grupos":[{"id":"g1","nombre":"Ventaja"},{"id":"g2","nombre":"Desventaja a resolver"}],"items":[{"id":"i1","texto":"Cumple la actividad física recomendada"},{"id":"i2","texto":"Tarda unos minutos más"},{"id":"i3","texto":"Ahorra estacionamiento y combustible"},{"id":"i4","texto":"Los días de lluvia fuerte es incómodo"},{"id":"i5","texto":"Emite mucho menos CO₂"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Un buen plan reconoce las desventajas y les busca solución, por ejemplo, otro modo los días de lluvia."}},{"slug":"movilidad-2.s7.p6","orden":6,"grupo":"movilidad-2.s7.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer los días de lluvia fuerte?","opciones":[{"id":"o1","texto":"Ir caminando o en colectivo a la estación"},{"id":"o2","texto":"Volver a usar el auto todos los días"},{"id":"o3","texto":"Pedalear igual sin luces ni capa"},{"id":"o4","texto":"Faltar al trabajo"}]},"solucion":{"clave":["o1"],"explicacion":"Tener un plan B para los días difíciles hace que el hábito se sostenga el resto de los días.","por_opcion":{"o3":"Con lluvia fuerte baja la visibilidad: sin preparación es riesgoso."}}},{"slug":"movilidad-2.s7.p7","orden":7,"grupo":"movilidad-2.s7.p7","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué necesita Carla para pedalear seguro? Marcá todo.","opciones":[{"id":"o1","texto":"Luces delantera y trasera"},{"id":"o2","texto":"Casco"},{"id":"o3","texto":"Usar la ciclovía hasta la estación"},{"id":"o4","texto":"Un buen candado para el bicicletero"},{"id":"o5","texto":"Auriculares con música fuerte"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Ver, ser vista, protegerse y cuidar la bici."}},{"slug":"movilidad-2.s7.p8","orden":8,"grupo":"movilidad-2.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Carla escribe su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Voy en bici por la ciclovía hasta la estación y tomo el tren."},{"id":"s2","texto":"Si llueve fuerte, voy en colectivo a la estación."},{"id":"s3","texto":"Para llegar antes, voy por la avenida de contramano en vez de la ciclovía."},{"id":"s4","texto":"Como tardo 7 minutos más, no vale la pena por la salud."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Un plan realista, seguro y con alternativas: así se sostiene un cambio de hábito.","por_opcion":{"s3":"Ir de contramano es muy riesgoso; la ciclovía es más segura.","s4":"Suma 240 minutos de actividad por semana: un beneficio enorme por 7 minutos."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"movilidad-3","rama":"movilidad","orden":3,"nivel":2,"titulo_es":"Transporte público","bajada_es":"Frecuencias, redes, combinaciones, carriles exclusivos y trenes: cómo funciona el transporte público y qué lo hace una opción que la gente elige.","objetivos_es":["Explicar por qué el transporte público es eficiente en espacio, energía y equidad","Calcular esperas a partir de la frecuencia y entender por qué los colectivos se amontonan","Comparar redes radiales y en grilla, y el dilema entre cobertura y frecuencia","Reconocer los componentes de un sistema de colectivos rápidos y de la electrificación","Evaluar la accesibilidad y la seguridad de un sistema para todas las personas"],"repasa":["movilidad-1","movilidad-2","energia-3","tronco-2"],"requiere_tronco":2,"fuentes":["human-transit","itdp-brt","metrobus-gcba","red-sube","owid-transporte","oms-aire-exterior","oms-seguridad-vial"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"movilidad-3.s1","orden":1,"tipo":"leccion","titulo_es":"Por qué funciona","bajada_es":"Espacio, energía y equidad: por qué una ciudad no puede moverse solo en auto.","minutos":11,"pasos":[{"slug":"movilidad-3.s1.p1","orden":1,"grupo":"movilidad-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Muchas personas, poco espacio","cuerpo":["Como viste en la base de la rama, un colectivo con 50 personas ocupa en la calle el lugar de tres o cuatro autos, que en promedio llevan poco más de una persona cada uno. Un tren puede mover en una hora a decenas de miles de personas por una sola vía. Ninguna ciudad grande podría funcionar si todos sus viajes se hicieran en auto: no habría calles ni estacionamiento suficientes.","Además, por persona, un transporte público con buena ocupación usa mucha menos energía y emite mucho menos que un auto con un solo ocupante."]},"solucion":{}},{"slug":"movilidad-3.s1.p2","orden":2,"grupo":"movilidad-3.s1.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un colectivo lleva 60 personas. Si en autos viajan en promedio 1,2 personas por auto, ¿cuántos autos harían falta para llevar a esas personas? Redondeá al entero.","unidad":"autos","decimales":0},"solucion":{"valor":50,"tolerancia":1,"explicacion":"60 ÷ 1,2 ≈ 50 autos. Todos ellos en la calle, en lugar de un solo colectivo."}},{"slug":"movilidad-3.s1.p2.v2","orden":2,"grupo":"movilidad-3.s1.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un colectivo lleva 45 personas. Si en autos viajan en promedio 1,5 personas por auto, ¿cuántos autos harían falta para llevar a esas personas? Redondeá al entero.","unidad":"autos","decimales":0},"solucion":{"valor":30,"tolerancia":1,"explicacion":"45 ÷ 1,5 ≈ 30 autos. Todos ellos en la calle, en lugar de un solo colectivo."}},{"slug":"movilidad-3.s1.p2.v3","orden":2,"grupo":"movilidad-3.s1.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un colectivo lleva 80 personas. Si en autos viajan en promedio 1,3 personas por auto, ¿cuántos autos harían falta para llevar a esas personas? Redondeá al entero.","unidad":"autos","decimales":0},"solucion":{"valor":62,"tolerancia":1,"explicacion":"80 ÷ 1,3 ≈ 62 autos. Todos ellos en la calle, en lugar de un solo colectivo."}},{"slug":"movilidad-3.s1.p3","orden":3,"grupo":"movilidad-3.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Equidad","cuerpo":["El transporte público no es solo una cuestión ambiental. Muchas personas no pueden o no deben manejar: chicos y adolescentes, muchas personas mayores, personas con algunas discapacidades, y quienes no pueden pagar un auto. Para ellas, el transporte público es la diferencia entre llegar o no a la escuela, al trabajo, al hospital o a ver a su familia."]},"solucion":{}},{"slug":"movilidad-3.s1.p4","orden":4,"grupo":"movilidad-3.s1.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Quiénes dependen especialmente del transporte público? Marcá todos.","opciones":[{"id":"o1","texto":"Estudiantes que todavía no pueden manejar"},{"id":"o2","texto":"Personas mayores que dejaron de manejar"},{"id":"o3","texto":"Hogares que no pueden pagar un auto"},{"id":"o4","texto":"Personas con algunas discapacidades"},{"id":"o5","texto":"Nadie: todas las personas tienen auto"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un buen sistema de transporte público amplía las oportunidades de muchísimas personas."}},{"slug":"movilidad-3.s1.p5","orden":5,"grupo":"movilidad-3.s1.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este beneficio es ambiental, social o urbano?","grupos":[{"id":"g1","nombre":"Ambiental"},{"id":"g2","nombre":"Social"},{"id":"g3","nombre":"Urbano"}],"items":[{"id":"i1","texto":"Menos emisiones por persona"},{"id":"i2","texto":"Acceso al trabajo para quien no tiene auto"},{"id":"i3","texto":"Menos espacio ocupado por vehículos"},{"id":"i4","texto":"Menos contaminación del aire"},{"id":"i5","texto":"Autonomía para adolescentes y personas mayores"},{"id":"i6","texto":"Menos congestión en las avenidas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"El transporte público suma beneficios en varias dimensiones a la vez."}},{"slug":"movilidad-3.s1.p6","orden":6,"grupo":"movilidad-3.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El círculo vicioso y el virtuoso","cuerpo":["Cuando el servicio es malo, quienes pueden se pasan al auto; bajan los pasajeros, bajan los ingresos, el servicio empeora y más gente se va. Es un círculo vicioso. Cuando el servicio mejora —más frecuencia, carriles exclusivos, buena información—, suben los pasajeros, lo que permite sostener y mejorar el servicio: un círculo virtuoso."]},"solucion":{}},{"slug":"movilidad-3.s1.p7","orden":7,"grupo":"movilidad-3.s1.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el círculo vicioso del transporte público.","items":[{"id":"i1","texto":"El servicio es poco frecuente y lento"},{"id":"i2","texto":"Quienes pueden se pasan al auto"},{"id":"i3","texto":"Bajan los pasajeros y los ingresos"},{"id":"i4","texto":"Se recortan frecuencias"},{"id":"i5","texto":"El servicio empeora todavía más"},{"id":"i6","texto":"Más personas eligen el colectivo porque es lento"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Romper el círculo requiere invertir en calidad de servicio, no solo en vehículos."}},{"slug":"movilidad-3.s1.p8","orden":8,"grupo":"movilidad-3.s1.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué medida puede iniciar un círculo virtuoso?","opciones":[{"id":"o1","texto":"Aumentar la frecuencia y darle carril exclusivo"},{"id":"o2","texto":"Subir la tarifa y reducir los recorridos"},{"id":"o3","texto":"Sacar las paradas para que el colectivo no frene"},{"id":"o4","texto":"Ensanchar las avenidas para más autos"}]},"solucion":{"clave":["o1"],"explicacion":"Un servicio más rápido y frecuente atrae pasajeros, y los pasajeros sostienen el servicio.","por_opcion":{"o3":"Sin paradas, nadie puede subir: no es una opción."}}},{"slug":"movilidad-3.s1.p9","orden":9,"grupo":"movilidad-3.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un colectivo emite 1.500 g de CO₂ por kilómetro y lleva 50 personas. ¿Cuántos gramos por persona y por kilómetro son?","unidad":"g/km por persona","decimales":0,"contexto":"1500 g/km del colectivo; 50 personas a bordo."},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"1.500 ÷ 50 = 30 g por persona y km. Un auto con una sola persona suele emitir entre 150 y 200 g/km."}},{"slug":"movilidad-3.s1.p9.v2","orden":9,"grupo":"movilidad-3.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un colectivo emite 2.200 g de CO₂ por kilómetro y lleva 40 personas. ¿Cuántos gramos por persona y por kilómetro son?","unidad":"g/km por persona","decimales":0,"contexto":"2200 g/km del colectivo; 40 personas a bordo."},"solucion":{"valor":55,"tolerancia":1.1,"explicacion":"2.200 ÷ 40 = 55 g por persona y km. Un auto con una sola persona suele emitir entre 150 y 200 g/km."}},{"slug":"movilidad-3.s1.p9.v3","orden":9,"grupo":"movilidad-3.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un colectivo emite 1.800 g de CO₂ por kilómetro y lleva 60 personas. ¿Cuántos gramos por persona y por kilómetro son?","unidad":"g/km por persona","decimales":0,"contexto":"1800 g/km del colectivo; 60 personas a bordo."},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"1.800 ÷ 60 = 30 g por persona y km. Un auto con una sola persona suele emitir entre 150 y 200 g/km."}},{"slug":"movilidad-3.s1.p10","orden":10,"grupo":"movilidad-3.s1.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un colectivo casi vacío siempre emite menos por persona que un auto.","razones":[{"id":"r1","texto":"Porque con pocos pasajeros sus emisiones se reparten entre pocos"},{"id":"r2","texto":"Porque los colectivos no emiten nada"},{"id":"r3","texto":"Porque los autos emiten siempre más que cualquier vehículo"}]},"solucion":{"valor":false,"explicacion":"Con muy pocos pasajeros, un colectivo puede emitir más por persona que un auto. Por eso la ocupación importa, y por eso el objetivo es atraer pasajeros.","clave":["r1"]}},{"slug":"movilidad-3.s1.p11","orden":11,"grupo":"movilidad-3.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Para llevar a 50 personas en autos con 1,25 personas por auto, ¿cuántos metros cuadrados de calle ocupan los autos, si cada uno ocupa unos 10 m² detenido?","unidad":"m²","decimales":0,"contexto":"50 personas; 1.25 por auto; 10 m² por auto."},"solucion":{"valor":400,"tolerancia":8,"explicacion":"50 ÷ 1,25 = 40 autos; 40 × 10 = 400 m². Un colectivo que lleva a las mismas personas ocupa unos 30 m²."}},{"slug":"movilidad-3.s1.p11.v2","orden":11,"grupo":"movilidad-3.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Para llevar a 60 personas en autos con 1,2 personas por auto, ¿cuántos metros cuadrados de calle ocupan los autos, si cada uno ocupa unos 10 m² detenido?","unidad":"m²","decimales":0,"contexto":"60 personas; 1.2 por auto; 10 m² por auto."},"solucion":{"valor":500,"tolerancia":10,"explicacion":"60 ÷ 1,2 = 50 autos; 50 × 10 = 500 m². Un colectivo que lleva a las mismas personas ocupa unos 30 m²."}},{"slug":"movilidad-3.s1.p11.v3","orden":11,"grupo":"movilidad-3.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Para llevar a 40 personas en autos con 1,25 personas por auto, ¿cuántos metros cuadrados de calle ocupan los autos, si cada uno ocupa unos 10 m² detenido?","unidad":"m²","decimales":0,"contexto":"40 personas; 1.25 por auto; 10 m² por auto."},"solucion":{"valor":320,"tolerancia":6.4,"explicacion":"40 ÷ 1,25 = 32 autos; 32 × 10 = 320 m². Un colectivo que lleva a las mismas personas ocupa unos 30 m²."}},{"slug":"movilidad-3.s1.p12","orden":12,"grupo":"movilidad-3.s1.p12","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada idea con su ejemplo.","izquierda":[{"id":"a1","texto":"Eficiencia de espacio"},{"id":"a2","texto":"Equidad"},{"id":"a3","texto":"Círculo vicioso"},{"id":"a4","texto":"Ocupación"}],"derecha":[{"id":"b1","texto":"Un colectivo en lugar de 40 autos"},{"id":"b2","texto":"Una adolescente que va sola a la escuela"},{"id":"b3","texto":"Menos pasajeros, menos servicio, menos pasajeros"},{"id":"b4","texto":"Emisiones repartidas entre muchas personas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro ideas que explican por qué el transporte público es clave."}},{"slug":"movilidad-3.s1.p13","orden":13,"grupo":"movilidad-3.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El transporte público ocupa menos espacio por persona que el auto."},{"id":"s2","texto":"El transporte público solo lo usa quien no tiene otra opción."},{"id":"s3","texto":"Mejorar el servicio puede atraer más pasajeros."},{"id":"s4","texto":"Si hay pocos pasajeros, lo mejor es recortar frecuencias hasta que suban."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El transporte público es una red que se alimenta de sus pasajeros.","por_opcion":{"s2":"Donde el servicio es bueno, lo eligen personas de todos los ingresos.","s4":"Recortar frecuencias suele alejar todavía más pasajeros."}}},{"slug":"movilidad-3.s1.p14","orden":14,"grupo":"movilidad-3.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando el servicio empeora y la gente lo abandona, se forma un círculo {{0}}; el transporte público da acceso a quienes no pueden manejar, lo que tiene que ver con la {{1}}; y las emisiones por persona dependen de la {{2}}.","banco":[{"id":"w1","texto":"vicioso"},{"id":"w2","texto":"equidad"},{"id":"w3","texto":"ocupación"},{"id":"w4","texto":"perfecto"},{"id":"w5","texto":"velocidad"},{"id":"w6","texto":"pintura"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas centrales sobre por qué importa el transporte público."}}]},{"slug":"movilidad-3.s2","orden":2,"tipo":"leccion","titulo_es":"Frecuencia es libertad","bajada_es":"Cada cuánto pasa, desde qué hora y hasta cuándo, y si llega a horario: lo que decide si el transporte sirve.","minutos":12,"pasos":[{"slug":"movilidad-3.s2.p1","orden":1,"grupo":"movilidad-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La espera","cuerpo":["La frecuencia es cada cuántos minutos pasa un servicio. Si una persona llega a la parada sin mirar horarios, en promedio espera la mitad del intervalo: si el colectivo pasa cada 20 minutos, espera en promedio 10. Con un servicio cada 5 minutos, casi no hace falta mirar el horario: se va a la parada y se sube. Por eso se dice que la frecuencia es libertad: permite moverse cuando uno quiere, no cuando pasa el colectivo."]},"solucion":{}},{"slug":"movilidad-3.s2.p2","orden":2,"grupo":"movilidad-3.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un colectivo pasa cada 20 minutos y llegás a la parada sin mirar el horario, ¿cuánto esperás en promedio?","unidad":"minutos","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"La espera promedio es la mitad del intervalo: 20 ÷ 2 = 10 minutos. Con frecuencias altas, la espera casi desaparece."}},{"slug":"movilidad-3.s2.p2.v2","orden":2,"grupo":"movilidad-3.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un colectivo pasa cada 12 minutos y llegás a la parada sin mirar el horario, ¿cuánto esperás en promedio?","unidad":"minutos","decimales":0},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"La espera promedio es la mitad del intervalo: 12 ÷ 2 = 6 minutos. Con frecuencias altas, la espera casi desaparece."}},{"slug":"movilidad-3.s2.p2.v3","orden":2,"grupo":"movilidad-3.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un colectivo pasa cada 30 minutos y llegás a la parada sin mirar el horario, ¿cuánto esperás en promedio?","unidad":"minutos","decimales":0},"solucion":{"valor":15,"tolerancia":0.5,"explicacion":"La espera promedio es la mitad del intervalo: 30 ÷ 2 = 15 minutos. Con frecuencias altas, la espera casi desaparece."}},{"slug":"movilidad-3.s2.p3","orden":3,"grupo":"movilidad-3.s2.p3","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Frecuencia y tiempo total","planteo":"Dos líneas tardan 20 minutos en llegar al centro. La línea A pasa cada 30 minutos. La línea B pasa cada 6 minutos.","pasos":["Espera promedio en A: 15 minutos. Tiempo total promedio: 15 + 20 = 35 minutos.","Espera promedio en B: 3 minutos. Tiempo total promedio: 3 + 20 = 23 minutos.","Con la misma velocidad, la línea frecuente ahorra 12 minutos por viaje en promedio."],"resultado":"La frecuencia puede pesar tanto como la velocidad en el tiempo total de viaje."},"solucion":{}},{"slug":"movilidad-3.s2.p4","orden":4,"grupo":"movilidad-3.s2.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Dos líneas tardan 25 minutos al destino. Una pasa cada 30 minutos y la otra cada 10. ¿Cuántos minutos ahorra en promedio quien toma la más frecuente, sin mirar horarios?","unidad":"minutos","decimales":0,"contexto":"Intervalos de 30 y 10 minutos; 25 minutos de viaje."},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"Esperas promedio: 15 y 5 minutos. Diferencia: 10 minutos por viaje, con el mismo tiempo arriba del colectivo."}},{"slug":"movilidad-3.s2.p4.v2","orden":4,"grupo":"movilidad-3.s2.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Dos líneas tardan 15 minutos al destino. Una pasa cada 20 minutos y la otra cada 5. ¿Cuántos minutos ahorra en promedio quien toma la más frecuente, sin mirar horarios?","unidad":"minutos","decimales":1,"contexto":"Intervalos de 20 y 5 minutos; 15 minutos de viaje."},"solucion":{"valor":7.5,"tolerancia":0.15,"explicacion":"Esperas promedio: 10 y 2.5 minutos. Diferencia: 7.5 minutos por viaje, con el mismo tiempo arriba del colectivo."}},{"slug":"movilidad-3.s2.p4.v3","orden":4,"grupo":"movilidad-3.s2.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Dos líneas tardan 30 minutos al destino. Una pasa cada 40 minutos y la otra cada 8. ¿Cuántos minutos ahorra en promedio quien toma la más frecuente, sin mirar horarios?","unidad":"minutos","decimales":0,"contexto":"Intervalos de 40 y 8 minutos; 30 minutos de viaje."},"solucion":{"valor":16,"tolerancia":0.5,"explicacion":"Esperas promedio: 20 y 4 minutos. Diferencia: 16 minutos por viaje, con el mismo tiempo arriba del colectivo."}},{"slug":"movilidad-3.s2.p5","orden":5,"grupo":"movilidad-3.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Horario de servicio y confiabilidad","cuerpo":["Además de la frecuencia importa el horario de servicio: desde qué hora hasta qué hora funciona. Una línea que termina a las 21 no sirve a quien sale de trabajar a las 22. Y importa la confiabilidad: si el colectivo que debería pasar cada 10 minutos a veces tarda 30, las personas tienen que salir mucho antes \"por las dudas\", y el viaje se vuelve impredecible."]},"solucion":{}},{"slug":"movilidad-3.s2.p6","orden":6,"grupo":"movilidad-3.s2.p6","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada atributo del servicio con su pregunta.","izquierda":[{"id":"a1","texto":"Frecuencia"},{"id":"a2","texto":"Horario de servicio"},{"id":"a3","texto":"Confiabilidad"},{"id":"a4","texto":"Velocidad"}],"derecha":[{"id":"b1","texto":"¿Cada cuánto pasa?"},{"id":"b2","texto":"¿Desde qué hora hasta qué hora funciona?"},{"id":"b3","texto":"¿Pasa cuando dice que va a pasar?"},{"id":"b4","texto":"¿Cuánto tarda una vez arriba?"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los cuatro atributos juntos definen si el transporte público es útil para una persona."}},{"slug":"movilidad-3.s2.p7","orden":7,"grupo":"movilidad-3.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Colectivos en racimo","cuerpo":["¿Por qué a veces pasan tres colectivos de la misma línea juntos después de una larga espera? Si uno se atrasa, en la parada lo espera más gente; tarda más en subirla y se atrasa todavía más. El que viene detrás encuentra menos gente, va más rápido y lo alcanza. Así se forman los racimos. Para evitarlos se usan carriles exclusivos, pago antes de subir, puertas múltiples y control de intervalos desde una central."]},"solucion":{}},{"slug":"movilidad-3.s2.p8","orden":8,"grupo":"movilidad-3.s2.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se forma un racimo de colectivos.","items":[{"id":"i1","texto":"Un colectivo se atrasa por el tránsito"},{"id":"i2","texto":"En la parada se acumula más gente esperándolo"},{"id":"i3","texto":"Tarda más en subir a todos y se atrasa más"},{"id":"i4","texto":"El colectivo de atrás encuentra paradas casi vacías"},{"id":"i5","texto":"Lo alcanza y pasan juntos"},{"id":"i6","texto":"El colectivo atrasado se adelanta solo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El sistema tiende a desordenarse solo; mantener intervalos parejos requiere gestión activa."}},{"slug":"movilidad-3.s2.p9","orden":9,"grupo":"movilidad-3.s2.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a evitar que los colectivos se amontonen? Marcá todo.","opciones":[{"id":"o1","texto":"Carriles exclusivos"},{"id":"o2","texto":"Pagar antes de subir o con tarjeta rápida"},{"id":"o3","texto":"Control de intervalos desde una central"},{"id":"o4","texto":"Que cada chofer salga cuando quiera"},{"id":"o5","texto":"Sacar las puertas traseras"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Menos tiempo en paradas y menos exposición al tránsito hacen el servicio más regular."}},{"slug":"movilidad-3.s2.p10","orden":10,"grupo":"movilidad-3.s2.p10","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una línea con colectivos muy rápidos pero que pasa cada hora es más útil que una un poco más lenta que pasa cada 5 minutos.","razones":[{"id":"r1","texto":"Porque la espera larga pesa mucho en el tiempo total"},{"id":"r2","texto":"Porque la velocidad no importa nunca"},{"id":"r3","texto":"Porque las líneas frecuentes no llevan pasajeros"}]},"solucion":{"valor":false,"explicacion":"Depende del viaje, pero en general la frecuencia alta ahorra más tiempo de espera del que se pierde por ir un poco más lento, y además da libertad de horarios.","clave":["r1"]}},{"slug":"movilidad-3.s2.p11","orden":11,"grupo":"movilidad-3.s2.p11","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tu colectivo debería pasar cada 10 minutos, pero a veces tarda 35. ¿Qué atributo está fallando?","opciones":[{"id":"o1","texto":"La confiabilidad"},{"id":"o2","texto":"El horario de servicio"},{"id":"o3","texto":"La tarifa"},{"id":"o4","texto":"La cantidad de asientos"}]},"solucion":{"clave":["o1"],"explicacion":"Sin confiabilidad, la frecuencia prometida no sirve: hay que salir antes \"por las dudas\".","por_opcion":{"o3":"La tarifa no cambia la regularidad del servicio."}}},{"slug":"movilidad-3.s2.p12","orden":12,"grupo":"movilidad-3.s2.p12","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas líneas por tiempo total promedio (espera más viaje), de menor a mayor, si llegás sin mirar el horario.","items":[{"id":"i1","texto":"Pasa cada 10 minutos y tarda 20"},{"id":"i2","texto":"Pasa cada 6 minutos y tarda 24"},{"id":"i3","texto":"Pasa cada 30 minutos y tarda 15"},{"id":"i4","texto":"Pasa cada 60 minutos y tarda 10"}],"extremos":["Menos tiempo","Más tiempo"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La más rápida arriba del colectivo resulta la peor en tiempo total por su espera.","valores":{"i1":"5 + 20 = 25 min","i2":"3 + 24 = 27 min","i3":"15 + 15 = 30 min","i4":"30 + 10 = 40 min"}}},{"slug":"movilidad-3.s2.p13","orden":13,"grupo":"movilidad-3.s2.p13","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una línea funciona de 6 a 20. Un enfermero sale de su turno a las 23. ¿Qué atributo del servicio le falla?","opciones":[{"id":"o1","texto":"El horario de servicio"},{"id":"o2","texto":"La frecuencia en hora pico"},{"id":"o3","texto":"La velocidad del colectivo"},{"id":"o4","texto":"La cantidad de paradas"}]},"solucion":{"clave":["o1"],"explicacion":"El horario de servicio decide si el transporte existe para quienes trabajan de noche o de madrugada.","por_opcion":{"o3":"Aunque fuera rapidísimo, a las 23 no pasa."}}},{"slug":"movilidad-3.s2.p14","orden":14,"grupo":"movilidad-3.s2.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta queja de un usuario y marcá lo que está mal razonado.","segmentos":[{"id":"s1","texto":"Si el colectivo pasa cada 30 minutos, espero en promedio 15."},{"id":"s2","texto":"Los colectivos vienen en racimo porque los choferes se ponen de acuerdo."},{"id":"s3","texto":"Una línea que termina a las 21 no me sirve para volver del trabajo."},{"id":"s4","texto":"La frecuencia no importa si el colectivo es rápido."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Entender cómo funciona el servicio ayuda a pedir las mejoras correctas.","por_opcion":{"s2":"Los racimos se forman solos por los atrasos y las paradas llenas.","s4":"La espera puede pesar tanto como la velocidad."}}},{"slug":"movilidad-3.s2.p15","orden":15,"grupo":"movilidad-3.s2.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Si un colectivo pasa cada 20 minutos, la espera promedio es de {{0}} minutos; que pase cuando dice que va a pasar es su {{1}}; y cuando varios colectivos pasan juntos se habla de un {{2}}.","banco":[{"id":"w1","texto":"10"},{"id":"w2","texto":"confiabilidad"},{"id":"w3","texto":"racimo"},{"id":"w4","texto":"40"},{"id":"w5","texto":"tarifa"},{"id":"w6","texto":"convoy"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para evaluar un servicio de transporte."}}]},{"slug":"movilidad-3.s3","orden":3,"tipo":"leccion","titulo_es":"Redes y combinaciones","bajada_es":"Líneas que van al centro o que forman una grilla, el dilema entre cubrir todo y pasar seguido, y la tarifa integrada.","minutos":12,"pasos":[{"slug":"movilidad-3.s3.p1","orden":1,"grupo":"movilidad-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Radial o en grilla","cuerpo":["En una red radial, casi todas las líneas van desde los barrios hasta el centro. Funciona bien para ir al centro, pero para ir de un barrio a otro hay que pasar por el centro, aunque esté lejos. En una red en grilla, las líneas cruzan la ciudad en dos direcciones y se combinan en los cruces: con una sola combinación se llega de casi cualquier punto a casi cualquier otro. Las grillas funcionan mejor cuando las líneas son frecuentes, porque la combinación implica una espera."]},"solucion":{}},{"slug":"movilidad-3.s3.p2","orden":2,"grupo":"movilidad-3.s3.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué ventaja tiene una red en grilla frente a una radial?","opciones":[{"id":"o1","texto":"Conecta barrios entre sí sin pasar por el centro"},{"id":"o2","texto":"Que nunca hace falta combinar"},{"id":"o3","texto":"Que solo sirve para ir al centro"},{"id":"o4","texto":"Que usa menos colectivos para cubrir lo mismo"}]},"solucion":{"clave":["o1"],"explicacion":"La grilla multiplica los destinos posibles, a cambio de combinaciones que necesitan frecuencia.","por_opcion":{"o3":"Eso describe a la red radial."}}},{"slug":"movilidad-3.s3.p3","orden":3,"grupo":"movilidad-3.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cobertura o frecuencia","cuerpo":["Con un presupuesto fijo, una ciudad tiene que elegir. Puede repartir los colectivos en muchas líneas para cubrir todos los barrios, pero cada una pasará poco. O puede concentrarlos en pocas líneas frecuentes por las avenidas principales, que atraen muchos pasajeros, aunque algunas personas tengan que caminar más. No hay una respuesta única: es una decisión sobre qué valorar, y conviene que sea explícita."]},"solucion":{}},{"slug":"movilidad-3.s3.p4","orden":4,"grupo":"movilidad-3.s3.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El mismo presupuesto, dos redes","planteo":"Una ciudad tiene 12 colectivos. Cada recorrido completo de ida y vuelta dura 60 minutos.","pasos":["Opción A: 2 líneas con 6 colectivos cada una. Cada línea pasa cada 60 ÷ 6 = 10 minutos.","Opción B: 6 líneas con 2 colectivos cada una. Cada línea pasa cada 60 ÷ 2 = 30 minutos.","A atrae más pasajeros por viaje; B llega más cerca de más casas, pero con esperas largas."],"resultado":"El intervalo es el tiempo de vuelta completa dividido por la cantidad de colectivos de la línea."},"solucion":{}},{"slug":"movilidad-3.s3.p5","orden":5,"grupo":"movilidad-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una línea tarda 60 minutos en hacer la vuelta completa y tiene 4 colectivos. ¿Cada cuántos minutos pasa?","unidad":"minutos","decimales":0},"solucion":{"valor":15,"tolerancia":0.5,"explicacion":"60 ÷ 4 = 15 minutos. Para pasar más seguido hay que sumar colectivos o hacer la vuelta más rápida, por ejemplo con carriles exclusivos."}},{"slug":"movilidad-3.s3.p5.v2","orden":5,"grupo":"movilidad-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una línea tarda 90 minutos en hacer la vuelta completa y tiene 6 colectivos. ¿Cada cuántos minutos pasa?","unidad":"minutos","decimales":0},"solucion":{"valor":15,"tolerancia":0.5,"explicacion":"90 ÷ 6 = 15 minutos. Para pasar más seguido hay que sumar colectivos o hacer la vuelta más rápida, por ejemplo con carriles exclusivos."}},{"slug":"movilidad-3.s3.p5.v3","orden":5,"grupo":"movilidad-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una línea tarda 80 minutos en hacer la vuelta completa y tiene 10 colectivos. ¿Cada cuántos minutos pasa?","unidad":"minutos","decimales":0},"solucion":{"valor":8,"tolerancia":0.5,"explicacion":"80 ÷ 10 = 8 minutos. Para pasar más seguido hay que sumar colectivos o hacer la vuelta más rápida, por ejemplo con carriles exclusivos."}},{"slug":"movilidad-3.s3.p6","orden":6,"grupo":"movilidad-3.s3.p6","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un carril exclusivo puede aumentar la frecuencia sin comprar colectivos.","items":[{"id":"i1","texto":"Se crea un carril exclusivo para colectivos"},{"id":"i2","texto":"Los colectivos hacen la vuelta más rápido"},{"id":"i3","texto":"Cada colectivo completa más vueltas por hora"},{"id":"i4","texto":"Con la misma flota, pasan más seguido"},{"id":"i5","texto":"Se necesitan más choferes para ir más lento"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La velocidad se convierte en frecuencia: un beneficio doble para quien viaja."}},{"slug":"movilidad-3.s3.p7","orden":7,"grupo":"movilidad-3.s3.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta decisión prioriza la cobertura o la frecuencia?","grupos":[{"id":"g1","nombre":"Cobertura"},{"id":"g2","nombre":"Frecuencia"}],"items":[{"id":"i1","texto":"Una línea que entra a cada barrio aunque pase cada 40 minutos"},{"id":"i2","texto":"Pocas líneas por avenidas principales cada 6 minutos"},{"id":"i3","texto":"Muchos recorridos cortos y poco frecuentes"},{"id":"i4","texto":"Concentrar la flota en los corredores más usados"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Ninguna opción es \"la correcta\" en todos los casos: depende de los objetivos de la ciudad."}},{"slug":"movilidad-3.s3.p8","orden":8,"grupo":"movilidad-3.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tarifa integrada","cuerpo":["Combinar no debería costar como dos viajes completos. En el Área Metropolitana de Buenos Aires, la Red SUBE descuenta un 50 % en el segundo viaje y un 75 % desde el tercero, si se combinan colectivos, trenes y subtes dentro de las 2 horas desde el primer viaje. Así, una red con combinaciones no castiga a quien necesita hacerlas."]},"solucion":{}},{"slug":"movilidad-3.s3.p9","orden":9,"grupo":"movilidad-3.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con la Red SUBE, alguien hace tres viajes en menos de 2 horas, cada uno con tarifa de 800 pesos. El segundo tiene 50 % de descuento y el tercero 75 %. ¿Cuánto paga en total?","unidad":"pesos","decimales":0,"contexto":"Tres viajes de 800 pesos; descuentos del 50 % y 75 %."},"solucion":{"valor":1400,"tolerancia":28,"explicacion":"800 + 400 + 200 = 1.400 pesos, en lugar de 2.400. Las tarifas son ejemplos; los descuentos son los de la Red SUBE."}},{"slug":"movilidad-3.s3.p9.v2","orden":9,"grupo":"movilidad-3.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con la Red SUBE, alguien hace tres viajes en menos de 2 horas, cada uno con tarifa de 1.000 pesos. El segundo tiene 50 % de descuento y el tercero 75 %. ¿Cuánto paga en total?","unidad":"pesos","decimales":0,"contexto":"Tres viajes de 1000 pesos; descuentos del 50 % y 75 %."},"solucion":{"valor":1750,"tolerancia":35,"explicacion":"1.000 + 500 + 250 = 1.750 pesos, en lugar de 3.000. Las tarifas son ejemplos; los descuentos son los de la Red SUBE."}},{"slug":"movilidad-3.s3.p9.v3","orden":9,"grupo":"movilidad-3.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con la Red SUBE, alguien hace tres viajes en menos de 2 horas, cada uno con tarifa de 600 pesos. El segundo tiene 50 % de descuento y el tercero 75 %. ¿Cuánto paga en total?","unidad":"pesos","decimales":0,"contexto":"Tres viajes de 600 pesos; descuentos del 50 % y 75 %."},"solucion":{"valor":1050,"tolerancia":21,"explicacion":"600 + 300 + 150 = 1.050 pesos, en lugar de 1.800. Las tarifas son ejemplos; los descuentos son los de la Red SUBE."}},{"slug":"movilidad-3.s3.p10","orden":10,"grupo":"movilidad-3.s3.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una red con combinaciones siempre es peor que una con viajes directos.","razones":[{"id":"r1","texto":"Porque con frecuencia y tarifa integrada multiplican los destinos"},{"id":"r2","texto":"Porque los viajes directos no existen"},{"id":"r3","texto":"Porque combinar es siempre gratis y sin espera"}]},"solucion":{"valor":false,"explicacion":"Si las líneas son frecuentes y la tarifa está integrada, las combinaciones permiten llegar a muchos más destinos con la misma flota.","clave":["r1"]}},{"slug":"movilidad-3.s3.p11","orden":11,"grupo":"movilidad-3.s3.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su descripción.","izquierda":[{"id":"a1","texto":"Red radial"},{"id":"a2","texto":"Red en grilla"},{"id":"a3","texto":"Tarifa integrada"},{"id":"a4","texto":"Intervalo"}],"derecha":[{"id":"b1","texto":"Líneas que convergen en el centro"},{"id":"b2","texto":"Líneas que se cruzan en dos direcciones"},{"id":"b3","texto":"Descuento al combinar dentro de un tiempo"},{"id":"b4","texto":"Tiempo de vuelta dividido por la cantidad de colectivos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Vocabulario básico para leer y discutir una red de transporte."}},{"slug":"movilidad-3.s3.p12","orden":12,"grupo":"movilidad-3.s3.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una red radial, querés ir de un barrio del oeste a uno del norte, los dos lejos del centro. ¿Qué es lo más probable?","opciones":[{"id":"o1","texto":"Tener que ir hasta el centro y volver a salir"},{"id":"o2","texto":"Encontrar una línea directa entre los dos barrios"},{"id":"o3","texto":"Llegar más rápido que en auto seguro"},{"id":"o4","texto":"No poder combinar en ningún lugar"}]},"solucion":{"clave":["o1"],"explicacion":"Las redes radiales sirven para ir al centro, pero hacen dar vueltas para los viajes entre barrios.","por_opcion":{"o3":"El rodeo por el centro suele alargar mucho el viaje."}}},{"slug":"movilidad-3.s3.p13","orden":13,"grupo":"movilidad-3.s3.p13","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que combinar sea una buena opción para quien viaja? Marcá todo.","opciones":[{"id":"o1","texto":"Que las dos líneas sean frecuentes"},{"id":"o2","texto":"Que la tarifa esté integrada"},{"id":"o3","texto":"Que la parada de combinación sea cercana y segura"},{"id":"o4","texto":"Que haya que cruzar una avenida sin semáforo"},{"id":"o5","texto":"Que la segunda línea pase cada hora"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Combinar funciona cuando la espera es corta, barata y segura."}},{"slug":"movilidad-3.s3.p14","orden":14,"grupo":"movilidad-3.s3.p14","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta de un concejal y marcá lo que no se sostiene.","segmentos":[{"id":"s1","texto":"Con el mismo presupuesto, más líneas implican menos frecuencia en cada una."},{"id":"s2","texto":"Podemos cubrir cada cuadra y que todas las líneas pasen cada 5 minutos, sin más colectivos."},{"id":"s3","texto":"Un carril exclusivo puede aumentar la frecuencia con la misma flota."},{"id":"s4","texto":"Las combinaciones deben cobrarse como viajes completos para recaudar más."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Diseñar una red es elegir con presupuestos reales, no prometer todo a la vez.","por_opcion":{"s2":"Con flota fija, más cobertura significa menos frecuencia.","s4":"Castiga a quien combina y hace menos útil la red."}}},{"slug":"movilidad-3.s3.p15","orden":15,"grupo":"movilidad-3.s3.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una red con líneas que se cruzan es una {{0}}; con un presupuesto fijo hay que elegir entre cobertura y {{1}}; y la Red SUBE da un {{2}} % de descuento desde el tercer viaje.","banco":[{"id":"w1","texto":"grilla"},{"id":"w2","texto":"frecuencia"},{"id":"w3","texto":"75"},{"id":"w4","texto":"estrella"},{"id":"w5","texto":"publicidad"},{"id":"w6","texto":"10"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves del diseño de redes de transporte."}}]},{"slug":"movilidad-3.s4","orden":4,"tipo":"leccion","titulo_es":"Carriles, rieles y electricidad","bajada_es":"Colectivos rápidos, trenes, subtes y la electrificación del transporte público.","minutos":11,"pasos":[{"slug":"movilidad-3.s4.p1","orden":1,"grupo":"movilidad-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Colectivos rápidos","cuerpo":["Un sistema de colectivos rápidos, conocido por su sigla en inglés BRT, busca parecerse a un tren pero con colectivos. Sus componentes principales son: carriles exclusivos, idealmente en el centro de la avenida; estaciones con andenes; cobro de la tarifa antes de subir o con validación rápida; prioridad en los semáforos; y alta frecuencia. En Buenos Aires, el Metrobus empezó en 2011 en la avenida Juan B. Justo, y luego se extendió a otros corredores."]},"solucion":{}},{"slug":"movilidad-3.s4.p2","orden":2,"grupo":"movilidad-3.s4.p2","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué componentes tiene un sistema de colectivos rápidos? Marcá todos.","opciones":[{"id":"o1","texto":"Carriles exclusivos en el centro de la avenida"},{"id":"o2","texto":"Estaciones con andenes"},{"id":"o3","texto":"Prioridad en los semáforos"},{"id":"o4","texto":"Colectivos que comparten el carril con los autos"},{"id":"o5","texto":"Paradas sin techo cada 100 metros"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Cada componente reduce demoras: juntos, hacen al colectivo más rápido y regular."}},{"slug":"movilidad-3.s4.p3","orden":3,"grupo":"movilidad-3.s4.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene que los carriles exclusivos estén en el centro de la avenida?","opciones":[{"id":"o1","texto":"No los bloquean autos que giran o estacionan"},{"id":"o2","texto":"Porque en el centro hay más sombra para los pasajeros"},{"id":"o3","texto":"Porque así los colectivos van más lento y seguros"},{"id":"o4","texto":"Porque en el centro se paga menos la tarifa"}]},"solucion":{"clave":["o1"],"explicacion":"Los carriles junto a la vereda suelen quedar bloqueados por autos estacionados, entregas y giros.","por_opcion":{"o3":"El objetivo es ir más rápido y regular, no más lento."}}},{"slug":"movilidad-3.s4.p4","orden":4,"grupo":"movilidad-3.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Trenes y subtes","cuerpo":["Los trenes y subtes tienen la mayor capacidad: no comparten el espacio con el tránsito, sus formaciones llevan cientos o miles de personas y pueden pasar con mucha frecuencia. Su construcción es cara y lleva años, por eso tienen sentido en los corredores con más demanda. En el Área Metropolitana de Buenos Aires, varias líneas de tren suburbano funcionan con electricidad, igual que el subte."]},"solucion":{}},{"slug":"movilidad-3.s4.p5","orden":5,"grupo":"movilidad-3.s4.p5","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos modos según cuántas personas pueden mover por hora en un corredor, de más a menos.","items":[{"id":"i1","texto":"Tren o subte"},{"id":"i2","texto":"Colectivo rápido con carril exclusivo"},{"id":"i3","texto":"Colectivo en tránsito mixto"},{"id":"i4","texto":"Autos en un carril"}],"extremos":["Más personas","Menos personas"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto más separado del tránsito y más grande el vehículo, mayor la capacidad.","valores":{"i1":"decenas de miles","i2":"muchos miles","i3":"algunos miles","i4":"unos 2.000"}}},{"slug":"movilidad-3.s4.p6","orden":6,"grupo":"movilidad-3.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Electrificar","cuerpo":["Los trenes eléctricos, los subtes, los trolebuses y los colectivos eléctricos no emiten gases por el caño de escape. Eso mejora el aire de las calles, donde respiran las personas. Sus emisiones de CO₂ dependen de cómo se genera la electricidad: con una red con más renovables, emiten cada vez menos. En Argentina hay trolebuses en ciudades como Rosario, Córdoba y Mendoza, y varias ciudades incorporan colectivos eléctricos."]},"solucion":{}},{"slug":"movilidad-3.s4.p7","orden":7,"grupo":"movilidad-3.s4.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de beneficios de un colectivo eléctrico.","items":[{"id":"i1","texto":"Se reemplaza un colectivo diésel por uno eléctrico"},{"id":"i2","texto":"Deja de haber humo en la calle"},{"id":"i3","texto":"Mejora el aire que respiran peatones y pasajeros"},{"id":"i4","texto":"Si la red eléctrica suma renovables, también bajan sus emisiones de CO₂"},{"id":"i5","texto":"El colectivo eléctrico emite más humo al frenar"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Electrificar mejora el aire local de inmediato y el clima a medida que la red se limpia."}},{"slug":"movilidad-3.s4.p8","orden":8,"grupo":"movilidad-3.s4.p8","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este vehículo emite gases por el caño de escape?","grupos":[{"id":"g1","nombre":"No emite por escape"},{"id":"g2","nombre":"Sí emite por escape"}],"items":[{"id":"i1","texto":"Trolebús"},{"id":"i2","texto":"Colectivo diésel"},{"id":"i3","texto":"Subte"},{"id":"i4","texto":"Tren diésel"},{"id":"i5","texto":"Colectivo eléctrico a batería"},{"id":"i6","texto":"Tren eléctrico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g1"},"explicacion":"Todos los vehículos eléctricos evitan el humo en la calle; su huella climática depende de la red."}},{"slug":"movilidad-3.s4.p9","orden":9,"grupo":"movilidad-3.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con un carril exclusivo, un viaje en colectivo pasa de 40 a 28 minutos. ¿En qué porcentaje se redujo el tiempo de viaje?","unidad":"%","decimales":0,"contexto":"De 40 a 28 minutos de viaje."},"solucion":{"valor":30,"tolerancia":1,"explicacion":"(40 − 28) ÷ 40 × 100 = 30 %. Valores de ejemplo; en corredores reales la mejora depende de cuán congestionada estaba la avenida."}},{"slug":"movilidad-3.s4.p9.v2","orden":9,"grupo":"movilidad-3.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con un carril exclusivo, un viaje en colectivo pasa de 50 a 35 minutos. ¿En qué porcentaje se redujo el tiempo de viaje?","unidad":"%","decimales":0,"contexto":"De 50 a 35 minutos de viaje."},"solucion":{"valor":30,"tolerancia":1,"explicacion":"(50 − 35) ÷ 50 × 100 = 30 %. Valores de ejemplo; en corredores reales la mejora depende de cuán congestionada estaba la avenida."}},{"slug":"movilidad-3.s4.p9.v3","orden":9,"grupo":"movilidad-3.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con un carril exclusivo, un viaje en colectivo pasa de 60 a 45 minutos. ¿En qué porcentaje se redujo el tiempo de viaje?","unidad":"%","decimales":0,"contexto":"De 60 a 45 minutos de viaje."},"solucion":{"valor":25,"tolerancia":1,"explicacion":"(60 − 45) ÷ 60 × 100 = 25 %. Valores de ejemplo; en corredores reales la mejora depende de cuán congestionada estaba la avenida."}},{"slug":"movilidad-3.s4.p10","orden":10,"grupo":"movilidad-3.s4.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como los colectivos eléctricos no tienen caño de escape, no tienen ninguna huella ambiental.","razones":[{"id":"r1","texto":"Porque su fabricación y la electricidad tienen emisiones"},{"id":"r2","texto":"Porque emiten más humo que los diésel"},{"id":"r3","texto":"Porque no usan energía"}]},"solucion":{"valor":false,"explicacion":"Su fabricación, en especial la batería, y la electricidad que usan tienen emisiones. Aun así, suelen tener una huella menor que los diésel y no contaminan el aire de la calle.","clave":["r1"]}},{"slug":"movilidad-3.s4.p11","orden":11,"grupo":"movilidad-3.s4.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una formación de tren lleva 1.500 personas y pasa cada 6 minutos. ¿Cuántas personas puede mover por hora en un sentido?","unidad":"personas por hora","decimales":0,"contexto":"1500 personas por tren; uno cada 6 minutos."},"solucion":{"valor":15000,"tolerancia":300,"explicacion":"Pasan 10 trenes por hora: 1.500 × 10 = 15.000 personas por hora, varias veces más que un carril de autos."}},{"slug":"movilidad-3.s4.p11.v2","orden":11,"grupo":"movilidad-3.s4.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una formación de tren lleva 1.200 personas y pasa cada 4 minutos. ¿Cuántas personas puede mover por hora en un sentido?","unidad":"personas por hora","decimales":0,"contexto":"1200 personas por tren; uno cada 4 minutos."},"solucion":{"valor":18000,"tolerancia":360,"explicacion":"Pasan 15 trenes por hora: 1.200 × 15 = 18.000 personas por hora, varias veces más que un carril de autos."}},{"slug":"movilidad-3.s4.p11.v3","orden":11,"grupo":"movilidad-3.s4.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una formación de tren lleva 2.000 personas y pasa cada 5 minutos. ¿Cuántas personas puede mover por hora en un sentido?","unidad":"personas por hora","decimales":0,"contexto":"2000 personas por tren; uno cada 5 minutos."},"solucion":{"valor":24000,"tolerancia":480,"explicacion":"Pasan 12 trenes por hora: 2.000 × 12 = 24.000 personas por hora, varias veces más que un carril de autos."}},{"slug":"movilidad-3.s4.p12","orden":12,"grupo":"movilidad-3.s4.p12","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada sistema con una característica.","izquierda":[{"id":"a1","texto":"Metrobus"},{"id":"a2","texto":"Subte"},{"id":"a3","texto":"Trolebús"},{"id":"a4","texto":"Tren suburbano"}],"derecha":[{"id":"b1","texto":"Colectivos en carriles exclusivos"},{"id":"b2","texto":"Trenes bajo tierra, sin cruzar el tránsito"},{"id":"b3","texto":"Colectivo eléctrico conectado a cables aéreos"},{"id":"b4","texto":"Une la ciudad con localidades del área metropolitana"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada modo tiene su rol en una red integrada."}},{"slug":"movilidad-3.s4.p13","orden":13,"grupo":"movilidad-3.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El Metrobus de Buenos Aires empezó en 2011."},{"id":"s2","texto":"Un colectivo rápido necesita compartir el carril con los autos."},{"id":"s3","texto":"Los trolebuses funcionan con electricidad."},{"id":"s4","texto":"Los trenes son la opción más barata para cualquier calle."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cada modo tiene costos y capacidades distintas: se eligen según la demanda.","por_opcion":{"s2":"Su base es justamente el carril exclusivo.","s4":"Son caros y tienen sentido en los corredores de más demanda."}}},{"slug":"movilidad-3.s4.p14","orden":14,"grupo":"movilidad-3.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un sistema de colectivos rápidos se conoce por la sigla {{0}}; conviene que sus carriles estén en el {{1}} de la avenida; y los vehículos eléctricos no emiten gases por el caño de {{2}}.","banco":[{"id":"w1","texto":"BRT"},{"id":"w2","texto":"centro"},{"id":"w3","texto":"escape"},{"id":"w4","texto":"GNC"},{"id":"w5","texto":"borde"},{"id":"w6","texto":"agua"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre carriles, rieles y electrificación."}}]},{"slug":"movilidad-3.s5","orden":5,"tipo":"leccion","titulo_es":"Un sistema para todas las personas","bajada_es":"Accesibilidad, seguridad, información y el último tramo: lo que hace que el transporte sea usable de verdad.","minutos":11,"pasos":[{"slug":"movilidad-3.s5.p1","orden":1,"grupo":"movilidad-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Accesibilidad","cuerpo":["Un sistema accesible permite viajar a personas en silla de ruedas, con bastón, con cochecitos de bebé, con valijas o con dificultades para ver u oír. Eso implica colectivos de piso bajo con rampa, andenes al nivel del tren, ascensores que funcionen, anuncios sonoros y visuales de la próxima parada, y veredas y cruces accesibles para llegar a la parada. Lo que sirve a una persona con discapacidad suele servir a todas."]},"solucion":{}},{"slug":"movilidad-3.s5.p2","orden":2,"grupo":"movilidad-3.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace accesible un sistema de transporte? Marcá todo.","opciones":[{"id":"o1","texto":"Colectivos de piso bajo con rampa"},{"id":"o2","texto":"Anuncios sonoros y visuales de las paradas"},{"id":"o3","texto":"Ascensores que funcionen en las estaciones"},{"id":"o4","texto":"Veredas y cruces accesibles hasta la parada"},{"id":"o5","texto":"Escalones altos para subir más rápido"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La accesibilidad empieza en la vereda de casa y termina en el destino, no solo en el vehículo."}},{"slug":"movilidad-3.s5.p3","orden":3,"grupo":"movilidad-3.s5.p3","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La accesibilidad solo beneficia a las personas en silla de ruedas.","razones":[{"id":"r1","texto":"Porque beneficia a muchísimos grupos distintos"},{"id":"r2","texto":"Porque nadie más usa rampas"},{"id":"r3","texto":"Porque la accesibilidad es un lujo innecesario"}]},"solucion":{"valor":false,"explicacion":"Beneficia a personas mayores, a quienes llevan cochecitos, bolsos o valijas, a personas con lesiones temporales y a muchos más. Es diseño para todas las personas.","clave":["r1"]}},{"slug":"movilidad-3.s5.p4","orden":4,"grupo":"movilidad-3.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Seguridad personal","cuerpo":["Muchas personas, sobre todo mujeres, cambian de recorrido, de horario o dejan de usar el transporte público por miedo a sufrir acoso o delitos. Paradas iluminadas y visibles, información sobre cuándo llega el colectivo (para esperar menos en la calle), canales de denuncia, y personal capacitado ayudan a que el sistema sea seguro para todas las personas."]},"solucion":{}},{"slug":"movilidad-3.s5.p5","orden":5,"grupo":"movilidad-3.s5.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida mejora la seguridad personal o la accesibilidad?","grupos":[{"id":"g1","nombre":"Seguridad personal"},{"id":"g2","nombre":"Accesibilidad"}],"items":[{"id":"i1","texto":"Paradas bien iluminadas"},{"id":"i2","texto":"Rampas en los colectivos"},{"id":"i3","texto":"Canales de denuncia del acoso"},{"id":"i4","texto":"Anuncios sonoros de la próxima parada"},{"id":"i5","texto":"Saber cuándo llega el colectivo para no esperar de noche"},{"id":"i6","texto":"Ascensores en las estaciones"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las dos son condiciones para que el transporte sea usable por todas las personas."}},{"slug":"movilidad-3.s5.p6","orden":6,"grupo":"movilidad-3.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Información y el último tramo","cuerpo":["Saber cuándo llega el próximo colectivo reduce la espera percibida y la incertidumbre. Las aplicaciones con información en tiempo real y los carteles en las paradas ayudan mucho. Y el viaje no termina en la estación: el \"último tramo\" hasta la casa o el trabajo —caminando, en bici o en otro colectivo— tiene que ser seguro y cómodo. Estacionamientos de bicis en las estaciones y veredas en buen estado amplían el alcance de cada parada."]},"solucion":{}},{"slug":"movilidad-3.s5.p7","orden":7,"grupo":"movilidad-3.s5.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un estacionamiento seguro de bicis en una estación de tren amplía el alcance del tren?","opciones":[{"id":"o1","texto":"Más personas pueden llegar desde lejos en bici"},{"id":"o2","texto":"Porque las bicis pueden viajar solas en el tren"},{"id":"o3","texto":"Porque obliga a todos a usar bici"},{"id":"o4","texto":"Porque reemplaza al tren"}]},"solucion":{"clave":["o1"],"explicacion":"Caminando se llega a una estación desde menos de 1 km; en bici, desde varios kilómetros: el área servida se multiplica.","por_opcion":{"o3":"No obliga: suma una opción para llegar a la estación."}}},{"slug":"movilidad-3.s5.p8","orden":8,"grupo":"movilidad-3.s5.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una persona camina hasta una estación desde 0,8 km como máximo y en bici desde 3 km, ¿cuántas veces más grande es el área que cubre la estación con bici? (El área de un círculo crece con el cuadrado del radio.) Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"Radio a pie 0.8 km; radio en bici 3 km."},"solucion":{"valor":14.1,"tolerancia":0.1,"explicacion":"(3 ÷ 0,8)² ≈ 14,1 veces. Por eso la combinación bici + tren es tan poderosa."}},{"slug":"movilidad-3.s5.p8.v2","orden":8,"grupo":"movilidad-3.s5.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una persona camina hasta una estación desde 1 km como máximo y en bici desde 4 km, ¿cuántas veces más grande es el área que cubre la estación con bici? (El área de un círculo crece con el cuadrado del radio.) Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"Radio a pie 1 km; radio en bici 4 km."},"solucion":{"valor":16,"tolerancia":0.1,"explicacion":"(4 ÷ 1)² ≈ 16 veces. Por eso la combinación bici + tren es tan poderosa."}},{"slug":"movilidad-3.s5.p8.v3","orden":8,"grupo":"movilidad-3.s5.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una persona camina hasta una estación desde 0,5 km como máximo y en bici desde 2,5 km, ¿cuántas veces más grande es el área que cubre la estación con bici? (El área de un círculo crece con el cuadrado del radio.) Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"Radio a pie 0.5 km; radio en bici 2.5 km."},"solucion":{"valor":25,"tolerancia":0.1,"explicacion":"(2,5 ÷ 0,5)² ≈ 25 veces. Por eso la combinación bici + tren es tan poderosa."}},{"slug":"movilidad-3.s5.p9","orden":9,"grupo":"movilidad-3.s5.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con una solución.","izquierda":[{"id":"a1","texto":"No sé cuándo llega el colectivo"},{"id":"a2","texto":"No puedo subir con la silla de ruedas"},{"id":"a3","texto":"Me da miedo esperar de noche"},{"id":"a4","texto":"La estación queda lejos de casa"}],"derecha":[{"id":"b1","texto":"Información en tiempo real"},{"id":"b2","texto":"Colectivos de piso bajo con rampa"},{"id":"b3","texto":"Paradas iluminadas y visibles"},{"id":"b4","texto":"Estacionamiento seguro de bicis"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada barrera tiene soluciones concretas."}},{"slug":"movilidad-3.s5.p10","orden":10,"grupo":"movilidad-3.s5.p10","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las partes de un viaje \"puerta a puerta\" en transporte público.","items":[{"id":"i1","texto":"Caminar o pedalear hasta la parada"},{"id":"i2","texto":"Esperar el colectivo"},{"id":"i3","texto":"Viajar arriba del vehículo"},{"id":"i4","texto":"Combinar con otra línea si hace falta"},{"id":"i5","texto":"Hacer el último tramo hasta el destino"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Mejorar solo el tramo arriba del vehículo no alcanza: todas las partes cuentan."}},{"slug":"movilidad-3.s5.p11","orden":11,"grupo":"movilidad-3.s5.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas mejoras según cuántas personas beneficia en una línea muy usada, de más a menos.","items":[{"id":"i1","texto":"Duplicar la frecuencia"},{"id":"i2","texto":"Información en tiempo real en las paradas"},{"id":"i3","texto":"Rampas en todos los colectivos"},{"id":"i4","texto":"Wifi a bordo"}],"extremos":["Más personas","Menos personas"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Todas ayudan, pero la frecuencia mejora el viaje de todas las personas a la vez.","valores":{"i1":"todos los pasajeros","i2":"casi todos","i3":"muchos, en especial quienes más lo necesitan","i4":"algunos"}}},{"slug":"movilidad-3.s5.p12","orden":12,"grupo":"movilidad-3.s5.p12","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una estación tiene ascensor, pero hace meses que no funciona. ¿Es accesible?","opciones":[{"id":"o1","texto":"No: un ascensor roto no le sirve a nadie"},{"id":"o2","texto":"Sí, porque el ascensor está instalado"},{"id":"o3","texto":"Sí, si hay escaleras al lado"},{"id":"o4","texto":"Depende del color del ascensor"}]},"solucion":{"clave":["o1"],"explicacion":"La accesibilidad incluye el mantenimiento: un ascensor roto deja afuera a quien lo necesita.","por_opcion":{"o3":"Las escaleras no sirven a quien usa silla de ruedas."}}},{"slug":"movilidad-3.s5.p13","orden":13,"grupo":"movilidad-3.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe municipal y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Instalamos anuncios sonoros de las paradas."},{"id":"s2","texto":"Las rampas son innecesarias porque pocos pasajeros usan silla de ruedas."},{"id":"s3","texto":"Iluminamos las paradas del recorrido nocturno."},{"id":"s4","texto":"El último tramo no es problema del transporte público."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un sistema pensado para todas las personas termina siendo mejor para cada una.","por_opcion":{"s2":"Benefician a muchos grupos y son un derecho de quienes las necesitan.","s4":"Si llegar a la parada es difícil o inseguro, el sistema pierde pasajeros."}}},{"slug":"movilidad-3.s5.p14","orden":14,"grupo":"movilidad-3.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Diseñar para personas con discapacidad hace un sistema {{0}}; saber cuándo llega el colectivo es información en tiempo {{1}}; y el recorrido desde la parada hasta el destino es el último {{2}}.","banco":[{"id":"w1","texto":"accesible"},{"id":"w2","texto":"real"},{"id":"w3","texto":"tramo"},{"id":"w4","texto":"exclusivo"},{"id":"w5","texto":"pasado"},{"id":"w6","texto":"peaje"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para un transporte público usable por todas las personas."}}]},{"slug":"movilidad-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: transporte público","bajada_es":"Eficiencia, frecuencia, redes, colectivos rápidos, electrificación y accesibilidad, mezclados.","minutos":8,"pasos":[{"slug":"movilidad-3.s6.p1","orden":1,"grupo":"movilidad-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Transporte público». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"movilidad-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la red de Villa Norte","bajada_es":"Una ciudad mediana tiene 12 colectivos y quiere rediseñar su red. Con los datos, elegí la mejor propuesta.","minutos":10,"pasos":[{"slug":"movilidad-3.s7.p1","orden":1,"grupo":"movilidad-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las propuestas","cuerpo":["Villa Norte tiene 12 colectivos. Cada vuelta completa dura 60 minutos. Hoy hay 6 líneas con 2 colectivos cada una, que entran a todos los barrios pero pasan cada 30 minutos, y los pasajeros bajan año tras año. La propuesta A mantiene las 6 líneas. La propuesta B arma 2 líneas troncales por las avenidas principales, con 5 colectivos cada una, más 1 línea barrial con 2 colectivos, y una tarifa integrada para combinar. Además, en las avenidas troncales se puede pintar un carril exclusivo, que bajaría la vuelta de 60 a 50 minutos."]},"solucion":{}},{"slug":"movilidad-3.s7.p2","orden":2,"grupo":"movilidad-3.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En la propuesta B, ¿cada cuántos minutos pasa cada línea troncal, sin carril exclusivo?","unidad":"minutos","decimales":0,"contexto":"Vuelta de 60 minutos; 5 colectivos por troncal."},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"60 ÷ 5 = 12 minutos, contra 30 minutos de hoy. La espera promedio baja de 15 a 6 minutos."}},{"slug":"movilidad-3.s7.p3","orden":3,"grupo":"movilidad-3.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el carril exclusivo, la vuelta de las troncales baja a 50 minutos. ¿Cada cuántos minutos pasarían?","unidad":"minutos","decimales":0,"contexto":"Vuelta de 50 minutos; 5 colectivos por troncal."},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"50 ÷ 5 = 10 minutos, sin comprar colectivos: la velocidad se convierte en frecuencia."}},{"slug":"movilidad-3.s7.p4","orden":4,"grupo":"movilidad-3.s7.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué riesgo tiene la propuesta B y cómo se atiende?","opciones":[{"id":"o1","texto":"Algunos caminan más; se atiende con la línea barrial"},{"id":"o2","texto":"Que los colectivos troncales vayan demasiado vacíos"},{"id":"o3","texto":"Que la frecuencia empeore en todas las líneas"},{"id":"o4","texto":"Que la tarifa integrada cueste más que hoy"}]},"solucion":{"clave":["o1"],"explicacion":"Toda red concentra o reparte. Reconocer quién pierde y compensarlo hace a la propuesta más justa.","por_opcion":{"o3":"Las troncales mejoran mucho; el costo está en la cobertura."}}},{"slug":"movilidad-3.s7.p5","orden":5,"grupo":"movilidad-3.s7.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué elementos hacen que la propuesta B funcione? Marcá todos.","opciones":[{"id":"o1","texto":"Tarifa integrada para no castigar las combinaciones"},{"id":"o2","texto":"Carril exclusivo en las troncales"},{"id":"o3","texto":"Paradas de combinación seguras e iluminadas"},{"id":"o4","texto":"Cobrar doble a quien combina"},{"id":"o5","texto":"Sacar la línea barrial para ahorrar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Una red troncal funciona si combinar es fácil, barato y seguro."}},{"slug":"movilidad-3.s7.p6","orden":6,"grupo":"movilidad-3.s7.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas por impacto en los pasajeros, de mayor a menor.","items":[{"id":"i1","texto":"Pasar de 30 a 10 minutos de frecuencia en las troncales"},{"id":"i2","texto":"Tarifa integrada"},{"id":"i3","texto":"Información en tiempo real"},{"id":"i4","texto":"Pintar los colectivos de otro color"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La frecuencia es la mejora más sentida; la estética casi no cambia el viaje.","valores":{"i1":"enorme","i2":"grande","i3":"media","i4":"mínima"}}},{"slug":"movilidad-3.s7.p7","orden":7,"grupo":"movilidad-3.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La propuesta B no necesita comprar colectivos nuevos para mejorar mucho la frecuencia.","razones":[{"id":"r1","texto":"Porque reorganiza la flota y acelera las vueltas"},{"id":"r2","texto":"Porque duplica la cantidad de colectivos"},{"id":"r3","texto":"Porque elimina todas las líneas"}]},"solucion":{"valor":true,"explicacion":"Reorganiza la misma flota y el carril exclusivo acelera las vueltas. Es una mejora de diseño y de gestión, no de compra.","clave":["r1"]}},{"slug":"movilidad-3.s7.p8","orden":8,"grupo":"movilidad-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio presenta la red nueva. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Las troncales pasarán cada 10 minutos gracias al carril exclusivo."},{"id":"s2","texto":"Quien combine pagará dos boletos completos."},{"id":"s3","texto":"Mantendremos una línea barrial para quienes quedan lejos."},{"id":"s4","texto":"No haremos consultas: los vecinos no saben de transporte."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una buena red se diseña con números y con las personas que la usan.","por_opcion":{"s2":"Sin tarifa integrada, la red castiga a quien combina.","s4":"Quienes viajan conocen sus recorridos; consultarlos mejora el diseño."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"movilidad-4","rama":"movilidad","orden":4,"nivel":2,"titulo_es":"Autos, eléctricos y combustibles","bajada_es":"Nafta, gasoil, GNC, biocombustibles y baterías: cuánto emite de verdad cada opción, qué resuelve el auto eléctrico y qué no resuelve ningún motor.","objetivos_es":["Calcular las emisiones de un auto a partir de su consumo","Comparar nafta, gasoil, GNC y biocombustibles con sus ventajas y límites","Evaluar el auto eléctrico en todo su ciclo de vida","Reconocer los problemas que ningún tipo de motor resuelve","Aplicar el marco evitar–cambiar–mejorar a decisiones de movilidad"],"repasa":["movilidad-1","movilidad-3","energia-3","aire-suelo-3"],"requiere_tronco":2,"fuentes":["epa-auto-tipico","doe-eficiencia-ev","icct-ev-global","icct-ev","iea-ev-outlook","oecd-no-escape","ley-27640-biocombustibles","owid-transporte","oms-aire-exterior","cammesa"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"movilidad-4.s1","orden":1,"tipo":"leccion","titulo_es":"Lo que sale del caño de escape","bajada_es":"Por qué un litro de nafta genera más de dos kilos de CO₂, y qué otros contaminantes emite un motor.","minutos":11,"pasos":[{"slug":"movilidad-4.s1.p1","orden":1,"grupo":"movilidad-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Más CO₂ que nafta","cuerpo":["Un litro de nafta pesa unos 750 gramos, pero al quemarse produce unos 2,3 kilos de CO₂. ¿Cómo puede ser? La nafta está hecha sobre todo de carbono e hidrógeno. Al quemarse, cada átomo de carbono se une con dos átomos de oxígeno que vienen del aire. El oxígeno agrega mucho peso: por cada kilo de carbono se forman unos 3,7 kilos de CO₂.","Según la Agencia de Protección Ambiental de EE. UU., quemar un galón de nafta (3,8 litros) produce unos 8,9 kilos de CO₂."]},"solucion":{}},{"slug":"movilidad-4.s1.p2","orden":2,"grupo":"movilidad-4.s1.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un litro de nafta produce más CO₂ que su propio peso?","opciones":[{"id":"o1","texto":"El carbono se une con oxígeno que viene del aire"},{"id":"o2","texto":"Porque la nafta se expande al calentarse"},{"id":"o3","texto":"Porque el motor fabrica carbono nuevo"},{"id":"o4","texto":"Porque el CO₂ se mide en volumen, no en peso"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste en el tronco: la materia no desaparece ni se crea. El CO₂ suma el oxígeno que toma del aire.","por_opcion":{"o3":"La materia no se crea: el peso extra es oxígeno del aire."}}},{"slug":"movilidad-4.s1.p3","orden":3,"grupo":"movilidad-4.s1.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto consume 8 litros de nafta cada 100 km. Si cada litro produce 2,3 kg de CO₂, ¿cuántos kilos emite en 100 km? Redondeá a un decimal.","unidad":"kg de CO₂","decimales":1,"contexto":"8 L/100 km; 100 km; 2,3 kg por litro."},"solucion":{"valor":18.4,"tolerancia":0.1,"explicacion":"8 × 100 ÷ 100 = 8 litros; × 2,3 = 18,4 kg de CO₂. Cada litro ahorrado son 2,3 kg menos."}},{"slug":"movilidad-4.s1.p3.v2","orden":3,"grupo":"movilidad-4.s1.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto consume 7 litros de nafta cada 100 km. Si cada litro produce 2,3 kg de CO₂, ¿cuántos kilos emite en 250 km? Redondeá a un decimal.","unidad":"kg de CO₂","decimales":1,"contexto":"7 L/100 km; 250 km; 2,3 kg por litro."},"solucion":{"valor":40.3,"tolerancia":0.1,"explicacion":"7 × 250 ÷ 100 = 17.5 litros; × 2,3 = 40,3 kg de CO₂. Cada litro ahorrado son 2,3 kg menos."}},{"slug":"movilidad-4.s1.p3.v3","orden":3,"grupo":"movilidad-4.s1.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto consume 10 litros de nafta cada 100 km. Si cada litro produce 2,3 kg de CO₂, ¿cuántos kilos emite en 40 km? Redondeá a un decimal.","unidad":"kg de CO₂","decimales":1,"contexto":"10 L/100 km; 40 km; 2,3 kg por litro."},"solucion":{"valor":9.2,"tolerancia":0.1,"explicacion":"10 × 40 ÷ 100 = 4 litros; × 2,3 = 9,2 kg de CO₂. Cada litro ahorrado son 2,3 kg menos."}},{"slug":"movilidad-4.s1.p4","orden":4,"grupo":"movilidad-4.s1.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Un año de auto","planteo":"Un auto recorre 12.000 km por año y consume 8 litros cada 100 km.","pasos":["Litros por año: 12.000 × 8 ÷ 100 = 960 litros.","CO₂ por año: 960 × 2,3 ≈ 2.200 kg, es decir, unas 2,2 toneladas.","Por kilómetro: 8 × 2,3 ÷ 100 ≈ 0,18 kg, unos 184 gramos."],"resultado":"Un auto de uso diario puede emitir más de dos toneladas de CO₂ por año, solo por el caño de escape."},"solucion":{}},{"slug":"movilidad-4.s1.p5","orden":5,"grupo":"movilidad-4.s1.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto recorre 10.000 km por año y consume 7 L cada 100 km. Con 2,3 kg de CO₂ por litro, ¿cuántas toneladas emite por año? Redondeá a un decimal.","unidad":"t de CO₂","decimales":1,"contexto":"10000 km/año; 7 L/100 km; 2,3 kg/L."},"solucion":{"valor":1.6,"tolerancia":0.1,"explicacion":"700 litros × 2,3 ≈ 1.610 kg ≈ 1,6 t. Un auto de uso diario pesa mucho en la huella de un hogar."}},{"slug":"movilidad-4.s1.p5.v2","orden":5,"grupo":"movilidad-4.s1.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto recorre 15.000 km por año y consume 9 L cada 100 km. Con 2,3 kg de CO₂ por litro, ¿cuántas toneladas emite por año? Redondeá a un decimal.","unidad":"t de CO₂","decimales":1,"contexto":"15000 km/año; 9 L/100 km; 2,3 kg/L."},"solucion":{"valor":3.1,"tolerancia":0.1,"explicacion":"1.350 litros × 2,3 ≈ 3.105 kg ≈ 3,1 t. Un auto de uso diario pesa mucho en la huella de un hogar."}},{"slug":"movilidad-4.s1.p5.v3","orden":5,"grupo":"movilidad-4.s1.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto recorre 8.000 km por año y consume 6 L cada 100 km. Con 2,3 kg de CO₂ por litro, ¿cuántas toneladas emite por año? Redondeá a un decimal.","unidad":"t de CO₂","decimales":1,"contexto":"8000 km/año; 6 L/100 km; 2,3 kg/L."},"solucion":{"valor":1.1,"tolerancia":0.1,"explicacion":"480 litros × 2,3 ≈ 1.104 kg ≈ 1,1 t. Un auto de uso diario pesa mucho en la huella de un hogar."}},{"slug":"movilidad-4.s1.p6","orden":6,"grupo":"movilidad-4.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto emitió 1.150 kg de CO₂ en un año por el caño de escape. Si cada litro de nafta produce 2,3 kg, ¿cuántos litros quemó?","unidad":"litros","decimales":0,"contexto":"1150 kg de CO₂ en un año; 2,3 kg por litro."},"solucion":{"valor":500,"tolerancia":10,"explicacion":"1.150 ÷ 2,3 = 500 litros. La misma cuenta, al revés: con la factura de combustible se puede estimar la huella del auto."}},{"slug":"movilidad-4.s1.p6.v2","orden":6,"grupo":"movilidad-4.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto emitió 1.380 kg de CO₂ en un año por el caño de escape. Si cada litro de nafta produce 2,3 kg, ¿cuántos litros quemó?","unidad":"litros","decimales":0,"contexto":"1380 kg de CO₂ en un año; 2,3 kg por litro."},"solucion":{"valor":600,"tolerancia":12,"explicacion":"1.380 ÷ 2,3 = 600 litros. La misma cuenta, al revés: con la factura de combustible se puede estimar la huella del auto."}},{"slug":"movilidad-4.s1.p6.v3","orden":6,"grupo":"movilidad-4.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto emitió 2.070 kg de CO₂ en un año por el caño de escape. Si cada litro de nafta produce 2,3 kg, ¿cuántos litros quemó?","unidad":"litros","decimales":0,"contexto":"2070 kg de CO₂ en un año; 2,3 kg por litro."},"solucion":{"valor":900,"tolerancia":18,"explicacion":"2.070 ÷ 2,3 = 900 litros. La misma cuenta, al revés: con la factura de combustible se puede estimar la huella del auto."}},{"slug":"movilidad-4.s1.p7","orden":7,"grupo":"movilidad-4.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No solo CO₂","cuerpo":["Además de CO₂, los motores emiten contaminantes que afectan la salud de quienes respiran cerca: óxidos de nitrógeno (sobre todo los motores diésel), partículas finas, monóxido de carbono y compuestos que forman ozono. El CO₂ es un problema global de clima; estos otros son un problema local de salud, en las calles donde vivimos."]},"solucion":{}},{"slug":"movilidad-4.s1.p8","orden":8,"grupo":"movilidad-4.s1.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un problema global de clima o local de salud?","grupos":[{"id":"g1","nombre":"Clima global"},{"id":"g2","nombre":"Salud local"}],"items":[{"id":"i1","texto":"CO₂ del caño de escape"},{"id":"i2","texto":"Óxidos de nitrógeno de un motor diésel"},{"id":"i3","texto":"Partículas finas en una avenida"},{"id":"i4","texto":"Monóxido de carbono en un garaje cerrado"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g2","i4":"g2"},"explicacion":"Un mismo auto genera los dos tipos de problema: por eso las soluciones deben mirar ambos."}},{"slug":"movilidad-4.s1.p9","orden":9,"grupo":"movilidad-4.s1.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada contaminante con su efecto principal.","izquierda":[{"id":"a1","texto":"CO₂"},{"id":"a2","texto":"Óxidos de nitrógeno"},{"id":"a3","texto":"Partículas finas"},{"id":"a4","texto":"Monóxido de carbono"}],"derecha":[{"id":"b1","texto":"Calentamiento global"},{"id":"b2","texto":"Irritan las vías respiratorias y forman ozono"},{"id":"b3","texto":"Penetran en los pulmones y la sangre"},{"id":"b4","texto":"Impide que la sangre transporte oxígeno"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Lo viste en la unidad del aire: cada contaminante afecta de forma distinta."}},{"slug":"movilidad-4.s1.p10","orden":10,"grupo":"movilidad-4.s1.p10","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un auto que no larga humo visible no emite CO₂.","razones":[{"id":"r1","texto":"Porque el CO₂ es invisible"},{"id":"r2","texto":"Porque el CO₂ siempre se ve como humo negro"},{"id":"r3","texto":"Porque los autos nuevos no queman combustible"}]},"solucion":{"valor":false,"explicacion":"El CO₂ es invisible. Todo auto que quema combustible emite CO₂, se vea humo o no.","clave":["r1"]}},{"slug":"movilidad-4.s1.p11","orden":11,"grupo":"movilidad-4.s1.p11","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas toneladas de CO₂ emite por año un auto típico en Estados Unidos, según la EPA.","min":0.1,"max":50,"paso":1,"unidad":"t","escala":"log"},"solucion":{"valor":4.6,"banda":"log","explicacion":"Unas 4,6 toneladas por año, según la EPA, con el consumo y los kilómetros promedio de ese país, que son mayores que en Argentina."}},{"slug":"movilidad-4.s1.p12","orden":12,"grupo":"movilidad-4.s1.p12","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de dónde viene el CO₂ de un auto.","items":[{"id":"i1","texto":"La nafta contiene carbono de origen fósil"},{"id":"i2","texto":"En el motor se quema con oxígeno del aire"},{"id":"i3","texto":"Cada carbono forma una molécula de CO₂"},{"id":"i4","texto":"El CO₂ sale por el caño de escape"},{"id":"i5","texto":"Se suma al CO₂ acumulado en la atmósfera"},{"id":"i6","texto":"El catalizador convierte el CO₂ en oxígeno"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El catalizador reduce otros contaminantes, pero no elimina el CO₂."}},{"slug":"movilidad-4.s1.p13","orden":13,"grupo":"movilidad-4.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Un litro de nafta produce más de 2 kg de CO₂."},{"id":"s2","texto":"El catalizador del auto elimina el CO₂."},{"id":"s3","texto":"Los motores diésel emiten muchos óxidos de nitrógeno."},{"id":"s4","texto":"Si el auto consume menos, emite lo mismo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La cuenta es simple: cada litro quemado es CO₂ emitido.","por_opcion":{"s2":"Reduce otros contaminantes, pero el CO₂ sale igual.","s4":"Las emisiones de CO₂ son proporcionales a los litros quemados."}}},{"slug":"movilidad-4.s1.p14","orden":14,"grupo":"movilidad-4.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un litro de nafta produce unos {{0}} kg de CO₂; el peso extra viene del {{1}} del aire; y el catalizador no elimina el {{2}}.","banco":[{"id":"w1","texto":"2,3"},{"id":"w2","texto":"oxígeno"},{"id":"w3","texto":"CO₂"},{"id":"w4","texto":"0,7"},{"id":"w5","texto":"agua"},{"id":"w6","texto":"ruido"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave para entender las emisiones de un auto."}}]},{"slug":"movilidad-4.s2","orden":2,"tipo":"leccion","titulo_es":"Nafta, gasoil, GNC y biocombustibles","bajada_es":"Cada combustible tiene ventajas y límites. Ninguno es neutro.","minutos":11,"pasos":[{"slug":"movilidad-4.s2.p1","orden":1,"grupo":"movilidad-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Gasoil y nafta","cuerpo":["El gasoil tiene más energía por litro que la nafta y los motores diésel suelen ser más eficientes, así que consumen menos litros por kilómetro. Pero cada litro de gasoil produce algo más de CO₂ que uno de nafta (unos 2,7 kg), y los motores diésel emiten más óxidos de nitrógeno y partículas si no tienen filtros modernos. En emisiones de CO₂ por kilómetro, la diferencia entre un auto a nafta y uno diésel parecidos suele ser chica."]},"solucion":{}},{"slug":"movilidad-4.s2.p2","orden":2,"grupo":"movilidad-4.s2.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto a nafta consume 8 L/100 km (2,3 kg de CO₂ por litro) y uno diésel 6 L/100 km (2,7 kg por litro). ¿Cuántos kilos de CO₂ cada 100 km emite de menos el diésel? Redondeá a un decimal.","unidad":"kg","decimales":1,"contexto":"Nafta 8 L/100 km; diésel 6 L/100 km."},"solucion":{"valor":2.2,"tolerancia":0.1,"explicacion":"Nafta: 8 × 2,3 = 18,4 kg. Diésel: 6 × 2,7 = 16,2 kg. Diferencia: 2,2 kg. Menos CO₂, pero más óxidos de nitrógeno si no tiene filtros modernos."}},{"slug":"movilidad-4.s2.p2.v2","orden":2,"grupo":"movilidad-4.s2.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto a nafta consume 9 L/100 km (2,3 kg de CO₂ por litro) y uno diésel 7 L/100 km (2,7 kg por litro). ¿Cuántos kilos de CO₂ cada 100 km emite de menos el diésel? Redondeá a un decimal.","unidad":"kg","decimales":1,"contexto":"Nafta 9 L/100 km; diésel 7 L/100 km."},"solucion":{"valor":1.8,"tolerancia":0.1,"explicacion":"Nafta: 9 × 2,3 = 20,7 kg. Diésel: 7 × 2,7 = 18,9 kg. Diferencia: 1,8 kg. Menos CO₂, pero más óxidos de nitrógeno si no tiene filtros modernos."}},{"slug":"movilidad-4.s2.p2.v3","orden":2,"grupo":"movilidad-4.s2.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto a nafta consume 7 L/100 km (2,3 kg de CO₂ por litro) y uno diésel 5,5 L/100 km (2,7 kg por litro). ¿Cuántos kilos de CO₂ cada 100 km emite de menos el diésel? Redondeá a un decimal.","unidad":"kg","decimales":1,"contexto":"Nafta 7 L/100 km; diésel 5.5 L/100 km."},"solucion":{"valor":1.2,"tolerancia":0.1,"explicacion":"Nafta: 7 × 2,3 = 16,1 kg. Diésel: 5,5 × 2,7 = 14,85 kg. Diferencia: 1,2 kg. Menos CO₂, pero más óxidos de nitrógeno si no tiene filtros modernos."}},{"slug":"movilidad-4.s2.p3","orden":3,"grupo":"movilidad-4.s2.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un auto diésel consume menos litros cada 100 km que uno a nafta parecido. ¿Por qué no emite mucho menos CO₂?","opciones":[{"id":"o1","texto":"Cada litro de gasoil tiene más carbono y emite más CO₂"},{"id":"o2","texto":"Porque el gasoil no se quema del todo en el motor"},{"id":"o3","texto":"Porque los autos diésel son siempre más pesados"},{"id":"o4","texto":"Porque el gasoil se evapora antes de usarse"}]},"solucion":{"clave":["o1"],"explicacion":"Menos litros, pero cada uno con más carbono: la ventaja en CO₂ por kilómetro termina siendo chica.","por_opcion":{"o3":"El peso influye poco acá: la clave es el carbono de cada litro."}}},{"slug":"movilidad-4.s2.p4","orden":4,"grupo":"movilidad-4.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"GNC","cuerpo":["Argentina es uno de los países con más vehículos a gas natural comprimido (GNC) del mundo. El GNC es mayormente metano: al quemarse, emite algo menos de CO₂ por kilómetro que la nafta, del orden de un 20 %, y muchas menos partículas. Pero el metano que se escapa en la extracción y el transporte del gas calienta mucho: si hay fugas importantes en la cadena, la ventaja climática se achica."]},"solucion":{}},{"slug":"movilidad-4.s2.p5","orden":5,"grupo":"movilidad-4.s2.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué puede achicar la ventaja climática del GNC frente a la nafta?","opciones":[{"id":"o1","texto":"Las fugas de metano en la cadena del gas"},{"id":"o2","texto":"Que el GNC emite más partículas que el gasoil"},{"id":"o3","texto":"Que el GNC es un combustible renovable"},{"id":"o4","texto":"Que los tubos de GNC pesan poco"}]},"solucion":{"clave":["o1"],"explicacion":"El metano calienta mucho más que el CO₂ en el corto plazo: las fugas cuentan, y mucho.","por_opcion":{"o3":"No lo es: el gas natural es un combustible fósil."}}},{"slug":"movilidad-4.s2.p6","orden":6,"grupo":"movilidad-4.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Biocombustibles","cuerpo":["El bioetanol se hace con caña de azúcar o maíz, y el biodiésel con aceites como el de soja. En Argentina, la Ley 27.640, de 2021, fijó un corte obligatorio de 12 % de bioetanol en la nafta y de 7,5 % de biodiésel en el gasoil. Las plantas absorbieron CO₂ al crecer, lo que puede compensar parte de lo que se emite al quemarlos. Pero su balance depende de cómo se producen: si para cultivarlos se desmontan bosques, o se usan muchos fertilizantes y combustibles en el campo, el beneficio se reduce o desaparece."]},"solucion":{}},{"slug":"movilidad-4.s2.p7","orden":7,"grupo":"movilidad-4.s2.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un biocombustible puede no ser tan limpio.","items":[{"id":"i1","texto":"Crece la demanda de soja para biodiésel"},{"id":"i2","texto":"Se desmonta bosque para sembrar más soja"},{"id":"i3","texto":"El bosque libera el carbono que guardaba"},{"id":"i4","texto":"Esa emisión puede superar el ahorro del biodiésel"},{"id":"i5","texto":"La soja absorbe más carbono que el bosque que reemplaza"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo viste con el desmonte en el Chaco: el cambio de uso del suelo puede anular el beneficio."}},{"slug":"movilidad-4.s2.p8","orden":8,"grupo":"movilidad-4.s2.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cargás 40 litros de nafta con un corte del 12 % de bioetanol, ¿cuántos litros de bioetanol hay en el tanque?","unidad":"litros","decimales":1},"solucion":{"valor":4.8,"tolerancia":0.1,"explicacion":"40 × 0,12 = 4,8 litros. El resto, 35,2 litros, es nafta de origen fósil."}},{"slug":"movilidad-4.s2.p8.v2","orden":8,"grupo":"movilidad-4.s2.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cargás 50 litros de nafta con un corte del 12 % de bioetanol, ¿cuántos litros de bioetanol hay en el tanque?","unidad":"litros","decimales":1},"solucion":{"valor":6,"tolerancia":0.1,"explicacion":"50 × 0,12 = 6 litros. El resto, 44 litros, es nafta de origen fósil."}},{"slug":"movilidad-4.s2.p8.v3","orden":8,"grupo":"movilidad-4.s2.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cargás 30 litros de nafta con un corte del 12 % de bioetanol, ¿cuántos litros de bioetanol hay en el tanque?","unidad":"litros","decimales":1},"solucion":{"valor":3.6,"tolerancia":0.1,"explicacion":"30 × 0,12 = 3,6 litros. El resto, 26,4 litros, es nafta de origen fósil."}},{"slug":"movilidad-4.s2.p9","orden":9,"grupo":"movilidad-4.s2.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una ventaja o un límite de este combustible?","grupos":[{"id":"g1","nombre":"Ventaja"},{"id":"g2","nombre":"Límite"}],"items":[{"id":"i1","texto":"El GNC emite menos partículas"},{"id":"i2","texto":"Fugas de metano en la cadena del GNC"},{"id":"i3","texto":"El bioetanol viene de plantas que absorbieron CO₂"},{"id":"i4","texto":"Desmontes para cultivar biocombustibles"},{"id":"i5","texto":"El diésel consume menos litros por km"},{"id":"i6","texto":"Más óxidos de nitrógeno en diésel sin filtros"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Ningún combustible es \"limpio\" o \"sucio\" sin matices: hay que mirar toda la cadena."}},{"slug":"movilidad-4.s2.p10","orden":10,"grupo":"movilidad-4.s2.p10","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada combustible con su origen.","izquierda":[{"id":"a1","texto":"Nafta"},{"id":"a2","texto":"GNC"},{"id":"a3","texto":"Bioetanol"},{"id":"a4","texto":"Biodiésel"}],"derecha":[{"id":"b1","texto":"Petróleo refinado"},{"id":"b2","texto":"Gas natural, mayormente metano"},{"id":"b3","texto":"Caña de azúcar o maíz"},{"id":"b4","texto":"Aceites vegetales como el de soja"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conocer el origen ayuda a entender el impacto de cada combustible."}},{"slug":"movilidad-4.s2.p11","orden":11,"grupo":"movilidad-4.s2.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como los biocombustibles vienen de plantas, siempre tienen emisiones netas cero.","razones":[{"id":"r1","texto":"Porque producirlos emite y pueden causar desmontes"},{"id":"r2","texto":"Porque las plantas no absorben CO₂"},{"id":"r3","texto":"Porque los biocombustibles no se queman"}]},"solucion":{"valor":false,"explicacion":"Cultivarlos, fertilizarlos, transportarlos y procesarlos emite gases, y si provocan desmontes, las emisiones pueden ser mayores que las de un combustible fósil.","clave":["r1"]}},{"slug":"movilidad-4.s2.p12","orden":12,"grupo":"movilidad-4.s2.p12","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos factores según cuánto pueden empeorar el balance de un biocombustible, de más a menos.","items":[{"id":"i1","texto":"Desmontar un bosque nativo para cultivar la materia prima"},{"id":"i2","texto":"Usar mucho fertilizante nitrogenado"},{"id":"i3","texto":"Transportarlo largas distancias"},{"id":"i4","texto":"Envasarlo en tanques reutilizables"}],"extremos":["Empeora más","Empeora menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El cambio de uso del suelo es, por lejos, el factor que más pesa.","valores":{"i1":"enorme","i2":"importante","i3":"moderado","i4":"mínimo"}}},{"slug":"movilidad-4.s2.p13","orden":13,"grupo":"movilidad-4.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Nuestra nafta contiene 12 % de bioetanol, como exige la ley."},{"id":"s2","texto":"Con nuestra nafta, tu auto no emite CO₂."},{"id":"s3","texto":"El GNC emite menos partículas que el gasoil."},{"id":"s4","texto":"El GNC es 100 % renovable."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo viste con el greenwashing: una verdad parcial puede usarse para engañar.","por_opcion":{"s2":"El 88 % sigue siendo fósil y todo el combustible emite CO₂ al quemarse.","s4":"El gas natural es un combustible fósil."}}},{"slug":"movilidad-4.s2.p14","orden":14,"grupo":"movilidad-4.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En Argentina, la nafta lleva un {{0}} % de bioetanol; el GNC es mayormente {{1}}; y el beneficio de un biocombustible puede desaparecer si causa {{2}}.","banco":[{"id":"w1","texto":"12"},{"id":"w2","texto":"metano"},{"id":"w3","texto":"desmontes"},{"id":"w4","texto":"50"},{"id":"w5","texto":"hidrógeno"},{"id":"w6","texto":"lluvias"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para comparar combustibles sin simplificar."}}]},{"slug":"movilidad-4.s3","orden":3,"tipo":"leccion","titulo_es":"El auto eléctrico","bajada_es":"Eficiencia, batería, red eléctrica y ciclo de vida: qué dice la evidencia sobre los autos eléctricos.","minutos":12,"pasos":[{"slug":"movilidad-4.s3.p1","orden":1,"grupo":"movilidad-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Eficiencia","cuerpo":["Según el Departamento de Energía de EE. UU., un auto a nafta usa solo entre el 12 % y el 30 % de la energía del combustible para mover el auto; el resto se pierde, sobre todo como calor. Un auto eléctrico convierte más del 77 % de la energía que toma de la red en movimiento de las ruedas. Además, al frenar recupera parte de la energía (frenado regenerativo)."],"datos":{"tipo":"barras","titulo":"Energía que llega a las ruedas (aproximado)","unidad":"%","filas":[{"etiqueta":"Auto a nafta","valor":21},{"etiqueta":"Auto eléctrico","valor":77}],"nota":"Departamento de Energía de EE. UU.; para la nafta, punto medio del rango 12–30 %."}},"solucion":{}},{"slug":"movilidad-4.s3.p2","orden":2,"grupo":"movilidad-4.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un auto a nafta aprovecha el 21 % de la energía y uno eléctrico el 77 %, ¿cuántas unidades de energía llegan a las ruedas de cada uno por cada 100 unidades que cargan? Respondé la diferencia. Redondeá al entero.","unidad":"unidades","decimales":0,"contexto":"100 unidades de energía; 21 % y 77 % de aprovechamiento."},"solucion":{"valor":56,"tolerancia":1,"explicacion":"Eléctrico: 100 × 0,77 ≈ 77. Nafta: 100 × 0,21 ≈ 21. Diferencia ≈ 56. El motor eléctrico desperdicia mucho menos."}},{"slug":"movilidad-4.s3.p2.v2","orden":2,"grupo":"movilidad-4.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un auto a nafta aprovecha el 21 % de la energía y uno eléctrico el 77 %, ¿cuántas unidades de energía llegan a las ruedas de cada uno por cada 60 unidades que cargan? Respondé la diferencia. Redondeá al entero.","unidad":"unidades","decimales":0,"contexto":"60 unidades de energía; 21 % y 77 % de aprovechamiento."},"solucion":{"valor":34,"tolerancia":1,"explicacion":"Eléctrico: 60 × 0,77 ≈ 46. Nafta: 60 × 0,21 ≈ 13. Diferencia ≈ 34. El motor eléctrico desperdicia mucho menos."}},{"slug":"movilidad-4.s3.p2.v3","orden":2,"grupo":"movilidad-4.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un auto a nafta aprovecha el 21 % de la energía y uno eléctrico el 77 %, ¿cuántas unidades de energía llegan a las ruedas de cada uno por cada 250 unidades que cargan? Respondé la diferencia. Redondeá al entero.","unidad":"unidades","decimales":0,"contexto":"250 unidades de energía; 21 % y 77 % de aprovechamiento."},"solucion":{"valor":140,"tolerancia":1,"explicacion":"Eléctrico: 250 × 0,77 ≈ 193. Nafta: 250 × 0,21 ≈ 53. Diferencia ≈ 140. El motor eléctrico desperdicia mucho menos."}},{"slug":"movilidad-4.s3.p3","orden":3,"grupo":"movilidad-4.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La batería y la red","cuerpo":["Fabricar un auto eléctrico emite más que fabricar uno a nafta, sobre todo por la batería. Pero al usarlo emite mucho menos, porque es más eficiente y porque la electricidad puede venir de fuentes con pocas emisiones. Cuánto menos depende de la red eléctrica: con más renovables, hidro y nuclear, menos emisiones. En Argentina, la electricidad todavía viene en buena parte de centrales a gas, pero las renovables vienen creciendo."]},"solucion":{}},{"slug":"movilidad-4.s3.p4","orden":4,"grupo":"movilidad-4.s3.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el ciclo de vida de las emisiones de un auto eléctrico.","items":[{"id":"i1","texto":"Se extraen minerales y se fabrica la batería"},{"id":"i2","texto":"El auto sale de fábrica con más emisiones que uno a nafta"},{"id":"i3","texto":"En cada kilómetro emite menos que uno a nafta"},{"id":"i4","texto":"Después de unos años de uso, compensa la diferencia inicial"},{"id":"i5","texto":"A lo largo de su vida, emite menos en total"},{"id":"i6","texto":"El auto eléctrico no tiene ninguna emisión de fabricación"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Hay que mirar toda la vida del auto, no solo el caño de escape ni solo la fábrica."}},{"slug":"movilidad-4.s3.p5","orden":5,"grupo":"movilidad-4.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que dice la evidencia","cuerpo":["Un estudio del ICCT de 2021 comparó las emisiones de todo el ciclo de vida de autos medianos en distintas regiones. Los eléctricos a batería emitían entre un 66 y un 69 % menos que los de nafta en Europa, entre un 60 y un 68 % menos en Estados Unidos, entre un 37 y un 45 % menos en China y entre un 19 y un 34 % menos en India. La diferencia entre regiones se explica sobre todo por cuánto carbón hay en la red eléctrica."],"datos":{"tipo":"tabla","titulo":"Reducción de emisiones de ciclo de vida del auto eléctrico frente al de nafta (ICCT, 2021)","columnas":["Región","Reducción"],"filas":[["Europa","66–69 %"],["Estados Unidos","60–68 %"],["China","37–45 %"],["India","19–34 %"]]}},"solucion":{}},{"slug":"movilidad-4.s3.p6","orden":6,"grupo":"movilidad-4.s3.p6","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las regiones según cuánto reduce emisiones un auto eléctrico frente a uno a nafta, de más a menos.","items":[{"id":"i1","texto":"Europa"},{"id":"i2","texto":"Estados Unidos"},{"id":"i3","texto":"China"},{"id":"i4","texto":"India"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Donde la electricidad depende más del carbón, la ventaja es menor, pero en todos los casos existe.","valores":{"i1":"66–69 %","i2":"60–68 %","i3":"37–45 %","i4":"19–34 %"}}},{"slug":"movilidad-4.s3.p7","orden":7,"grupo":"movilidad-4.s3.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un auto eléctrico reduce menos emisiones en India que en Europa?","opciones":[{"id":"o1","texto":"Porque la electricidad de India usa más carbón"},{"id":"o2","texto":"Porque en India los autos eléctricos son más pesados"},{"id":"o3","texto":"Porque en Europa no se fabrican baterías"},{"id":"o4","texto":"Porque en India se maneja más rápido"}]},"solucion":{"clave":["o1"],"explicacion":"La red eléctrica define cuánto emite cada kilómetro de un auto eléctrico.","por_opcion":{"o3":"Se fabrican en muchos lugares; la diferencia está en la red eléctrica."}}},{"slug":"movilidad-4.s3.p8","orden":8,"grupo":"movilidad-4.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico consume 15 kWh cada 100 km. Si la red emite 0,35 kg de CO₂ por kWh, ¿cuántos gramos de CO₂ por km le corresponden? Redondeá al entero.","unidad":"g/km","decimales":0,"contexto":"15 kWh/100 km; 0.35 kg CO₂/kWh."},"solucion":{"valor":53,"tolerancia":1,"explicacion":"15 × 0,35 = 5,25 kg cada 100 km, o sea 53 g/km. Un auto a nafta de 8 L/100 km emite unos 184 g/km solo por el escape."}},{"slug":"movilidad-4.s3.p8.v2","orden":8,"grupo":"movilidad-4.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico consume 18 kWh cada 100 km. Si la red emite 0,4 kg de CO₂ por kWh, ¿cuántos gramos de CO₂ por km le corresponden? Redondeá al entero.","unidad":"g/km","decimales":0,"contexto":"18 kWh/100 km; 0.4 kg CO₂/kWh."},"solucion":{"valor":72,"tolerancia":1,"explicacion":"18 × 0,4 = 7,2 kg cada 100 km, o sea 72 g/km. Un auto a nafta de 8 L/100 km emite unos 184 g/km solo por el escape."}},{"slug":"movilidad-4.s3.p8.v3","orden":8,"grupo":"movilidad-4.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico consume 14 kWh cada 100 km. Si la red emite 0,3 kg de CO₂ por kWh, ¿cuántos gramos de CO₂ por km le corresponden? Redondeá al entero.","unidad":"g/km","decimales":0,"contexto":"14 kWh/100 km; 0.3 kg CO₂/kWh."},"solucion":{"valor":42,"tolerancia":1,"explicacion":"14 × 0,3 = 4,2 kg cada 100 km, o sea 42 g/km. Un auto a nafta de 8 L/100 km emite unos 184 g/km solo por el escape."}},{"slug":"movilidad-4.s3.p9","orden":9,"grupo":"movilidad-4.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Crecen rápido","cuerpo":["Según la Agencia Internacional de Energía, en 2024 se vendieron en el mundo más de 17 millones de autos eléctricos, más de uno de cada cinco autos nuevos. China concentra la mayor parte de las ventas. En Argentina son todavía muy pocos, pero crecen, y aparecen cargadores en ciudades y rutas."]},"solucion":{}},{"slug":"movilidad-4.s3.p10","orden":10,"grupo":"movilidad-4.s3.p10","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos autos eléctricos se vendieron en el mundo en 2024, según la AIE.","min":100000,"max":1000000000,"paso":1,"unidad":"autos","escala":"log"},"solucion":{"valor":17000000,"banda":"log","explicacion":"Más de 17 millones, más de uno de cada cinco autos nuevos vendidos en el mundo."}},{"slug":"movilidad-4.s3.p11","orden":11,"grupo":"movilidad-4.s3.p11","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un auto eléctrico cargado con una red que usa gas emite lo mismo que uno a nafta.","razones":[{"id":"r1","texto":"Porque es más eficiente y la red puede limpiarse con el tiempo"},{"id":"r2","texto":"Porque la electricidad de gas no emite nada"},{"id":"r3","texto":"Porque los autos a nafta son más eficientes"}]},"solucion":{"valor":false,"explicacion":"Aun con electricidad de gas, su mayor eficiencia suele darle ventaja. Y a medida que la red suma renovables, la ventaja crece durante toda la vida del auto.","clave":["r1"]}},{"slug":"movilidad-4.s3.p12","orden":12,"grupo":"movilidad-4.s3.p12","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este factor aumenta o reduce la ventaja climática de un auto eléctrico?","grupos":[{"id":"g1","nombre":"Aumenta la ventaja"},{"id":"g2","nombre":"Reduce la ventaja"}],"items":[{"id":"i1","texto":"Una red con más renovables"},{"id":"i2","texto":"Una red con mucho carbón"},{"id":"i3","texto":"Un auto chico y liviano"},{"id":"i4","texto":"Una batería enorme que casi nunca se aprovecha"},{"id":"i5","texto":"Usarlo muchos años"},{"id":"i6","texto":"Un vehículo muy pesado"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El mismo tipo de auto puede tener huellas muy distintas según cómo se fabrica, dónde se carga y cómo se usa."}},{"slug":"movilidad-4.s3.p13","orden":13,"grupo":"movilidad-4.s3.p13","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término con su definición.","izquierda":[{"id":"a1","texto":"Frenado regenerativo"},{"id":"a2","texto":"Autonomía"},{"id":"a3","texto":"kWh cada 100 km"},{"id":"a4","texto":"Ciclo de vida"}],"derecha":[{"id":"b1","texto":"Recuperar energía al frenar"},{"id":"b2","texto":"Kilómetros que recorre con una carga"},{"id":"b3","texto":"Consumo de un auto eléctrico"},{"id":"b4","texto":"Emisiones desde la fabricación hasta el desguace"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Vocabulario para leer comparaciones de autos sin confundirse."}},{"slug":"movilidad-4.s3.p14","orden":14,"grupo":"movilidad-4.s3.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este debate y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Fabricar un auto eléctrico emite más, sobre todo por la batería."},{"id":"s2","texto":"El auto eléctrico emite cero en todo su ciclo de vida."},{"id":"s3","texto":"La ventaja del eléctrico depende de la red eléctrica."},{"id":"s4","texto":"Un auto a nafta aprovecha casi toda la energía de su combustible."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Ni \"cero emisiones\" ni \"igual que un auto a nafta\": la evidencia está en el medio, y favorece al eléctrico.","por_opcion":{"s2":"Su fabricación y la electricidad tienen emisiones, aunque en total suelen ser menores.","s4":"Aprovecha solo entre el 12 y el 30 %."}}},{"slug":"movilidad-4.s3.p15","orden":15,"grupo":"movilidad-4.s3.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un auto eléctrico convierte más del {{0}} % de la energía en movimiento; su mayor emisión de fabricación viene de la {{1}}; y su ventaja depende de la red {{2}}.","banco":[{"id":"w1","texto":"77"},{"id":"w2","texto":"batería"},{"id":"w3","texto":"eléctrica"},{"id":"w4","texto":"30"},{"id":"w5","texto":"pintura"},{"id":"w6","texto":"vial"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para evaluar un auto eléctrico con justicia."}}]},{"slug":"movilidad-4.s4","orden":4,"tipo":"leccion","titulo_es":"Lo que ningún motor resuelve","bajada_es":"Peso, partículas de frenos y cubiertas, espacio, tránsito y seguridad: problemas que siguen ahí con cualquier motor.","minutos":12,"pasos":[{"slug":"movilidad-4.s4.p1","orden":1,"grupo":"movilidad-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Más grandes, más pesados","cuerpo":["En muchos países crece la venta de camionetas y SUV, más grandes y pesados que los autos comunes. Un vehículo más pesado necesita más energía para moverse, sea a nafta o eléctrico, ocupa más espacio y, en un choque, es más peligroso para peatones y ciclistas. Un SUV eléctrico emite menos que un SUV a nafta, pero puede emitir más que un auto chico eficiente."]},"solucion":{}},{"slug":"movilidad-4.s4.p2","orden":2,"grupo":"movilidad-4.s4.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué problema tienen los vehículos cada vez más grandes y pesados, aunque sean eléctricos?","opciones":[{"id":"o1","texto":"Usan más energía y son más peligrosos para peatones"},{"id":"o2","texto":"Que no pueden cargar combustible en estaciones"},{"id":"o3","texto":"Que emiten más humo por el caño de escape"},{"id":"o4","texto":"Que no entran en ninguna ruta del país"}]},"solucion":{"clave":["o1"],"explicacion":"El tamaño y el peso importan más allá del tipo de motor.","por_opcion":{"o3":"Si son eléctricos no tienen escape; el problema es el peso."}}},{"slug":"movilidad-4.s4.p3","orden":3,"grupo":"movilidad-4.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Partículas sin escape","cuerpo":["Los autos también emiten partículas que no salen del caño de escape: el desgaste de los frenos, de las cubiertas y del asfalto, y el polvo que levantan. Según la OCDE, a medida que los escapes se vuelven más limpios, estas partículas pasan a ser la mayor parte de las partículas del tránsito. Los eléctricos frenan en parte con el motor y gastan menos frenos, pero al ser más pesados pueden gastar más las cubiertas."]},"solucion":{}},{"slug":"movilidad-4.s4.p4","orden":4,"grupo":"movilidad-4.s4.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta emisión sale del caño de escape o no?","grupos":[{"id":"g1","nombre":"Del caño de escape"},{"id":"g2","nombre":"No sale del escape"}],"items":[{"id":"i1","texto":"CO₂ de la nafta quemada"},{"id":"i2","texto":"Polvo del desgaste de frenos"},{"id":"i3","texto":"Óxidos de nitrógeno de un motor diésel"},{"id":"i4","texto":"Partículas del desgaste de las cubiertas"},{"id":"i5","texto":"Polvo del asfalto levantado al pasar"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Un auto eléctrico elimina las primeras, pero no las segundas."}},{"slug":"movilidad-4.s4.p5","orden":5,"grupo":"movilidad-4.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un auto eléctrico no emite ninguna partícula contaminante.","razones":[{"id":"r1","texto":"Porque frenos, cubiertas y asfalto también emiten partículas"},{"id":"r2","texto":"Porque emite humo por el escape"},{"id":"r3","texto":"Porque las partículas solo vienen del escape"}]},"solucion":{"valor":false,"explicacion":"No tiene escape, pero emite partículas por el desgaste de frenos, cubiertas y asfalto, que dependen mucho del peso del vehículo.","clave":["r1"]}},{"slug":"movilidad-4.s4.p6","orden":6,"grupo":"movilidad-4.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Espacio, tránsito y seguridad","cuerpo":["Un auto eléctrico ocupa el mismo espacio que uno a nafta: en un embotellamiento, cambiar el motor no cambia nada. Tampoco cambia el riesgo de siniestros viales, que dependen de la velocidad, el diseño de las calles y el comportamiento. Ni el sedentarismo de quien viaja sentado. Por eso, electrificar los autos es necesario pero no suficiente: también hace falta menos dependencia del auto."]},"solucion":{}},{"slug":"movilidad-4.s4.p7","orden":7,"grupo":"movilidad-4.s4.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas NO resuelve cambiar autos a nafta por eléctricos? Marcá todos.","opciones":[{"id":"o1","texto":"La congestión en las avenidas"},{"id":"o2","texto":"El espacio que ocupan los autos estacionados"},{"id":"o3","texto":"Los siniestros viales"},{"id":"o4","texto":"El humo del caño de escape en la calle"},{"id":"o5","texto":"Las emisiones por quemar nafta"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Electrificar resuelve el escape; el espacio, el tránsito y la seguridad necesitan otras soluciones."}},{"slug":"movilidad-4.s4.p8","orden":8,"grupo":"movilidad-4.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto chico pesa 1.200 kg y un SUV grande 2.000 kg. ¿En qué porcentaje es más pesado el SUV? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"1200 kg frente a 2000 kg."},"solucion":{"valor":67,"tolerancia":1,"explicacion":"(2.000 − 1.200) ÷ 1.200 × 100 ≈ 67 %. Más peso significa más energía, más desgaste de cubiertas y más daño en un choque."}},{"slug":"movilidad-4.s4.p8.v2","orden":8,"grupo":"movilidad-4.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto chico pesa 1.300 kg y un SUV grande 2.400 kg. ¿En qué porcentaje es más pesado el SUV? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"1300 kg frente a 2400 kg."},"solucion":{"valor":85,"tolerancia":1,"explicacion":"(2.400 − 1.300) ÷ 1.300 × 100 ≈ 85 %. Más peso significa más energía, más desgaste de cubiertas y más daño en un choque."}},{"slug":"movilidad-4.s4.p8.v3","orden":8,"grupo":"movilidad-4.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto chico pesa 1.100 kg y un SUV grande 1.800 kg. ¿En qué porcentaje es más pesado el SUV? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"1100 kg frente a 1800 kg."},"solucion":{"valor":64,"tolerancia":1,"explicacion":"(1.800 − 1.100) ÷ 1.100 × 100 ≈ 64 %. Más peso significa más energía, más desgaste de cubiertas y más daño en un choque."}},{"slug":"movilidad-4.s4.p9","orden":9,"grupo":"movilidad-4.s4.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un auto más pesado emite más partículas sin escape.","items":[{"id":"i1","texto":"El vehículo pesa más"},{"id":"i2","texto":"Las cubiertas soportan más fuerza contra el asfalto"},{"id":"i3","texto":"Se desgastan más rápido"},{"id":"i4","texto":"Se liberan más partículas al aire"},{"id":"i5","texto":"El peso extra reduce el roce con el asfalto"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El peso es un factor que atraviesa el consumo, las partículas y la seguridad."}},{"slug":"movilidad-4.s4.p10","orden":10,"grupo":"movilidad-4.s4.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El efecto rebote","cuerpo":["Cuando algo se vuelve más barato de usar, a veces se usa más. Si un auto eléctrico cuesta menos por kilómetro, algunas personas pueden manejar más o dejar el transporte público. Es el efecto rebote: parte del ahorro se pierde por el aumento del uso. No elimina el beneficio, pero conviene tenerlo en cuenta en las políticas."]},"solucion":{}},{"slug":"movilidad-4.s4.p11","orden":11,"grupo":"movilidad-4.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Alguien compra un auto eléctrico y, como le sale barato, deja de usar el tren y maneja el doble. ¿Qué es esto?","opciones":[{"id":"o1","texto":"Un efecto rebote"},{"id":"o2","texto":"Un caso de mala adaptación"},{"id":"o3","texto":"Un beneficio doble para el ambiente"},{"id":"o4","texto":"Una forma de mitigación perfecta"}]},"solucion":{"clave":["o1"],"explicacion":"El ahorro por kilómetro se come en parte por los kilómetros extra.","por_opcion":{"o3":"Manejar el doble y dejar el tren reduce el beneficio."}}},{"slug":"movilidad-4.s4.p12","orden":12,"grupo":"movilidad-4.s4.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En un embotellamiento, un auto eléctrico ocupa menos lugar que uno a nafta del mismo tamaño.","razones":[{"id":"r1","texto":"Porque el espacio depende del tamaño, no del motor"},{"id":"r2","texto":"Porque los eléctricos se achican al frenar"},{"id":"r3","texto":"Porque los eléctricos pueden ir por las veredas"}]},"solucion":{"valor":false,"explicacion":"Ocupa exactamente el mismo espacio. Cambiar el motor no cambia la congestión ni el lugar que usan los autos.","clave":["r1"]}},{"slug":"movilidad-4.s4.p13","orden":13,"grupo":"movilidad-4.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los autos eléctricos no tienen emisiones por el caño de escape."},{"id":"s2","texto":"Si todos los autos fueran eléctricos, se terminarían los embotellamientos."},{"id":"s3","texto":"Los vehículos pesados desgastan más las cubiertas."},{"id":"s4","texto":"Un SUV eléctrico siempre emite menos que cualquier auto a nafta."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Electrificar es parte de la solución, no toda la solución.","por_opcion":{"s2":"Ocupan el mismo espacio: la congestión sigue igual.","s4":"Puede emitir más que un auto chico y eficiente."}}},{"slug":"movilidad-4.s4.p14","orden":14,"grupo":"movilidad-4.s4.p14","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con una solución que no depende del motor.","izquierda":[{"id":"a1","texto":"Congestión"},{"id":"a2","texto":"Siniestros viales"},{"id":"a3","texto":"Sedentarismo"},{"id":"a4","texto":"Espacio ocupado"}],"derecha":[{"id":"b1","texto":"Transporte público frecuente"},{"id":"b2","texto":"Velocidades más bajas en la ciudad"},{"id":"b3","texto":"Caminar y pedalear en viajes cortos"},{"id":"b4","texto":"Menos autos por persona"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Las soluciones de fondo cambian cómo nos movemos, no solo con qué motor."}},{"slug":"movilidad-4.s4.p15","orden":15,"grupo":"movilidad-4.s4.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las partículas de frenos y cubiertas son emisiones que no salen del {{0}}; manejar más porque el auto sale más barato es un efecto {{1}}; y los vehículos más {{2}} gastan más energía.","banco":[{"id":"w1","texto":"escape"},{"id":"w2","texto":"rebote"},{"id":"w3","texto":"pesados"},{"id":"w4","texto":"motor"},{"id":"w5","texto":"espejo"},{"id":"w6","texto":"livianos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre lo que ningún motor resuelve por sí solo."}}]},{"slug":"movilidad-4.s5","orden":5,"tipo":"leccion","titulo_es":"Evitar, cambiar, mejorar","bajada_es":"Un marco para ordenar las soluciones: primero evitar viajes innecesarios, después cambiar de modo, y mejorar los vehículos.","minutos":12,"pasos":[{"slug":"movilidad-4.s5.p1","orden":1,"grupo":"movilidad-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres escalones","cuerpo":["Un marco muy usado en planificación del transporte ordena las soluciones en tres escalones. Evitar: reducir la necesidad de viajar lejos, con ciudades más compactas, servicios cerca y trabajo remoto cuando es posible. Cambiar: pasar viajes del auto a caminar, pedalear o al transporte público. Mejorar: hacer más eficientes y limpios los vehículos que sí se usan, como los eléctricos."]},"solucion":{}},{"slug":"movilidad-4.s5.p2","orden":2,"grupo":"movilidad-4.s5.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una medida de evitar, cambiar o mejorar?","grupos":[{"id":"g1","nombre":"Evitar"},{"id":"g2","nombre":"Cambiar"},{"id":"g3","nombre":"Mejorar"}],"items":[{"id":"i1","texto":"Un centro de salud en el barrio en lugar de viajar al centro"},{"id":"i2","texto":"Ir en bici en lugar de en auto"},{"id":"i3","texto":"Pasar a un auto eléctrico"},{"id":"i4","texto":"Trabajar desde casa algunos días"},{"id":"i5","texto":"Tomar el tren en lugar de manejar"},{"id":"i6","texto":"Mantener bien infladas las cubiertas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Los tres escalones se complementan, pero los primeros suelen tener más beneficios a la vez."}},{"slug":"movilidad-4.s5.p3","orden":3,"grupo":"movilidad-4.s5.p3","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los escalones del marco, del que se aplica primero al último.","items":[{"id":"i1","texto":"Evitar viajes innecesarios o largos"},{"id":"i2","texto":"Cambiar a modos más eficientes"},{"id":"i3","texto":"Mejorar los vehículos que se siguen usando"}]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Primero se pregunta si hace falta el viaje; después cómo hacerlo; y por último con qué vehículo."}},{"slug":"movilidad-4.s5.p4","orden":4,"grupo":"movilidad-4.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Manejar mejor","cuerpo":["Si se usa el auto, la forma de manejar cambia el consumo. La resistencia del aire crece con el cuadrado de la velocidad: ir a 120 km/h en lugar de 100 multiplica esa resistencia por 1,44. Acelerar y frenar de golpe desperdicia energía. Las cubiertas desinfladas aumentan el consumo. Y cargar peso de más o un portaequipajes vacío en el techo también suma."]},"solucion":{}},{"slug":"movilidad-4.s5.p5","orden":5,"grupo":"movilidad-4.s5.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La resistencia del aire crece con el cuadrado de la velocidad. ¿Cuántas veces mayor es a 120 km/h que a 100 km/h? Redondeá a dos decimales.","unidad":"veces","decimales":2,"contexto":"Velocidad de 100 a 120 km/h."},"solucion":{"valor":1.44,"tolerancia":0.01,"explicacion":"(120 ÷ 100)² ≈ 1,44. En ruta, bajar un poco la velocidad ahorra bastante combustible."}},{"slug":"movilidad-4.s5.p5.v2","orden":5,"grupo":"movilidad-4.s5.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La resistencia del aire crece con el cuadrado de la velocidad. ¿Cuántas veces mayor es a 110 km/h que a 90 km/h? Redondeá a dos decimales.","unidad":"veces","decimales":2,"contexto":"Velocidad de 90 a 110 km/h."},"solucion":{"valor":1.49,"tolerancia":0.01,"explicacion":"(110 ÷ 90)² ≈ 1,49. En ruta, bajar un poco la velocidad ahorra bastante combustible."}},{"slug":"movilidad-4.s5.p5.v3","orden":5,"grupo":"movilidad-4.s5.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La resistencia del aire crece con el cuadrado de la velocidad. ¿Cuántas veces mayor es a 120 km/h que a 80 km/h? Redondeá a dos decimales.","unidad":"veces","decimales":2,"contexto":"Velocidad de 80 a 120 km/h."},"solucion":{"valor":2.25,"tolerancia":0.01,"explicacion":"(120 ÷ 80)² ≈ 2,25. En ruta, bajar un poco la velocidad ahorra bastante combustible."}},{"slug":"movilidad-4.s5.p6","orden":6,"grupo":"movilidad-4.s5.p6","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hábitos de manejo reducen el consumo? Marcá todos.","opciones":[{"id":"o1","texto":"Acelerar y frenar suavemente"},{"id":"o2","texto":"Mantener las cubiertas bien infladas"},{"id":"o3","texto":"No ir más rápido de lo necesario en ruta"},{"id":"o4","texto":"Llevar un portaequipajes vacío en el techo"},{"id":"o5","texto":"Dejar el motor encendido mientras se espera"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Pequeños hábitos que, sumados en un año, ahorran combustible y dinero."}},{"slug":"movilidad-4.s5.p7","orden":7,"grupo":"movilidad-4.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Compartir","cuerpo":["Compartir un auto también es una forma de mejorar. Viajar de a cuatro en lugar de de a uno divide por cuatro las emisiones por persona. El auto compartido (car sharing), donde varias personas usan un mismo auto cuando lo necesitan, reduce la cantidad de autos y el espacio de estacionamiento. En promedio, un auto particular pasa más del 90 % del tiempo estacionado."]},"solucion":{}},{"slug":"movilidad-4.s5.p8","orden":8,"grupo":"movilidad-4.s5.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto emite 184 g de CO₂ por km. Si viajan 4 personas en lugar de una, ¿cuántos gramos por persona y por km son?","unidad":"g/km por persona","decimales":0},"solucion":{"valor":46,"tolerancia":0.92,"explicacion":"184 ÷ 4 = 46 g por persona y km. La ocupación es una de las palancas más baratas."}},{"slug":"movilidad-4.s5.p8.v2","orden":8,"grupo":"movilidad-4.s5.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto emite 160 g de CO₂ por km. Si viajan 3 personas en lugar de una, ¿cuántos gramos por persona y por km son?","unidad":"g/km por persona","decimales":3},"solucion":{"valor":53.333333333333336,"tolerancia":1.0666666666666667,"explicacion":"160 ÷ 3 = 53,333 g por persona y km. La ocupación es una de las palancas más baratas."}},{"slug":"movilidad-4.s5.p8.v3","orden":8,"grupo":"movilidad-4.s5.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto emite 200 g de CO₂ por km. Si viajan 2 personas en lugar de una, ¿cuántos gramos por persona y por km son?","unidad":"g/km por persona","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"200 ÷ 2 = 100 g por persona y km. La ocupación es una de las palancas más baratas."}},{"slug":"movilidad-4.s5.p9","orden":9,"grupo":"movilidad-4.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Políticas","cuerpo":["Las ciudades y los países usan distintas políticas: cobrar por entrar al centro en horas pico, como Londres desde 2003 y Estocolmo desde 2006, que redujeron el tránsito; zonas de bajas emisiones donde no pueden entrar los vehículos más contaminantes; cobrar el estacionamiento en la calle; normas de eficiencia para los autos nuevos; e inversión en transporte público, veredas y ciclovías."]},"solucion":{}},{"slug":"movilidad-4.s5.p10","orden":10,"grupo":"movilidad-4.s5.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada política con su efecto.","izquierda":[{"id":"a1","texto":"Cobro por congestión"},{"id":"a2","texto":"Zona de bajas emisiones"},{"id":"a3","texto":"Estacionamiento tarifado"},{"id":"a4","texto":"Normas de eficiencia"}],"derecha":[{"id":"b1","texto":"Menos autos en el centro en horas pico"},{"id":"b2","texto":"Menos vehículos contaminantes en un área"},{"id":"b3","texto":"El espacio de la calle deja de ser gratis"},{"id":"b4","texto":"Autos nuevos que consumen menos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada política actúa sobre una palanca distinta; combinadas, suman."}},{"slug":"movilidad-4.s5.p11","orden":11,"grupo":"movilidad-4.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Londres cobra por entrar al centro en horas pico. ¿Qué busca esa medida?","opciones":[{"id":"o1","texto":"Que entren menos autos y el tránsito fluya mejor"},{"id":"o2","texto":"Recaudar sin cambiar la cantidad de autos"},{"id":"o3","texto":"Prohibir totalmente los autos en la ciudad"},{"id":"o4","texto":"Que los colectivos paguen más que los autos"}]},"solucion":{"clave":["o1"],"explicacion":"Poner precio al espacio escaso en el momento de más demanda reduce la congestión y financia alternativas.","por_opcion":{"o3":"No prohíbe: pone un precio al uso del espacio más escaso."}}},{"slug":"movilidad-4.s5.p12","orden":12,"grupo":"movilidad-4.s5.p12","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas decisiones de una familia de mayor a menor impacto en sus emisiones de transporte, si hoy hace 15.000 km por año en un SUV a nafta.","items":[{"id":"i1","texto":"Vender el SUV y usar transporte público, bici y un auto compartido"},{"id":"i2","texto":"Reemplazarlo por un auto eléctrico chico"},{"id":"i3","texto":"Reemplazarlo por un auto a nafta chico y eficiente"},{"id":"i4","texto":"Mantener el SUV y manejar más suave"}],"extremos":["Mayor impacto","Menor impacto"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los escalones de evitar y cambiar suelen pesar más que mejorar el vehículo.","valores":{"i1":"evita la mayor parte","i2":"reduce mucho","i3":"reduce algo","i4":"reduce poco"}}},{"slug":"movilidad-4.s5.p13","orden":13,"grupo":"movilidad-4.s5.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La solución a los problemas del transporte es solo cambiar todos los autos por eléctricos.","razones":[{"id":"r1","texto":"Porque también hace falta evitar y cambiar viajes"},{"id":"r2","texto":"Porque los autos eléctricos no sirven para nada"},{"id":"r3","texto":"Porque el transporte no tiene ningún problema"}]},"solucion":{"valor":false,"explicacion":"Electrificar es necesario, pero no resuelve congestión, espacio, seguridad ni sedentarismo. Evitar y cambiar viajes también son parte de la solución.","clave":["r1"]}},{"slug":"movilidad-4.s5.p14","orden":14,"grupo":"movilidad-4.s5.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé el plan de movilidad de una empresa y marcá lo que no cierra.","segmentos":[{"id":"s1","texto":"Ofreceremos trabajo remoto dos días por semana."},{"id":"s2","texto":"Regalaremos estacionamiento gratis a todos para que vengan en auto."},{"id":"s3","texto":"Instalaremos estacionamiento seguro para bicis."},{"id":"s4","texto":"Con cambiar la flota a eléctricos, ya no hace falta nada más."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan usa los tres escalones y no premia lo que quiere reducir.","por_opcion":{"s2":"Incentiva el auto; conviene premiar otros modos.","s4":"Evitar y cambiar viajes suman beneficios que electrificar no da."}}},{"slug":"movilidad-4.s5.p15","orden":15,"grupo":"movilidad-4.s5.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Reducir la necesidad de viajar es {{0}}; pasar del auto al tren es {{1}}; y hacer más limpios los vehículos es {{2}}.","banco":[{"id":"w1","texto":"evitar"},{"id":"w2","texto":"cambiar"},{"id":"w3","texto":"mejorar"},{"id":"w4","texto":"ignorar"},{"id":"w5","texto":"repetir"},{"id":"w6","texto":"agrandar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los tres escalones para ordenar las soluciones de movilidad."}}]},{"slug":"movilidad-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: autos, eléctricos y combustibles","bajada_es":"Emisiones, combustibles, autos eléctricos, límites del motor y el marco evitar–cambiar–mejorar, mezclados.","minutos":8,"pasos":[{"slug":"movilidad-4.s6.p1","orden":1,"grupo":"movilidad-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Autos, eléctricos y combustibles». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"movilidad-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el auto de la familia Paz","bajada_es":"La familia Paz recorre 10.000 km por año y tiene que cambiar el auto. Compará las opciones con números y ayudala a decidir.","minutos":10,"pasos":[{"slug":"movilidad-4.s7.p1","orden":1,"grupo":"movilidad-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las opciones","cuerpo":["Supuestos: nafta, 2,3 kg de CO₂ por litro; electricidad, 0,35 kg de CO₂ por kWh (valor aproximado para una red con mucho gas)."],"datos":{"tipo":"tabla","titulo":"Opciones de la familia Paz (10.000 km por año)","columnas":["Opción","Consumo","CO₂ por año (uso)"],"filas":[["SUV a nafta","10 L/100 km","2.300 kg"],["Auto chico a nafta","6 L/100 km","¿?"],["Auto eléctrico chico","15 kWh/100 km","¿?"],["Sin auto: transporte público, bici y auto compartido","—","unos 400 kg"]],"nota":"Valores aproximados para el ejercicio; no incluyen la fabricación."}},"solucion":{}},{"slug":"movilidad-4.s7.p2","orden":2,"grupo":"movilidad-4.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de CO₂ por año emitiría el auto chico a nafta?","unidad":"kg","decimales":0,"contexto":"10.000 km; 6 L/100 km; 2,3 kg/L."},"solucion":{"valor":1380,"tolerancia":27.6,"explicacion":"10.000 × 6 ÷ 100 = 600 litros; 600 × 2,3 = 1.380 kg por año."}},{"slug":"movilidad-4.s7.p3","orden":3,"grupo":"movilidad-4.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de CO₂ por año le corresponderían al auto eléctrico chico?","unidad":"kg","decimales":0,"contexto":"10.000 km; 15 kWh/100 km; 0,35 kg/kWh."},"solucion":{"valor":525,"tolerancia":10.5,"explicacion":"10.000 × 15 ÷ 100 = 1.500 kWh; 1.500 × 0,35 = 525 kg por año. Y bajaría si la red suma renovables."}},{"slug":"movilidad-4.s7.p4","orden":4,"grupo":"movilidad-4.s7.p4","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las opciones de menor a mayor CO₂ por año de uso.","items":[{"id":"i1","texto":"Sin auto: transporte, bici y auto compartido"},{"id":"i2","texto":"Auto eléctrico chico"},{"id":"i3","texto":"Auto chico a nafta"},{"id":"i4","texto":"SUV a nafta"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Evitar y cambiar gana; entre los autos, el eléctrico chico gana; el SUV a nafta queda último por lejos.","valores":{"i1":"≈ 400 kg","i2":"525 kg","i3":"1.380 kg","i4":"2.300 kg"}}},{"slug":"movilidad-4.s7.p5","orden":5,"grupo":"movilidad-4.s7.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué dato falta para comparar de forma completa el auto eléctrico con el chico a nafta?","opciones":[{"id":"o1","texto":"Las emisiones de fabricar la batería"},{"id":"o2","texto":"El color del auto y el de su tapizado"},{"id":"o3","texto":"El precio del estacionamiento del barrio"},{"id":"o4","texto":"La marca de las cubiertas originales"}]},"solucion":{"clave":["o1"],"explicacion":"Sin la fabricación, la comparación queda incompleta. Aun así, los estudios de ciclo de vida suelen favorecer al eléctrico.","por_opcion":{"o3":"Importa para el bolsillo, no para las emisiones de ciclo de vida."}}},{"slug":"movilidad-4.s7.p6","orden":6,"grupo":"movilidad-4.s7.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"La familia elige el auto eléctrico chico. ¿Qué más puede hacer para bajar su impacto? Marcá todo.","opciones":[{"id":"o1","texto":"Seguir usando el tren para ir al centro"},{"id":"o2","texto":"Ir en bici a los lugares cercanos"},{"id":"o3","texto":"Compartir viajes con vecinos"},{"id":"o4","texto":"Manejar el doble porque cargar es barato"},{"id":"o5","texto":"Comprar además un segundo auto grande"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Mejorar el vehículo rinde más si además se evitan y se cambian viajes. Cuidado con el efecto rebote."}},{"slug":"movilidad-4.s7.p7","orden":7,"grupo":"movilidad-4.s7.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Pasar del SUV a nafta al auto eléctrico chico reduce las emisiones de uso en más de un 75 %.","razones":[{"id":"r1","texto":"Porque baja de 2.300 a 525 kg por año"},{"id":"r2","texto":"Porque el eléctrico emite más que el SUV"},{"id":"r3","texto":"Porque el eléctrico no consume energía"}]},"solucion":{"valor":true,"explicacion":"De 2.300 a 525 kg: una baja de 1.775 kg, que es un 77 % menos, con los supuestos del ejercicio.","clave":["r1"]}},{"slug":"movilidad-4.s7.p8","orden":8,"grupo":"movilidad-4.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La familia escribe su decisión. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Elegimos un auto chico: menos peso, menos energía."},{"id":"s2","texto":"Como es eléctrico, ya no importa cuánto lo usemos."},{"id":"s3","texto":"Vamos a seguir usando el tren para ir al centro."},{"id":"s4","texto":"El eléctrico no tiene ninguna emisión en toda su vida."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una buena decisión combina el vehículo adecuado con un uso responsable.","por_opcion":{"s2":"Usarlo más suma emisiones y congestión: es el efecto rebote.","s4":"Su fabricación y la electricidad tienen emisiones, aunque menores."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"movilidad-5","rama":"movilidad","orden":5,"nivel":3,"titulo_es":"Ciudades para las personas","bajada_es":"Por qué más carriles traen más autos, cuánto cuesta estacionar \"gratis\", qué lograron Estocolmo y Nueva York cobrando por entrar y cómo se rediseña una calle para vivirla.","objetivos_es":["Explicar la accesibilidad y el papel de la densidad y la mezcla de usos","Analizar la demanda inducida y la evaporación del tránsito","Evaluar políticas de precio: estacionamiento y cobro por congestión","Proponer rediseños de calles con evidencia de salud y seguridad","Reconocer desigualdades de movilidad por ingreso, género, edad y discapacidad"],"repasa":["movilidad-1","movilidad-2","movilidad-3","movilidad-4"],"requiere_tronco":3,"fuentes":["itdp-tod","human-transit","duranton-turner-2011","cheonggyecheon","shoup-estacionamiento","borjesson-2012-estocolmo","mta-congestion-2026","mueller-2020-supermanzanas","declaracion-estocolmo-2020","oms-seguridad-vial","caf-movilidad-genero"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"movilidad-5.s1","orden":1,"tipo":"leccion","titulo_es":"Llegar, no solo moverse","bajada_es":"Accesibilidad, densidad y mezcla de usos: la forma de la ciudad decide cuánto y cómo viajamos.","minutos":9,"pasos":[{"slug":"movilidad-5.s1.p1","orden":1,"grupo":"movilidad-5.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Moverse para llegar","cuerpo":["Casi nadie viaja por el gusto de viajar: nos movemos para llegar al trabajo, la escuela, el hospital o la casa de alguien. Por eso los especialistas hablan de accesibilidad: cuántas oportunidades se pueden alcanzar en un tiempo razonable. Se puede mejorar de dos maneras: haciendo más rápido el transporte, o acercando las cosas, con barrios que mezclen viviendas, comercios, escuelas y trabajo."]},"solucion":{}},{"slug":"movilidad-5.s1.p2","orden":2,"grupo":"movilidad-5.s1.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué mide la accesibilidad de un barrio?","opciones":[{"id":"o1","texto":"Cuántos destinos útiles se alcanzan en un tiempo razonable"},{"id":"o2","texto":"La velocidad máxima de los autos en sus avenidas"},{"id":"o3","texto":"La cantidad de autos por familia del barrio"},{"id":"o4","texto":"La cantidad de semáforos por cada kilómetro"}]},"solucion":{"clave":["o1"],"explicacion":"La pregunta clave no es qué tan rápido vamos, sino a cuántos lugares podemos llegar.","por_opcion":{"o3":"Tener más autos no significa llegar a más lugares."}}},{"slug":"movilidad-5.s1.p3","orden":3,"grupo":"movilidad-5.s1.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un municipio quiere que los vecinos de un barrio lejano lleguen más fácil a la atención médica. ¿Qué opción mejora la accesibilidad sin construir rutas?","opciones":[{"id":"o1","texto":"Abrir un centro de salud dentro del barrio"},{"id":"o2","texto":"Subir la velocidad máxima de la avenida de acceso"},{"id":"o3","texto":"Agregar estacionamiento en el hospital central"},{"id":"o4","texto":"Pintar de nuevo la señalización de la ruta"}]},"solucion":{"clave":["o1"],"explicacion":"Acercar los destinos es tan poderoso como acelerar los viajes, y suele ser más barato.","por_opcion":{"o3":"Ayuda solo a quien tiene auto, y no acerca la atención."}}},{"slug":"movilidad-5.s1.p4","orden":4,"grupo":"movilidad-5.s1.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Desde un barrio se podía llegar a 50.000 puestos de trabajo en 45 minutos de transporte público. Con una línea nueva se llega a 80.000. ¿En qué porcentaje aumentó su accesibilidad al empleo?","unidad":"%","decimales":0,"contexto":"50000 empleos antes; 80000 después."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"(80.000 − 50.000) ÷ 50.000 × 100 = 60 %. Medir así muestra el beneficio real de una obra: más oportunidades al alcance."}},{"slug":"movilidad-5.s1.p4.v2","orden":4,"grupo":"movilidad-5.s1.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Desde un barrio se podía llegar a 120.000 puestos de trabajo en 45 minutos de transporte público. Con una línea nueva se llega a 150.000. ¿En qué porcentaje aumentó su accesibilidad al empleo?","unidad":"%","decimales":0,"contexto":"120000 empleos antes; 150000 después."},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"(150.000 − 120.000) ÷ 120.000 × 100 = 25 %. Medir así muestra el beneficio real de una obra: más oportunidades al alcance."}},{"slug":"movilidad-5.s1.p4.v3","orden":4,"grupo":"movilidad-5.s1.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Desde un barrio se podía llegar a 20.000 puestos de trabajo en 45 minutos de transporte público. Con una línea nueva se llega a 50.000. ¿En qué porcentaje aumentó su accesibilidad al empleo?","unidad":"%","decimales":0,"contexto":"20000 empleos antes; 50000 después."},"solucion":{"valor":150,"tolerancia":3,"explicacion":"(50.000 − 20.000) ÷ 20.000 × 100 = 150 %. Medir así muestra el beneficio real de una obra: más oportunidades al alcance."}},{"slug":"movilidad-5.s1.p5","orden":5,"grupo":"movilidad-5.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Densidad y mezcla","cuerpo":["Una ciudad extendida, de baja densidad y con usos separados (barrios solo de casas, centros comerciales lejos, trabajo en otra punta) alarga los viajes y hace depender del auto: con poca gente por kilómetro, el transporte público no puede pasar seguido. Una ciudad compacta, con usos mezclados y más gente viviendo cerca de las estaciones, permite resolver muchos viajes caminando, en bici o en transporte público.","El Instituto de Políticas para el Transporte y el Desarrollo (ITDP) resume esta idea en ocho principios para el desarrollo orientado al transporte: caminar, pedalear, conectar, usar transporte público, mezclar usos, densificar, compactar y cambiar la prioridad del auto."]},"solucion":{}},{"slug":"movilidad-5.s1.p6","orden":6,"grupo":"movilidad-5.s1.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una ciudad extendida termina dependiendo del auto.","items":[{"id":"i1","texto":"Se construyen barrios lejanos solo con viviendas"},{"id":"i2","texto":"Trabajo, escuelas y comercios quedan lejos"},{"id":"i3","texto":"Hay poca gente por kilómetro para sostener colectivos frecuentes"},{"id":"i4","texto":"Hace falta un auto para casi todo"},{"id":"i5","texto":"Crecen el tránsito, las emisiones y el gasto de las familias"},{"id":"i6","texto":"La baja densidad permite colectivos más frecuentes"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La forma de la ciudad decide los viajes antes de que alguien elija cómo moverse."}},{"slug":"movilidad-5.s1.p7","orden":7,"grupo":"movilidad-5.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 5.000 habitantes por km². ¿Cuántas personas viven a menos de 500 m de su estación? (El área de un círculo de 500 m de radio es de unos 0,785 km².) Redondeá a la centena.","unidad":"personas","decimales":0,"contexto":"5000 habitantes por km²; círculo de 500 m."},"solucion":{"valor":3900,"tolerancia":100,"explicacion":"5.000 × 0,785 ≈ 3.900 personas. Con más gente a distancia caminable, la estación tiene más usuarios y se justifica más frecuencia."}},{"slug":"movilidad-5.s1.p7.v2","orden":7,"grupo":"movilidad-5.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 15.000 habitantes por km². ¿Cuántas personas viven a menos de 500 m de su estación? (El área de un círculo de 500 m de radio es de unos 0,785 km².) Redondeá a la centena.","unidad":"personas","decimales":0,"contexto":"15000 habitantes por km²; círculo de 500 m."},"solucion":{"valor":11800,"tolerancia":100,"explicacion":"15.000 × 0,785 ≈ 11.800 personas. Con más gente a distancia caminable, la estación tiene más usuarios y se justifica más frecuencia."}},{"slug":"movilidad-5.s1.p7.v3","orden":7,"grupo":"movilidad-5.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 30.000 habitantes por km². ¿Cuántas personas viven a menos de 500 m de su estación? (El área de un círculo de 500 m de radio es de unos 0,785 km².) Redondeá a la centena.","unidad":"personas","decimales":0,"contexto":"30000 habitantes por km²; círculo de 500 m."},"solucion":{"valor":23600,"tolerancia":100,"explicacion":"30.000 × 0,785 ≈ 23.600 personas. Con más gente a distancia caminable, la estación tiene más usuarios y se justifica más frecuencia."}},{"slug":"movilidad-5.s1.p8","orden":8,"grupo":"movilidad-5.s1.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada principio del desarrollo orientado al transporte con un ejemplo.","izquierda":[{"id":"a1","texto":"Caminar"},{"id":"a2","texto":"Pedalear"},{"id":"a3","texto":"Transporte público"},{"id":"a4","texto":"Mezclar"},{"id":"a5","texto":"Densificar"}],"derecha":[{"id":"b1","texto":"Veredas anchas, sombra y cruces seguros"},{"id":"b2","texto":"Red de ciclovías conectada"},{"id":"b3","texto":"Estación a pocas cuadras de casa"},{"id":"b4","texto":"Viviendas, comercios y escuelas en la misma zona"},{"id":"b5","texto":"Más gente viviendo cerca de las estaciones"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Los principios se refuerzan entre sí: ninguno alcanza solo."}},{"slug":"movilidad-5.s1.p9","orden":9,"grupo":"movilidad-5.s1.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una ciudad más densa siempre es peor para vivir.","razones":[{"id":"r1","texto":"Porque con buen diseño y servicios la densidad acerca todo"},{"id":"r2","texto":"Porque la densidad elimina siempre las plazas"},{"id":"r3","texto":"Porque en las ciudades densas no hay transporte"}]},"solucion":{"valor":false,"explicacion":"Depende del diseño: con plazas, árboles, servicios y buen transporte, la densidad permite vivir cerca de todo. Lo que empeora la vida es la densidad sin espacio público ni servicios.","clave":["r1"]}},{"slug":"movilidad-5.s1.p10","orden":10,"grupo":"movilidad-5.s1.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué rasgos tiene un barrio orientado al transporte público? Marcá todos.","opciones":[{"id":"o1","texto":"Estaciones a distancia caminable"},{"id":"o2","texto":"Comercios y servicios en planta baja"},{"id":"o3","texto":"Veredas y cruces seguros hacia la estación"},{"id":"o4","texto":"Viviendas de distintos precios cerca del transporte"},{"id":"o5","texto":"Grandes playas de estacionamiento junto a cada estación"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las playas de estacionamiento ocupan justo el suelo más valioso para vivir cerca del transporte."}},{"slug":"movilidad-5.s1.p11","orden":11,"grupo":"movilidad-5.s1.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan urbano y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Permitiremos más viviendas cerca de las estaciones de tren."},{"id":"s2","texto":"El nuevo barrio tendrá solo casas; los comercios estarán en un centro comercial a 8 km."},{"id":"s3","texto":"Mediremos cuántos empleos se alcanzan en 45 minutos desde cada barrio."},{"id":"s4","texto":"El éxito se medirá solo por la velocidad promedio de los autos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Planificar para la accesibilidad cambia qué se construye y qué se mide.","por_opcion":{"s2":"Separar los usos alarga los viajes y obliga a usar el auto.","s4":"Importa la accesibilidad de todas las personas, no solo la velocidad de los autos."}}},{"slug":"movilidad-5.s1.p12","orden":12,"grupo":"movilidad-5.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La cantidad de destinos que se alcanzan en un tiempo razonable es la {{0}}; barrios con viviendas, comercios y escuelas juntos tienen usos {{1}}; y más gente viviendo cerca de las estaciones es {{2}}.","banco":[{"id":"w1","texto":"accesibilidad"},{"id":"w2","texto":"mezclados"},{"id":"w3","texto":"densificar"},{"id":"w4","texto":"velocidad"},{"id":"w5","texto":"separados"},{"id":"w6","texto":"dispersar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para pensar la ciudad antes que el vehículo."}}]},{"slug":"movilidad-5.s2","orden":2,"tipo":"leccion","titulo_es":"Más carriles, más autos","bajada_es":"La demanda inducida, por qué ensanchar no cura la congestión y qué pasa cuando se quita una autopista.","minutos":11,"pasos":[{"slug":"movilidad-5.s2.p1","orden":1,"grupo":"movilidad-5.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La ley fundamental de la congestión","cuerpo":["Un estudio publicado en 2011 con datos de ciudades de Estados Unidos encontró que los kilómetros recorridos en auto aumentan en proporción a los kilómetros de carriles de autopista: si se amplían un 10 %, se maneja cerca de un 10 % más. El tránsito nuevo viene de residentes que manejan más, de más transporte de carga y de gente que se muda. Los autores concluyeron que agregar rutas difícilmente alivie la congestión."]},"solucion":{}},{"slug":"movilidad-5.s2.p2","orden":2,"grupo":"movilidad-5.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Por una red de autopistas se recorren 100.000 km en auto por día. Si se amplían los carriles un 20 % y el tránsito crece en la misma proporción, ¿cuántos km por día se recorrerán?","unidad":"km por día","decimales":0,"contexto":"100000 km por día; ampliación del 20 %."},"solucion":{"valor":120000,"tolerancia":2400,"explicacion":"100.000 × 1,2 = 120.000 km. Con más espacio llega más tránsito, y la congestión vuelve."}},{"slug":"movilidad-5.s2.p2.v2","orden":2,"grupo":"movilidad-5.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Por una red de autopistas se recorren 80.000 km en auto por día. Si se amplían los carriles un 25 % y el tránsito crece en la misma proporción, ¿cuántos km por día se recorrerán?","unidad":"km por día","decimales":0,"contexto":"80000 km por día; ampliación del 25 %."},"solucion":{"valor":100000,"tolerancia":2000,"explicacion":"80.000 × 1,25 = 100.000 km. Con más espacio llega más tránsito, y la congestión vuelve."}},{"slug":"movilidad-5.s2.p2.v3","orden":2,"grupo":"movilidad-5.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Por una red de autopistas se recorren 50.000 km en auto por día. Si se amplían los carriles un 10 % y el tránsito crece en la misma proporción, ¿cuántos km por día se recorrerán?","unidad":"km por día","decimales":0,"contexto":"50000 km por día; ampliación del 10 %."},"solucion":{"valor":55000,"tolerancia":1100,"explicacion":"50.000 × 1,1 = 55.000 km. Con más espacio llega más tránsito, y la congestión vuelve."}},{"slug":"movilidad-5.s2.p3","orden":3,"grupo":"movilidad-5.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué pasa","cuerpo":["La congestión funciona como un precio que se paga en tiempo. Cuando una obra nueva baja ese precio, aparecen viajes que antes se evitaban: gente que cambia de ruta, de horario, de modo o de destino, y a la larga, de lugar donde vivir. A eso se lo llama demanda inducida. Al poco tiempo, la nueva vía se llena y el ahorro de tiempo se esfuma."]},"solucion":{}},{"slug":"movilidad-5.s2.p4","orden":4,"grupo":"movilidad-5.s2.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la demanda inducida.","items":[{"id":"i1","texto":"Se ensancha una avenida congestionada"},{"id":"i2","texto":"Al principio se viaja más rápido"},{"id":"i3","texto":"Manejar se vuelve más atractivo"},{"id":"i4","texto":"Más personas eligen el auto, en más horarios"},{"id":"i5","texto":"La avenida vuelve a congestionarse"},{"id":"i6","texto":"Menos gente elige manejar porque hay más carriles"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Ensanchar alivia unos meses; el tránsito nuevo llena el espacio."}},{"slug":"movilidad-5.s2.p5","orden":5,"grupo":"movilidad-5.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un viaje tardaba 40 minutos. Tras ensanchar la avenida pasó a 30, pero dos años después, con más tránsito, tarda 38. ¿Qué porcentaje del ahorro inicial se perdió?","unidad":"%","decimales":0,"contexto":"40 min antes; 30 tras la obra; 38 dos años después."},"solucion":{"valor":80,"tolerancia":1,"explicacion":"Ahorro inicial: 10 min; se perdieron 8 min. 8 ÷ 10 × 100 ≈ 80 %. Valores de ejemplo de un patrón que se repite en muchas ciudades."}},{"slug":"movilidad-5.s2.p5.v2","orden":5,"grupo":"movilidad-5.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un viaje tardaba 50 minutos. Tras ensanchar la avenida pasó a 35, pero dos años después, con más tránsito, tarda 47. ¿Qué porcentaje del ahorro inicial se perdió?","unidad":"%","decimales":0,"contexto":"50 min antes; 35 tras la obra; 47 dos años después."},"solucion":{"valor":80,"tolerancia":1,"explicacion":"Ahorro inicial: 15 min; se perdieron 12 min. 12 ÷ 15 × 100 ≈ 80 %. Valores de ejemplo de un patrón que se repite en muchas ciudades."}},{"slug":"movilidad-5.s2.p5.v3","orden":5,"grupo":"movilidad-5.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un viaje tardaba 30 minutos. Tras ensanchar la avenida pasó a 24, pero dos años después, con más tránsito, tarda 28. ¿Qué porcentaje del ahorro inicial se perdió?","unidad":"%","decimales":0,"contexto":"30 min antes; 24 tras la obra; 28 dos años después."},"solucion":{"valor":67,"tolerancia":1,"explicacion":"Ahorro inicial: 6 min; se perdieron 4 min. 4 ÷ 6 × 100 ≈ 67 %. Valores de ejemplo de un patrón que se repite en muchas ciudades."}},{"slug":"movilidad-5.s2.p6","orden":6,"grupo":"movilidad-5.s2.p6","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Ensanchar una avenida congestionada resuelve el tránsito para siempre.","razones":[{"id":"r1","texto":"Porque la demanda inducida vuelve a llenar la vía"},{"id":"r2","texto":"Porque las avenidas anchas no se pueden congestionar"},{"id":"r3","texto":"Porque el tránsito nunca cambia"}]},"solucion":{"valor":false,"explicacion":"El alivio suele durar poco: la demanda inducida vuelve a llenar la avenida. Por eso se combinan otras medidas, como transporte público y gestión de la demanda.","clave":["r1"]}},{"slug":"movilidad-5.s2.p7","orden":7,"grupo":"movilidad-5.s2.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada reacción de los conductores ante una vía nueva con un ejemplo.","izquierda":[{"id":"a1","texto":"Cambio de ruta"},{"id":"a2","texto":"Cambio de horario"},{"id":"a3","texto":"Cambio de modo"},{"id":"a4","texto":"Cambio de lugar donde vivir"}],"derecha":[{"id":"b1","texto":"Dejar la avenida de siempre por la nueva autopista"},{"id":"b2","texto":"Salir en hora pico porque ahora parece más rápido"},{"id":"b3","texto":"Dejar el tren y volver al auto"},{"id":"b4","texto":"Mudarse más lejos porque \"total, se llega rápido\""}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Todas estas reacciones suman tránsito nuevo sobre la vía ampliada."}},{"slug":"movilidad-5.s2.p8","orden":8,"grupo":"movilidad-5.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quitar una autopista","cuerpo":["El efecto también funciona al revés. En Seúl, entre 2003 y 2005, se demolió una autopista elevada de unos 5,8 km que tapaba el arroyo Cheonggyecheon, y en su lugar se recuperó el curso de agua con un parque lineal. Hubo más congestión en algunas calles paralelas, pero el efecto sobre el tránsito del conjunto de la ciudad fue mínimo: parte de los viajes se reorganizó y parte se \"evaporó\"."]},"solucion":{}},{"slug":"movilidad-5.s2.p9","orden":9,"grupo":"movilidad-5.s2.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué pasó con el tránsito de Seúl al quitar la autopista del Cheonggyecheon?","opciones":[{"id":"o1","texto":"Cambió poco en conjunto: los viajes se reorganizaron"},{"id":"o2","texto":"La ciudad quedó paralizada durante años"},{"id":"o3","texto":"Tuvieron que reconstruir la autopista al año"},{"id":"o4","texto":"Todo el tránsito pasó a una sola calle paralela"}]},"solucion":{"clave":["o1"],"explicacion":"Si agregar vías induce tránsito, quitarlas puede hacer que parte desaparezca.","por_opcion":{"o3":"No se reconstruyó: hoy es un parque lineal."}}},{"slug":"movilidad-5.s2.p10","orden":10,"grupo":"movilidad-5.s2.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es tránsito inducido al ampliar una vía, o tránsito que se evapora al reducirla?","grupos":[{"id":"g1","nombre":"Tránsito inducido"},{"id":"g2","nombre":"Tránsito que se evapora"}],"items":[{"id":"i1","texto":"Gente que antes iba en tren y ahora maneja"},{"id":"i2","texto":"Viajes que se combinan en uno solo"},{"id":"i3","texto":"Viajes en auto que antes no se hacían"},{"id":"i4","texto":"Gente que pasa al transporte público"},{"id":"i5","texto":"Barrios lejanos que crecen gracias a la autopista"},{"id":"i6","texto":"Compras que se hacen cerca de casa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La demanda de viajes en auto no es fija: responde al espacio y al tiempo disponibles."}},{"slug":"movilidad-5.s2.p11","orden":11,"grupo":"movilidad-5.s2.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué alternativas a ensanchar pueden mejorar la movilidad de un corredor? Marcá todas.","opciones":[{"id":"o1","texto":"Un carril exclusivo para colectivos"},{"id":"o2","texto":"Más frecuencia de trenes"},{"id":"o3","texto":"Ciclovías protegidas"},{"id":"o4","texto":"Cobrar por estacionar en la zona"},{"id":"o5","texto":"Sumar dos carriles más para autos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Mover más personas en el mismo espacio es la forma de ganarle a la congestión."}},{"slug":"movilidad-5.s2.p12","orden":12,"grupo":"movilidad-5.s2.p12","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para evaluar en serio un proyecto vial.","items":[{"id":"i1","texto":"Medir los viajes actuales en todos los modos"},{"id":"i2","texto":"Estimar el tránsito inducido que generaría la obra"},{"id":"i3","texto":"Comparar con alternativas de transporte público y gestión de la demanda"},{"id":"i4","texto":"Evaluar costos, emisiones y seguridad de cada opción"},{"id":"i5","texto":"Decidir y monitorear los resultados"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una evaluación que ignora la demanda inducida sobrestima los beneficios de ensanchar."}},{"slug":"movilidad-5.s2.p13","orden":13,"grupo":"movilidad-5.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este anuncio de una obra y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"La avenida tiene congestión todos los días en hora pico."},{"id":"s2","texto":"Con dos carriles más, la congestión desaparecerá para siempre."},{"id":"s3","texto":"También agregaremos un carril exclusivo para colectivos."},{"id":"s4","texto":"No hace falta medir el tránsito después de la obra."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Frente a la congestión, la pregunta es cómo mover más personas, no más autos.","por_opcion":{"s2":"La demanda inducida suele volver a llenar la avenida.","s4":"Sin medir, no se sabe si funcionó ni si llegó tránsito nuevo."}}},{"slug":"movilidad-5.s2.p14","orden":14,"grupo":"movilidad-5.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El tránsito nuevo que aparece al ampliar una vía es la demanda {{0}}; al quitar capacidad, parte de los viajes se {{1}}; y en Seúl se demolió una autopista para recuperar un {{2}}.","banco":[{"id":"w1","texto":"inducida"},{"id":"w2","texto":"evapora"},{"id":"w3","texto":"arroyo"},{"id":"w4","texto":"reducida"},{"id":"w5","texto":"duplica"},{"id":"w6","texto":"estadio"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas que cambian cómo se discute una obra vial."}}]},{"slug":"movilidad-5.s3","orden":3,"tipo":"leccion","titulo_es":"El precio de usar la calle","bajada_es":"Estacionar \"gratis\", cocheras obligatorias, cobro por congestión en Estocolmo y Nueva York, y zonas de bajas emisiones.","minutos":11,"pasos":[{"slug":"movilidad-5.s3.p1","orden":1,"grupo":"movilidad-5.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Estacionar gratis no es gratis","cuerpo":["Cada lugar para estacionar ocupa suelo y cuesta construirlo. Cuando es gratis, ese costo se paga igual, escondido en el precio de las viviendas, de los comercios o de los impuestos, y lo pagan también quienes no tienen auto. El urbanista Donald Shoup mostró además que exigir un mínimo de cocheras en cada edificio encarece la vivienda y fomenta el uso del auto. Y que cobrar el estacionamiento en la calle a un precio que deje siempre algún lugar libre por cuadra reduce las vueltas buscando dónde estacionar."]},"solucion":{}},{"slug":"movilidad-5.s3.p2","orden":2,"grupo":"movilidad-5.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una cochera en un edificio ocupa unos 30 m², contando rampas y circulación. Si construir cuesta 1.000 dólares por m², ¿cuánto cuesta cada cochera?","unidad":"dólares","decimales":0,"contexto":"30 m² por cochera; 1000 dólares por m²."},"solucion":{"valor":30000,"tolerancia":600,"explicacion":"30 × 1.000 = 30.000 dólares por cochera. Si es obligatoria, ese costo se suma al precio de cada departamento, tenga o no auto quien lo compre. Valores de ejemplo."}},{"slug":"movilidad-5.s3.p2.v2","orden":2,"grupo":"movilidad-5.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una cochera en un edificio ocupa unos 30 m², contando rampas y circulación. Si construir cuesta 1.500 dólares por m², ¿cuánto cuesta cada cochera?","unidad":"dólares","decimales":0,"contexto":"30 m² por cochera; 1500 dólares por m²."},"solucion":{"valor":45000,"tolerancia":900,"explicacion":"30 × 1.500 = 45.000 dólares por cochera. Si es obligatoria, ese costo se suma al precio de cada departamento, tenga o no auto quien lo compre. Valores de ejemplo."}},{"slug":"movilidad-5.s3.p2.v3","orden":2,"grupo":"movilidad-5.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una cochera en un edificio ocupa unos 25 m², contando rampas y circulación. Si construir cuesta 800 dólares por m², ¿cuánto cuesta cada cochera?","unidad":"dólares","decimales":0,"contexto":"25 m² por cochera; 800 dólares por m²."},"solucion":{"valor":20000,"tolerancia":400,"explicacion":"25 × 800 = 20.000 dólares por cochera. Si es obligatoria, ese costo se suma al precio de cada departamento, tenga o no auto quien lo compre. Valores de ejemplo."}},{"slug":"movilidad-5.s3.p3","orden":3,"grupo":"movilidad-5.s3.p3","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo las cocheras obligatorias fomentan el auto.","items":[{"id":"i1","texto":"La norma exige una cochera por departamento"},{"id":"i2","texto":"Construir cada edificio cuesta más"},{"id":"i3","texto":"Los departamentos son más caros"},{"id":"i4","texto":"Quien no tiene auto igual paga su cochera"},{"id":"i5","texto":"Tener auto parece \"incluido\" y se usa más"},{"id":"i6","texto":"Las cocheras obligatorias abaratan las viviendas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un requisito que parece técnico cambia el precio de la vivienda y los hábitos de viaje."}},{"slug":"movilidad-5.s3.p4","orden":4,"grupo":"movilidad-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una política de estacionamiento medido busca que cada cuadra esté ocupada al 85 %. Si una cuadra tiene 20 lugares, ¿cuántos deberían quedar libres?","unidad":"lugares","decimales":0,"contexto":"20 lugares; ocupación objetivo del 85 %."},"solucion":{"valor":3,"tolerancia":0.5,"explicacion":"20 × 15 % = 3 lugares libres. Si siempre hay alguno libre, nadie da vueltas buscando, y eso reduce el tránsito y las emisiones."}},{"slug":"movilidad-5.s3.p4.v2","orden":4,"grupo":"movilidad-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una política de estacionamiento medido busca que cada cuadra esté ocupada al 85 %. Si una cuadra tiene 40 lugares, ¿cuántos deberían quedar libres?","unidad":"lugares","decimales":0,"contexto":"40 lugares; ocupación objetivo del 85 %."},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"40 × 15 % = 6 lugares libres. Si siempre hay alguno libre, nadie da vueltas buscando, y eso reduce el tránsito y las emisiones."}},{"slug":"movilidad-5.s3.p4.v3","orden":4,"grupo":"movilidad-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una política de estacionamiento medido busca que cada cuadra esté ocupada al 85 %. Si una cuadra tiene 60 lugares, ¿cuántos deberían quedar libres?","unidad":"lugares","decimales":0,"contexto":"60 lugares; ocupación objetivo del 85 %."},"solucion":{"valor":9,"tolerancia":0.5,"explicacion":"60 × 15 % = 9 lugares libres. Si siempre hay alguno libre, nadie da vueltas buscando, y eso reduce el tránsito y las emisiones."}},{"slug":"movilidad-5.s3.p5","orden":5,"grupo":"movilidad-5.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cobrar por la congestión","cuerpo":["Estocolmo probó cobrar por entrar y salir del centro entre enero y julio de 2006. El tránsito que cruzaba el cordón bajó entre un 20 y un 25 %. En un referéndum, los vecinos de la ciudad votaron por mantenerlo, y desde agosto de 2007 es permanente. Nueva York empezó a cobrar por entrar al sur de Manhattan en enero de 2025. Según la autoridad de transporte, en el primer año entraron 27 millones de vehículos menos, un 11 % menos, y se recaudaron más de 550 millones de dólares netos para el transporte público."],"destacado":{"valor":"−11 %","texto":"de vehículos entrando al sur de Manhattan en el primer año de cobro por congestión, según la autoridad de transporte de Nueva York."}},"solucion":{}},{"slug":"movilidad-5.s3.p6","orden":6,"grupo":"movilidad-5.s3.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En Nueva York entraron 27 millones de vehículos menos, un 11 % menos que sin el cobro. ¿Cuántos millones de vehículos habrían entrado sin el cobro? Redondeá al entero.","unidad":"millones de vehículos","decimales":0,"contexto":"27 millones menos; equivale al 11 %."},"solucion":{"valor":245,"tolerancia":3,"explicacion":"27 ÷ 0,11 ≈ 245 millones. Si 27 millones son el 11 %, el total de referencia es unas nueve veces mayor."}},{"slug":"movilidad-5.s3.p7","orden":7,"grupo":"movilidad-5.s3.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En Estocolmo, muchos vecinos se oponían al cobro antes de probarlo, pero votaron por mantenerlo después de la prueba. ¿Qué explica mejor ese cambio?","opciones":[{"id":"o1","texto":"Vieron en la práctica menos tránsito y viajes más rápidos"},{"id":"o2","texto":"Porque la prueba fue gratis para todos los conductores"},{"id":"o3","texto":"Porque durante la prueba se prohibieron los autos"},{"id":"o4","texto":"Porque el referéndum era obligatorio para aprobarlo"}]},"solucion":{"clave":["o1"],"explicacion":"Probar una medida y mostrar sus efectos puede cambiar la opinión pública más que cualquier discurso.","por_opcion":{"o3":"No se prohibieron: se cobró por cruzar el cordón."}}},{"slug":"movilidad-5.s3.p8","orden":8,"grupo":"movilidad-5.s3.p8","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Cobrar por entrar al centro solo sirve para recaudar.","razones":[{"id":"r1","texto":"Porque reduce el tránsito y puede financiar el transporte público"},{"id":"r2","texto":"Porque no cambia la cantidad de autos"},{"id":"r3","texto":"Porque la recaudación es siempre nula"}]},"solucion":{"valor":false,"explicacion":"Reduce el tránsito, acelera los colectivos y mejora el aire; además, la recaudación puede financiar transporte público, como en Nueva York.","clave":["r1"]}},{"slug":"movilidad-5.s3.p9","orden":9,"grupo":"movilidad-5.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Zonas de bajas emisiones","cuerpo":["Otra herramienta son las zonas de bajas emisiones: áreas donde los vehículos más contaminantes no pueden circular o pagan un cargo. Apuntan sobre todo a la calidad del aire. Funcionan mejor combinadas con alternativas de transporte y con ayudas para quienes tienen vehículos viejos y menos recursos, para que la medida no sea injusta."]},"solucion":{}},{"slug":"movilidad-5.s3.p10","orden":10,"grupo":"movilidad-5.s3.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada política con su objetivo principal.","izquierda":[{"id":"a1","texto":"Estacionamiento medido"},{"id":"a2","texto":"Cobro por congestión"},{"id":"a3","texto":"Zona de bajas emisiones"},{"id":"a4","texto":"Eliminar las cocheras obligatorias"}],"derecha":[{"id":"b1","texto":"Que siempre haya algún lugar libre por cuadra"},{"id":"b2","texto":"Menos autos en las zonas y horas más cargadas"},{"id":"b3","texto":"Aire más limpio en áreas densas"},{"id":"b4","texto":"Viviendas más baratas y menos incentivo al auto"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Poner precio al uso de la calle ordena el tránsito sin construir nada."}},{"slug":"movilidad-5.s3.p11","orden":11,"grupo":"movilidad-5.s3.p11","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es gestión de la demanda o aumento de la oferta vial?","grupos":[{"id":"g1","nombre":"Gestión de la demanda"},{"id":"g2","nombre":"Aumento de la oferta vial"}],"items":[{"id":"i1","texto":"Cobro por congestión"},{"id":"i2","texto":"Una autopista nueva"},{"id":"i3","texto":"Estacionamiento medido"},{"id":"i4","texto":"Dos carriles más en una avenida"},{"id":"i5","texto":"Zona de bajas emisiones"},{"id":"i6","texto":"Un distribuidor de tránsito"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La gestión de la demanda actúa sobre cuántos viajes en auto se hacen; la oferta, sobre cuánto espacio tienen."}},{"slug":"movilidad-5.s3.p12","orden":12,"grupo":"movilidad-5.s3.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más justo un cobro por congestión? Marcá todo.","opciones":[{"id":"o1","texto":"Invertir lo recaudado en transporte público"},{"id":"o2","texto":"Exenciones para personas con discapacidad"},{"id":"o3","texto":"Descuentos para hogares de bajos ingresos"},{"id":"o4","texto":"Probarlo antes y consultar a la población"},{"id":"o5","texto":"Usar la recaudación para ensanchar autopistas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La aceptación y la equidad dependen mucho de qué se hace con el dinero."}},{"slug":"movilidad-5.s3.p13","orden":13,"grupo":"movilidad-5.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta columna de opinión y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Estocolmo cobra por entrar al centro desde 2007, tras una prueba en 2006."},{"id":"s2","texto":"El estacionamiento gratis no le cuesta nada a nadie."},{"id":"s3","texto":"En Nueva York bajó el tránsito que entra a la zona con cobro."},{"id":"s4","texto":"Cobrar por congestión nunca cambia la cantidad de autos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los precios cambian conductas: ignorarlo lleva a políticas que no funcionan.","por_opcion":{"s2":"Su costo se paga escondido en viviendas, comercios o impuestos.","s4":"Estocolmo y Nueva York muestran bajas claras del tránsito."}}},{"slug":"movilidad-5.s3.p14","orden":14,"grupo":"movilidad-5.s3.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cobrar el estacionamiento para que quede algún lugar libre busca una ocupación de alrededor del {{0}} %; Estocolmo cobra por la {{1}} desde 2007; y en Nueva York el tránsito que entra a la zona bajó un {{2}} %.","banco":[{"id":"w1","texto":"85"},{"id":"w2","texto":"congestión"},{"id":"w3","texto":"11"},{"id":"w4","texto":"50"},{"id":"w5","texto":"contaminación"},{"id":"w6","texto":"25"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos para discutir el precio de usar la calle."}}]},{"slug":"movilidad-5.s4","orden":4,"tipo":"leccion","titulo_es":"Calles para estar","bajada_es":"Supermanzanas, 30 km/h, Visión Cero y urbanismo táctico: cómo se rediseña una calle para vivirla.","minutos":12,"pasos":[{"slug":"movilidad-5.s4.p1","orden":1,"grupo":"movilidad-5.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto espacio para quién","cuerpo":["En muchas avenidas, la mayor parte del ancho entre fachadas está dedicada a autos que circulan o estacionan, aunque por la calle se muevan más personas a pie o en colectivo. Rediseñar una calle es, antes que nada, repartir de nuevo ese espacio."]},"solucion":{}},{"slug":"movilidad-5.s4.p2","orden":2,"grupo":"movilidad-5.s4.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una calle mide 20 m entre fachadas: 14 m de calzada para autos (circulación y estacionamiento) y 6 m de veredas en total. ¿Qué porcentaje del ancho es para los autos?","unidad":"%","decimales":0,"contexto":"14 m de calzada; 6 m de veredas."},"solucion":{"valor":70,"tolerancia":1.4000000000000001,"explicacion":"14 ÷ 20 × 100 = 70 %. Si por esa calle camina más gente de la que maneja, el reparto no refleja cómo se usa."}},{"slug":"movilidad-5.s4.p2.v2","orden":2,"grupo":"movilidad-5.s4.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una calle mide 20 m entre fachadas: 12 m de calzada para autos (circulación y estacionamiento) y 8 m de veredas en total. ¿Qué porcentaje del ancho es para los autos?","unidad":"%","decimales":0,"contexto":"12 m de calzada; 8 m de veredas."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"12 ÷ 20 × 100 = 60 %. Si por esa calle camina más gente de la que maneja, el reparto no refleja cómo se usa."}},{"slug":"movilidad-5.s4.p2.v3","orden":2,"grupo":"movilidad-5.s4.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una calle mide 20 m entre fachadas: 16 m de calzada para autos (circulación y estacionamiento) y 4 m de veredas en total. ¿Qué porcentaje del ancho es para los autos?","unidad":"%","decimales":0,"contexto":"16 m de calzada; 4 m de veredas."},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"16 ÷ 20 × 100 = 80 %. Si por esa calle camina más gente de la que maneja, el reparto no refleja cómo se usa."}},{"slug":"movilidad-5.s4.p3","orden":3,"grupo":"movilidad-5.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Supermanzanas","cuerpo":["En Barcelona, una supermanzana agrupa varias manzanas: el tránsito de paso se desvía por el perímetro, y las calles interiores se vuelven lugares para caminar, jugar y tener verde, con acceso lento para vecinos, emergencias y cargas. Un estudio de 2020 estimó que implementar 503 supermanzanas en la ciudad podría evitar unas 667 muertes prematuras por año, sobre todo por menos dióxido de nitrógeno, menos ruido, menos calor y más verde."]},"solucion":{}},{"slug":"movilidad-5.s4.p4","orden":4,"grupo":"movilidad-5.s4.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cómo funciona una supermanzana?","opciones":[{"id":"o1","texto":"Desvía el tránsito de paso al perímetro y libera el interior"},{"id":"o2","texto":"Prohíbe todos los vehículos, incluidas las ambulancias"},{"id":"o3","texto":"Construye una autopista alrededor de cada barrio"},{"id":"o4","texto":"Junta varias manzanas en un solo edificio muy alto"}]},"solucion":{"clave":["o1"],"explicacion":"No se trata de prohibir el acceso, sino de sacar el tránsito que solo pasa.","por_opcion":{"o3":"Usa las avenidas existentes; no construye autopistas."}}},{"slug":"movilidad-5.s4.p5","orden":5,"grupo":"movilidad-5.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De las 667 muertes evitables estimadas para las supermanzanas de Barcelona, 291 se deben a la reducción del dióxido de nitrógeno. ¿Qué porcentaje es? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"291 de 667 muertes evitables."},"solucion":{"valor":44,"tolerancia":1,"explicacion":"291 ÷ 667 × 100 ≈ 44 %. El resto se reparte entre menos ruido, menos calor y más espacios verdes."}},{"slug":"movilidad-5.s4.p6","orden":6,"grupo":"movilidad-5.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Velocidad, diseño y Visión Cero","cuerpo":["La Declaración de Estocolmo de 2020, adoptada en la Conferencia Ministerial Mundial sobre Seguridad Vial, pide un límite máximo de 30 km/h donde peatones, ciclistas y vehículos se mezclan de forma frecuente. Los límites funcionan mejor cuando la calle misma invita a ir despacio: carriles angostos, cruces elevados, árboles, esquinas con veredas ampliadas.","El enfoque Visión Cero, adoptado por Suecia en 1997, parte de que las personas se equivocan, y de que el sistema vial debe diseñarse para que esos errores no terminen en muertes ni heridas graves."]},"solucion":{}},{"slug":"movilidad-5.s4.p7","orden":7,"grupo":"movilidad-5.s4.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el diseño de una calle mejora la seguridad.","items":[{"id":"i1","texto":"Se angostan los carriles y se elevan los cruces"},{"id":"i2","texto":"Los conductores bajan la velocidad sin necesidad de un cartel"},{"id":"i3","texto":"Tienen más tiempo para ver y frenar"},{"id":"i4","texto":"Los choques son menos frecuentes y menos graves"},{"id":"i5","texto":"Hay menos muertes y heridos en esa calle"},{"id":"i6","texto":"Carriles más anchos hacen manejar más despacio"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una calle bien diseñada hace que la velocidad segura sea la natural."}},{"slug":"movilidad-5.s4.p8","orden":8,"grupo":"movilidad-5.s4.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El enfoque Visión Cero parte de que las personas nunca se equivocan al manejar o al cruzar.","razones":[{"id":"r1","texto":"Porque acepta los errores humanos y diseña para que no maten"},{"id":"r2","texto":"Porque culpa solo a los peatones de los choques"},{"id":"r3","texto":"Porque propone subir las velocidades máximas"}]},"solucion":{"valor":false,"explicacion":"Es al revés: acepta que las personas se equivocan y propone diseñar calles, vehículos y velocidades para que esos errores no maten.","clave":["r1"]}},{"slug":"movilidad-5.s4.p9","orden":9,"grupo":"movilidad-5.s4.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿La medida baja la velocidad por diseño o depende solo de un cartel?","grupos":[{"id":"g1","nombre":"Por diseño"},{"id":"g2","nombre":"Solo un cartel"}],"items":[{"id":"i1","texto":"Cruces peatonales elevados"},{"id":"i2","texto":"Un cartel de \"máxima 30\" en una avenida ancha y recta"},{"id":"i3","texto":"Carriles más angostos"},{"id":"i4","texto":"Un cartel de \"zona escolar\" sin otros cambios"},{"id":"i5","texto":"Esquinas con veredas ampliadas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Los carteles ayudan, pero la forma de la calle es lo que más cambia la velocidad real."}},{"slug":"movilidad-5.s4.p10","orden":10,"grupo":"movilidad-5.s4.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Probar antes de construir","cuerpo":["El urbanismo táctico prueba cambios con materiales baratos y rápidos: pintura, macetas, bolardos, bancos. Se mide qué pasa con la velocidad, el uso y la opinión de los vecinos, se ajusta y, si funciona, se construye la versión permanente. Las calles escolares, que se cierran al tránsito en los horarios de entrada y salida, suelen empezar así."]},"solucion":{}},{"slug":"movilidad-5.s4.p11","orden":11,"grupo":"movilidad-5.s4.p11","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de una intervención de urbanismo táctico.","items":[{"id":"i1","texto":"Detectar el problema con vecinos y datos"},{"id":"i2","texto":"Probar el cambio con pintura y macetas"},{"id":"i3","texto":"Medir velocidad, uso y opiniones"},{"id":"i4","texto":"Ajustar el diseño"},{"id":"i5","texto":"Construir la versión permanente"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Probar barato y medir permite corregir antes de invertir mucho."}},{"slug":"movilidad-5.s4.p12","orden":12,"grupo":"movilidad-5.s4.p12","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada intervención con su beneficio principal.","izquierda":[{"id":"a1","texto":"Árboles en la vereda"},{"id":"a2","texto":"Cruce elevado"},{"id":"a3","texto":"Calle escolar"},{"id":"a4","texto":"Supermanzana"}],"derecha":[{"id":"b1","texto":"Sombra y menos calor"},{"id":"b2","texto":"Autos que frenan ante los peatones"},{"id":"b3","texto":"Entrada a la escuela sin autos"},{"id":"b4","texto":"Interior del barrio sin tránsito de paso"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada intervención resuelve algo concreto, y juntas cambian el carácter de un barrio."}},{"slug":"movilidad-5.s4.p13","orden":13,"grupo":"movilidad-5.s4.p13","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que una calle invite a quedarse? Marcá todo.","opciones":[{"id":"o1","texto":"Sombra de árboles"},{"id":"o2","texto":"Lugares para sentarse"},{"id":"o3","texto":"Tránsito lento y poco ruido"},{"id":"o4","texto":"Comercios y actividad en planta baja"},{"id":"o5","texto":"Autos estacionados en toda la vereda"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las calles también son el espacio público más grande de una ciudad."}},{"slug":"movilidad-5.s4.p14","orden":14,"grupo":"movilidad-5.s4.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta vecinal y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Probaremos una calle escolar con vallas en los horarios de entrada y salida."},{"id":"s2","texto":"Para bajar la velocidad alcanza con un cartel de 30 en la avenida de cuatro carriles."},{"id":"s3","texto":"Mediremos la velocidad antes y después de la prueba."},{"id":"s4","texto":"La supermanzana prohibirá la entrada de ambulancias."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen rediseño combina diseño físico, medición y participación.","por_opcion":{"s2":"Sin cambios de diseño, la velocidad real casi no baja.","s4":"Emergencias, vecinos y cargas siguen entrando, a baja velocidad."}}},{"slug":"movilidad-5.s4.p15","orden":15,"grupo":"movilidad-5.s4.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Agrupar manzanas y sacar el tránsito de paso crea una {{0}}; la Declaración de Estocolmo pide un máximo de {{1}} km/h donde se mezclan peatones y vehículos; y probar cambios con pintura y macetas es urbanismo {{2}}.","banco":[{"id":"w1","texto":"supermanzana"},{"id":"w2","texto":"30"},{"id":"w3","texto":"táctico"},{"id":"w4","texto":"autopista"},{"id":"w5","texto":"60"},{"id":"w6","texto":"rígido"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres herramientas para calles más seguras y habitables."}}]},{"slug":"movilidad-5.s5","orden":5,"tipo":"leccion","titulo_es":"Movilidad justa","bajada_es":"Quién se mueve cómo: ingresos, género, edad y discapacidad, y cómo planificar con todas las personas.","minutos":10,"pasos":[{"slug":"movilidad-5.s5.p1","orden":1,"grupo":"movilidad-5.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No todos se mueven igual","cuerpo":["La forma de moverse cambia mucho según el ingreso, el género, la edad y la discapacidad. Según estudios de CAF en ciudades de América Latina, las mujeres usan más el transporte público y caminan más, hacen viajes más cortos y en horarios variados, y encadenan paradas ligadas a tareas de cuidado: llevar a los chicos a la escuela, hacer compras, acompañar a alguien al médico. El mayor obstáculo que señalan es el acoso en el transporte y las paradas.","Los hogares de menores ingresos, que muchas veces viven en la periferia, suelen tener viajes más largos, con más transbordos, y gastar una parte mayor de su ingreso en moverse."]},"solucion":{}},{"slug":"movilidad-5.s5.p2","orden":2,"grupo":"movilidad-5.s5.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un viaje pendular o un viaje encadenado?","grupos":[{"id":"g1","nombre":"Pendular"},{"id":"g2","nombre":"Encadenado"}],"items":[{"id":"i1","texto":"Casa, trabajo y vuelta a casa"},{"id":"i2","texto":"Casa, escuela de los chicos, trabajo, supermercado y casa"},{"id":"i3","texto":"Casa, facultad y vuelta a casa"},{"id":"i4","texto":"Casa, centro de salud con un familiar, farmacia y casa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Las encuestas que solo miran el viaje al trabajo pierden buena parte de la movilidad de cuidado."}},{"slug":"movilidad-5.s5.p3","orden":3,"grupo":"movilidad-5.s5.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué una encuesta que solo pregunta por el viaje al trabajo subestima las necesidades de muchas mujeres?","opciones":[{"id":"o1","texto":"Porque no registra los viajes de cuidado encadenados"},{"id":"o2","texto":"Porque las mujeres casi no viajan al trabajo"},{"id":"o3","texto":"Porque las mujeres no usan el transporte público"},{"id":"o4","texto":"Porque los viajes de cuidado son siempre en auto"}]},"solucion":{"clave":["o1"],"explicacion":"Lo que no se mide no se planifica: los viajes de cuidado quedan invisibles.","por_opcion":{"o3":"Según CAF, son sus principales usuarias."}}},{"slug":"movilidad-5.s5.p4","orden":4,"grupo":"movilidad-5.s5.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un hogar tiene ingresos de 500.000 pesos por mes y gasta 60.000 en transporte. ¿Qué porcentaje de su ingreso gasta en moverse?","unidad":"%","decimales":0,"contexto":"Ingreso de 500000; gasto de 60000 en transporte."},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"60.000 ÷ 500.000 × 100 = 12 %. Valores de ejemplo: el mismo pasaje pesa mucho más en un hogar de menores ingresos."}},{"slug":"movilidad-5.s5.p4.v2","orden":4,"grupo":"movilidad-5.s5.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un hogar tiene ingresos de 300.000 pesos por mes y gasta 54.000 en transporte. ¿Qué porcentaje de su ingreso gasta en moverse?","unidad":"%","decimales":0,"contexto":"Ingreso de 300000; gasto de 54000 en transporte."},"solucion":{"valor":18,"tolerancia":0.5,"explicacion":"54.000 ÷ 300.000 × 100 = 18 %. Valores de ejemplo: el mismo pasaje pesa mucho más en un hogar de menores ingresos."}},{"slug":"movilidad-5.s5.p4.v3","orden":4,"grupo":"movilidad-5.s5.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un hogar tiene ingresos de 900.000 pesos por mes y gasta 45.000 en transporte. ¿Qué porcentaje de su ingreso gasta en moverse?","unidad":"%","decimales":0,"contexto":"Ingreso de 900000; gasto de 45000 en transporte."},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"45.000 ÷ 900.000 × 100 = 5 %. Valores de ejemplo: el mismo pasaje pesa mucho más en un hogar de menores ingresos."}},{"slug":"movilidad-5.s5.p5","orden":5,"grupo":"movilidad-5.s5.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona tarda 90 minutos en cada sentido para ir a trabajar, 22 días por mes. ¿Cuántas horas por mes pasa viajando?","unidad":"horas","decimales":0,"contexto":"90 minutos por sentido; 22 días."},"solucion":{"valor":66,"tolerancia":1.32,"explicacion":"90 × 2 × 22 = 3960 minutos = 66 horas por mes. Tiempo que no se puede dedicar a descansar, estudiar o cuidar."}},{"slug":"movilidad-5.s5.p5.v2","orden":5,"grupo":"movilidad-5.s5.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona tarda 60 minutos en cada sentido para ir a trabajar, 22 días por mes. ¿Cuántas horas por mes pasa viajando?","unidad":"horas","decimales":0,"contexto":"60 minutos por sentido; 22 días."},"solucion":{"valor":44,"tolerancia":0.88,"explicacion":"60 × 2 × 22 = 2640 minutos = 44 horas por mes. Tiempo que no se puede dedicar a descansar, estudiar o cuidar."}},{"slug":"movilidad-5.s5.p5.v3","orden":5,"grupo":"movilidad-5.s5.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona tarda 120 minutos en cada sentido para ir a trabajar, 22 días por mes. ¿Cuántas horas por mes pasa viajando?","unidad":"horas","decimales":0,"contexto":"120 minutos por sentido; 22 días."},"solucion":{"valor":88,"tolerancia":1.76,"explicacion":"120 × 2 × 22 = 5280 minutos = 88 horas por mes. Tiempo que no se puede dedicar a descansar, estudiar o cuidar."}},{"slug":"movilidad-5.s5.p6","orden":6,"grupo":"movilidad-5.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el acoso en el transporte reduce oportunidades.","items":[{"id":"i1","texto":"Hay acoso en paradas y vehículos"},{"id":"i2","texto":"Muchas mujeres evitan ciertos horarios o recorridos"},{"id":"i3","texto":"Eligen viajes más caros o más largos, o no viajan"},{"id":"i4","texto":"Pierden acceso a trabajos, estudios o actividades"},{"id":"i5","texto":"Se profundiza la desigualdad"},{"id":"i6","texto":"El acoso solo afecta el viaje del día en que ocurre"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La seguridad personal es una condición para que el transporte público sea realmente público."}},{"slug":"movilidad-5.s5.p7","orden":7,"grupo":"movilidad-5.s5.p7","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada grupo con una barrera frecuente.","izquierda":[{"id":"a1","texto":"Personas en silla de ruedas"},{"id":"a2","texto":"Niñas y niños"},{"id":"a3","texto":"Mujeres"},{"id":"a4","texto":"Barrios de la periferia"}],"derecha":[{"id":"b1","texto":"Colectivos sin piso bajo ni rampa"},{"id":"b2","texto":"Cruces peligrosos camino a la escuela"},{"id":"b3","texto":"Acoso en paradas y vehículos"},{"id":"b4","texto":"Viajes largos con varios transbordos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada barrera tiene soluciones concretas, si se la ve."}},{"slug":"movilidad-5.s5.p8","orden":8,"grupo":"movilidad-5.s5.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el tiempo promedio de viaje de la ciudad baja, mejora para todas las personas.","razones":[{"id":"r1","texto":"Porque el promedio puede esconder que algunos grupos empeoran"},{"id":"r2","texto":"Porque los promedios siempre muestran a todos por igual"},{"id":"r3","texto":"Porque el tiempo de viaje no importa"}]},"solucion":{"valor":false,"explicacion":"Un promedio puede bajar mientras empeora para algunos grupos, por ejemplo en la periferia. Hay que mirar los datos separados por barrio, ingreso y género.","clave":["r1"]}},{"slug":"movilidad-5.s5.p9","orden":9,"grupo":"movilidad-5.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Planificar con todas las personas","cuerpo":["Una movilidad justa se planifica con datos separados por género, ingreso, edad y discapacidad; con la participación de quienes viajan; y con medidas concretas: paradas iluminadas y visibles, colectivos accesibles, tarifas integradas que no castiguen los transbordos, cruces seguros cerca de escuelas y veredas sin obstáculos."]},"solucion":{}},{"slug":"movilidad-5.s5.p10","orden":10,"grupo":"movilidad-5.s5.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas hacen la movilidad más justa? Marcá todas.","opciones":[{"id":"o1","texto":"Paradas iluminadas y visibles"},{"id":"o2","texto":"Colectivos con piso bajo y rampa"},{"id":"o3","texto":"Tarifas integradas que no cobren de más por transbordar"},{"id":"o4","texto":"Encuestas que registren los viajes de cuidado"},{"id":"o5","texto":"Planificar solo con datos del viaje al trabajo en auto"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La movilidad justa se diseña mirando a quienes hoy tienen más dificultades."}},{"slug":"movilidad-5.s5.p11","orden":11,"grupo":"movilidad-5.s5.p11","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de una planificación participativa de la movilidad.","items":[{"id":"i1","texto":"Relevar cómo viajan las personas, con datos separados por grupo"},{"id":"i2","texto":"Escuchar a vecinas, vecinos y organizaciones"},{"id":"i3","texto":"Identificar las barreras principales"},{"id":"i4","texto":"Diseñar y probar soluciones"},{"id":"i5","texto":"Evaluar con los mismos grupos y ajustar"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Participar desde el principio mejora las soluciones y su aceptación."}},{"slug":"movilidad-5.s5.p12","orden":12,"grupo":"movilidad-5.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este diagnóstico municipal y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Relevamos los viajes al trabajo y también los de cuidado."},{"id":"s2","texto":"Como el tiempo promedio bajó, no hace falta mirar la periferia."},{"id":"s3","texto":"Las paradas nuevas tendrán iluminación."},{"id":"s4","texto":"El acoso es un tema policial, no de planificación del transporte."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un diagnóstico justo mira quién queda afuera de los promedios.","por_opcion":{"s2":"El promedio puede esconder que en la periferia empeoró.","s4":"El diseño de paradas, horarios e iluminación también lo previene."}}},{"slug":"movilidad-5.s5.p13","orden":13,"grupo":"movilidad-5.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un viaje con varias paradas ligadas al cuidado es un viaje {{0}}; el que va de casa al trabajo y vuelve es {{1}}; y para ver desigualdades hay que mirar datos separados por {{2}}.","banco":[{"id":"w1","texto":"encadenado"},{"id":"w2","texto":"pendular"},{"id":"w3","texto":"grupo"},{"id":"w4","texto":"directo"},{"id":"w5","texto":"circular"},{"id":"w6","texto":"color"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para planificar una movilidad para todas las personas."}}]},{"slug":"movilidad-5.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: ciudades para las personas","bajada_es":"Accesibilidad, demanda inducida, precios, rediseño de calles y movilidad justa, mezclados.","minutos":8,"pasos":[{"slug":"movilidad-5.s6.p1","orden":1,"grupo":"movilidad-5.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Ciudades para las personas». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"movilidad-5.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la avenida de San Martín del Río","bajada_es":"Una ciudad mediana discute rediseñar su avenida principal. Con los conteos, evaluá la propuesta y cómo implementarla.","minutos":10,"pasos":[{"slug":"movilidad-5.s7.p1","orden":1,"grupo":"movilidad-5.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["La avenida mide 24 m entre fachadas: 18 m de calzada (cuatro carriles y dos de estacionamiento) y 3 m de vereda de cada lado. En la hora pico pasan 1.200 personas en 1.000 autos, 2.400 en 40 colectivos, 300 en bicicleta y 3.000 a pie. La propuesta: dejar un carril para autos por sentido, sumar un carril exclusivo de colectivos por sentido y ciclovías protegidas, ensanchar las veredas y plantar árboles. Algunos comerciantes temen que \"todo el tránsito se vaya a las calles vecinas\"."]},"solucion":{}},{"slug":"movilidad-5.s7.p2","orden":2,"grupo":"movilidad-5.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje del ancho entre fachadas ocupa hoy la calzada para autos?","unidad":"%","decimales":0,"contexto":"18 m de calzada en 24 m."},"solucion":{"valor":75,"tolerancia":1.5,"explicacion":"18 ÷ 24 × 100 = 75 %: tres cuartos de la avenida para el vehículo que menos personas mueve."}},{"slug":"movilidad-5.s7.p3","orden":3,"grupo":"movilidad-5.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Sin contar a quienes caminan, ¿qué porcentaje de las personas que circulan por la avenida en hora pico va en auto? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"1.200 en auto, 2.400 en colectivo y 300 en bici."},"solucion":{"valor":31,"tolerancia":1,"explicacion":"1.200 ÷ (1.200 + 2.400 + 300) × 100 = 1.200 ÷ 3.900 × 100 ≈ 31 %."}},{"slug":"movilidad-5.s7.p4","orden":4,"grupo":"movilidad-5.s7.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué argumento justifica mejor el nuevo reparto del espacio?","opciones":[{"id":"o1","texto":"La mayoría viaja en colectivo, en bici o a pie"},{"id":"o2","texto":"Que los autos contaminan y por eso hay que castigarlos"},{"id":"o3","texto":"Que los colectivos no necesitan carriles propios"},{"id":"o4","texto":"Que las avenidas anchas son siempre peligrosas"}]},"solucion":{"clave":["o1"],"explicacion":"Repartir el espacio según cuántas personas mueve cada modo es un criterio de eficiencia y de justicia.","por_opcion":{"o3":"Los necesitan: un carril exclusivo los hace más rápidos y regulares."}}},{"slug":"movilidad-5.s7.p5","orden":5,"grupo":"movilidad-5.s7.p5","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué objetivo apunta cada parte de la propuesta?","grupos":[{"id":"g1","nombre":"Mover más personas"},{"id":"g2","nombre":"Seguridad y vida en la calle"}],"items":[{"id":"i1","texto":"Carril exclusivo de colectivos"},{"id":"i2","texto":"Veredas más anchas"},{"id":"i3","texto":"Ciclovías protegidas"},{"id":"i4","texto":"Árboles y bancos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Una buena avenida mueve más gente y, a la vez, es un lugar mejor para estar."}},{"slug":"movilidad-5.s7.p6","orden":6,"grupo":"movilidad-5.s7.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si se sacan dos carriles para autos, todo ese tránsito se va a pasar a las calles vecinas.","razones":[{"id":"r1","texto":"Porque parte del tránsito se evapora o cambia de modo"},{"id":"r2","texto":"Porque los autos desaparecen por completo de la ciudad"},{"id":"r3","texto":"Porque las calles vecinas no tienen tránsito"}]},"solucion":{"valor":false,"explicacion":"Parte del tránsito se reorganiza, pero parte se \"evapora\": viajes que cambian de modo, de horario o se combinan. Conviene medirlo y cuidar las calles vecinas.","clave":["r1"]}},{"slug":"movilidad-5.s7.p7","orden":7,"grupo":"movilidad-5.s7.p7","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cómo implementar la propuesta.","items":[{"id":"i1","texto":"Presentar los conteos y la propuesta a vecinos y comerciantes"},{"id":"i2","texto":"Probar el nuevo reparto con pintura y separadores"},{"id":"i3","texto":"Medir tiempos de viaje, ventas y tránsito en calles vecinas"},{"id":"i4","texto":"Ajustar el diseño según los datos"},{"id":"i5","texto":"Construir la versión permanente con árboles"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Probar, medir y ajustar reduce riesgos y construye apoyo."}},{"slug":"movilidad-5.s7.p8","orden":8,"grupo":"movilidad-5.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio redacta el proyecto. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"El carril exclusivo hará más rápidos y regulares a los colectivos."},{"id":"s2","texto":"No mediremos las calles vecinas, porque el tránsito se evapora todo."},{"id":"s3","texto":"Probaremos primero con materiales temporales."},{"id":"s4","texto":"La decisión se tomará sin consultar a comerciantes ni vecinos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen proyecto se apoya en datos, pruebas y participación.","por_opcion":{"s2":"Solo una parte se evapora: hay que medir y cuidar las calles vecinas.","s4":"La participación mejora el diseño y la aceptación."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"movilidad-6","rama":"movilidad","orden":6,"nivel":3,"titulo_es":"Carga, logística y viajes largos","bajada_es":"Camiones, trenes, barcazas, paquetes a domicilio, aviones y vacaciones: la parte del transporte que no se ve desde la parada del colectivo.","objetivos_es":["Calcular toneladas-kilómetro y comparar las emisiones de cada modo de carga","Analizar cuándo conviene combinar camión, tren y barcaza","Proponer soluciones para la última milla de las entregas","Explicar el impacto climático de la aviación y quiénes lo generan","Comparar opciones para viajes largos y turismo de menor huella"],"repasa":["movilidad-1","movilidad-2","movilidad-4","movilidad-5"],"requiere_tronco":3,"fuentes":["bcr-cargas-2018","bcr-cargas-2024","eea-intensidad-transporte","owid-aviacion","owid-huella-viajes","gossling-humpe-2020","iata-saf-2024","francia-vuelos-cortos","imo-ghg4","imo-estrategia-2023","lenzen-2018-turismo"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"movilidad-6.s1","orden":1,"tipo":"leccion","titulo_es":"Cómo se mueve la carga","bajada_es":"Toneladas-kilómetro, el dominio del camión en Argentina y cuánto emite cada modo.","minutos":10,"pasos":[{"slug":"movilidad-6.s1.p1","orden":1,"grupo":"movilidad-6.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Toneladas por kilómetro","cuerpo":["Para comparar el transporte de carga se usa la tonelada-kilómetro: mover una tonelada a lo largo de un kilómetro. Un camión con 30 toneladas que recorre 400 km hace 12.000 toneladas-kilómetro.","Según la Bolsa de Comercio de Rosario, en 2018 se transportaron en Argentina unos 537 millones de toneladas de mercaderías: el 92,7 % en camión, el 3,7 % por agua, el 3,5 % en tren y apenas el 0,04 % en avión. Medido en toneladas-kilómetro, el camión concentró el 88 %."],"datos":{"tipo":"barras","titulo":"Carga transportada en Argentina por modo (2018)","unidad":"% de las toneladas","filas":[{"etiqueta":"Camión","valor":92.7},{"etiqueta":"Por agua","valor":3.7},{"etiqueta":"Tren","valor":3.5},{"etiqueta":"Avión","valor":0.04}],"nota":"Bolsa de Comercio de Rosario."}},"solucion":{}},{"slug":"movilidad-6.s1.p2","orden":2,"grupo":"movilidad-6.s1.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un camión lleva 30 toneladas a lo largo de 400 km. ¿Cuántas toneladas-kilómetro hace?","unidad":"toneladas-kilómetro","decimales":0,"contexto":"Carga de 30 toneladas; recorrido de 400 km."},"solucion":{"valor":12000,"tolerancia":240,"explicacion":"30 × 400 = 12.000 toneladas-kilómetro. Con esta unidad se pueden comparar cargas y distancias distintas."}},{"slug":"movilidad-6.s1.p2.v2","orden":2,"grupo":"movilidad-6.s1.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un camión lleva 25 toneladas a lo largo de 600 km. ¿Cuántas toneladas-kilómetro hace?","unidad":"toneladas-kilómetro","decimales":0,"contexto":"Carga de 25 toneladas; recorrido de 600 km."},"solucion":{"valor":15000,"tolerancia":300,"explicacion":"25 × 600 = 15.000 toneladas-kilómetro. Con esta unidad se pueden comparar cargas y distancias distintas."}},{"slug":"movilidad-6.s1.p2.v3","orden":2,"grupo":"movilidad-6.s1.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un camión lleva 40 toneladas a lo largo de 350 km. ¿Cuántas toneladas-kilómetro hace?","unidad":"toneladas-kilómetro","decimales":0,"contexto":"Carga de 40 toneladas; recorrido de 350 km."},"solucion":{"valor":14000,"tolerancia":280,"explicacion":"40 × 350 = 14.000 toneladas-kilómetro. Con esta unidad se pueden comparar cargas y distancias distintas."}},{"slug":"movilidad-6.s1.p3","orden":3,"grupo":"movilidad-6.s1.p3","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las toneladas de carga de Argentina viaja en camión.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":93,"banda":"lineal","explicacion":"Un 92,7 % en 2018, según la Bolsa de Comercio de Rosario: el tren y el agua juntos no llegan al 8 %."}},{"slug":"movilidad-6.s1.p4","orden":4,"grupo":"movilidad-6.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto emite cada modo","cuerpo":["Un estudio para la Agencia Europea de Medio Ambiente calculó cuánto emite cada modo de carga por tonelada-kilómetro en la Unión Europea en 2018, incluida la producción del combustible. Un camión pesado emitía unos 137 g de CO₂e por tonelada-kilómetro. El tren, alrededor del 18 % de eso (unos 25 g); las barcazas fluviales, el 24 % (unos 33 g); y el barco marítimo, apenas el 5 % (unos 7 g). En el otro extremo, el avión de carga y las camionetas de reparto emitían unas 16 veces más que el camión pesado."],"datos":{"tipo":"barras","titulo":"Emisiones de la carga por tonelada-kilómetro (UE, 2018, aproximado)","unidad":"g CO₂e","filas":[{"etiqueta":"Avión de carga","valor":2200},{"etiqueta":"Camión pesado","valor":137},{"etiqueta":"Barcaza fluvial","valor":33},{"etiqueta":"Tren","valor":25},{"etiqueta":"Barco marítimo","valor":7}],"nota":"Estudio para la Agencia Europea de Medio Ambiente; valores redondeados."}},"solucion":{}},{"slug":"movilidad-6.s1.p5","orden":5,"grupo":"movilidad-6.s1.p5","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos modos de carga por sus emisiones por tonelada-kilómetro, de más a menos.","items":[{"id":"i1","texto":"Avión de carga"},{"id":"i2","texto":"Camión pesado"},{"id":"i3","texto":"Tren"},{"id":"i4","texto":"Barco marítimo"}],"extremos":["Más emisiones","Menos emisiones"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Entre el avión y el barco hay una diferencia de cientos de veces por tonelada movida.","valores":{"i1":"≈ 2.200 g","i2":"≈ 137 g","i3":"≈ 25 g","i4":"≈ 7 g"}}},{"slug":"movilidad-6.s1.p6","orden":6,"grupo":"movilidad-6.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un camión pesado lleva 30 toneladas a 500 km. Con 137 g de CO₂e por tonelada-kilómetro, ¿cuántos kilos de CO₂e emite el viaje? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"30 t; 500 km; 137 g por t-km."},"solucion":{"valor":2055,"tolerancia":1,"explicacion":"30 × 500 = 15.000 t-km; × 137 g = 2.055.000 g ≈ 2.055 kg de CO₂e."}},{"slug":"movilidad-6.s1.p6.v2","orden":6,"grupo":"movilidad-6.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un camión pesado lleva 20 toneladas a 300 km. Con 137 g de CO₂e por tonelada-kilómetro, ¿cuántos kilos de CO₂e emite el viaje? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"20 t; 300 km; 137 g por t-km."},"solucion":{"valor":822,"tolerancia":1,"explicacion":"20 × 300 = 6.000 t-km; × 137 g = 822.000 g ≈ 822 kg de CO₂e."}},{"slug":"movilidad-6.s1.p6.v3","orden":6,"grupo":"movilidad-6.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un camión pesado lleva 30 toneladas a 1000 km. Con 137 g de CO₂e por tonelada-kilómetro, ¿cuántos kilos de CO₂e emite el viaje? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"30 t; 1000 km; 137 g por t-km."},"solucion":{"valor":4110,"tolerancia":1,"explicacion":"30 × 1000 = 30.000 t-km; × 137 g = 4.110.000 g ≈ 4.110 kg de CO₂e."}},{"slug":"movilidad-6.s1.p7","orden":7,"grupo":"movilidad-6.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una carga de 12.000 toneladas-kilómetro pasa del camión (137 g por t-km) al tren (25 g por t-km). ¿Cuántos kilos de CO₂e se ahorran?","unidad":"kg CO₂e","decimales":0,"contexto":"12000 t-km; 137 contra 25 g por t-km."},"solucion":{"valor":1344,"tolerancia":1,"explicacion":"(137 − 25) × 12.000 = 1.344.000 g ≈ 1.344 kg. El tren emite cerca de un 80 % menos por tonelada movida."}},{"slug":"movilidad-6.s1.p7.v2","orden":7,"grupo":"movilidad-6.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una carga de 20.000 toneladas-kilómetro pasa del camión (137 g por t-km) al tren (25 g por t-km). ¿Cuántos kilos de CO₂e se ahorran?","unidad":"kg CO₂e","decimales":0,"contexto":"20000 t-km; 137 contra 25 g por t-km."},"solucion":{"valor":2240,"tolerancia":1,"explicacion":"(137 − 25) × 20.000 = 2.240.000 g ≈ 2.240 kg. El tren emite cerca de un 80 % menos por tonelada movida."}},{"slug":"movilidad-6.s1.p7.v3","orden":7,"grupo":"movilidad-6.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una carga de 50.000 toneladas-kilómetro pasa del camión (137 g por t-km) al tren (25 g por t-km). ¿Cuántos kilos de CO₂e se ahorran?","unidad":"kg CO₂e","decimales":0,"contexto":"50000 t-km; 137 contra 25 g por t-km."},"solucion":{"valor":5600,"tolerancia":1,"explicacion":"(137 − 25) × 50.000 = 5.600.000 g ≈ 5.600 kg. El tren emite cerca de un 80 % menos por tonelada movida."}},{"slug":"movilidad-6.s1.p8","orden":8,"grupo":"movilidad-6.s1.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el tren es tan eficiente para la carga.","items":[{"id":"i1","texto":"La rueda de acero sobre el riel roza muy poco"},{"id":"i2","texto":"Mover cada tonelada requiere poca energía"},{"id":"i3","texto":"Una locomotora arrastra muchos vagones a la vez"},{"id":"i4","texto":"La energía se reparte entre mucha carga"},{"id":"i5","texto":"Las emisiones por tonelada y kilómetro son bajas"},{"id":"i6","texto":"El tren es eficiente porque va más rápido que el camión"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Poco rozamiento y mucha carga por motor: la física juega a favor del tren."}},{"slug":"movilidad-6.s1.p9","orden":9,"grupo":"movilidad-6.s1.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el avión de carga emite tanto por tonelada-kilómetro?","opciones":[{"id":"o1","texto":"Mantenerse en el aire a gran velocidad exige mucha energía"},{"id":"o2","texto":"Porque los aviones de carga siempre viajan vacíos"},{"id":"o3","texto":"Porque usa el mismo combustible que los barcos"},{"id":"o4","texto":"Porque vuela solo distancias muy cortas"}]},"solucion":{"clave":["o1"],"explicacion":"Por eso el avión se usa para cargas chicas, valiosas o urgentes, no para volúmenes grandes.","por_opcion":{"o3":"Usa queroseno de aviación; el problema es la energía que necesita volar."}}},{"slug":"movilidad-6.s1.p10","orden":10,"grupo":"movilidad-6.s1.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Para esta carga conviene más el tren o el barco, o el camión?","grupos":[{"id":"g1","nombre":"Tren o barco"},{"id":"g2","nombre":"Camión"}],"items":[{"id":"i1","texto":"Granos de Santiago del Estero al puerto de Rosario"},{"id":"i2","texto":"Una entrega a un almacén de pueblo"},{"id":"i3","texto":"Mineral en grandes volúmenes hacia un puerto"},{"id":"i4","texto":"Del campo al acopio más cercano"},{"id":"i5","texto":"Contenedores entre dos ciudades unidas por vías"},{"id":"i6","texto":"Una carga chica y urgente a un lugar sin vías"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Grandes volúmenes y largas distancias favorecen al tren y al barco; tramos cortos y dispersos, al camión."}},{"slug":"movilidad-6.s1.p11","orden":11,"grupo":"movilidad-6.s1.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el camión lleva más del 90 % de la carga en Argentina, es el modo más eficiente.","razones":[{"id":"r1","texto":"Porque usarse mucho no es lo mismo que ser eficiente"},{"id":"r2","texto":"Porque el tren emite más que el camión por tonelada"},{"id":"r3","texto":"Porque en Argentina no hay ningún tren de carga"}]},"solucion":{"valor":false,"explicacion":"Que un modo se use mucho no significa que sea el más eficiente. El tren y el barco emiten mucho menos por tonelada-kilómetro; su baja participación depende de la infraestructura y de la historia.","clave":["r1"]}},{"slug":"movilidad-6.s1.p12","orden":12,"grupo":"movilidad-6.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe de una empresa de logística y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Medimos nuestras emisiones en gramos por tonelada-kilómetro."},{"id":"s2","texto":"Mandaremos la mercadería de exportación por avión porque es el modo más limpio."},{"id":"s3","texto":"Para las distancias largas, estudiaremos usar el tren."},{"id":"s4","texto":"El barco emite más que el camión por tonelada movida."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Con la tonelada-kilómetro, las comparaciones dejan de ser opiniones.","por_opcion":{"s2":"El avión de carga es el modo que más emite por tonelada-kilómetro.","s4":"Es al revés: el barco marítimo emite alrededor del 5 % de lo que emite el camión."}}},{"slug":"movilidad-6.s1.p13","orden":13,"grupo":"movilidad-6.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Mover una tonelada a lo largo de un kilómetro es una tonelada-{{0}}; en Argentina, más del 90 % de la carga va en {{1}}; y por tonelada movida, el modo que menos emite es el {{2}}.","banco":[{"id":"w1","texto":"kilómetro"},{"id":"w2","texto":"camión"},{"id":"w3","texto":"barco"},{"id":"w4","texto":"litro"},{"id":"w5","texto":"avión"},{"id":"w6","texto":"helicóptero"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para mirar la carga con números."}}]},{"slug":"movilidad-6.s2","orden":2,"tipo":"leccion","titulo_es":"Combinar modos","bajada_es":"Del campo al acopio en camión, del acopio al puerto en tren o barcaza: cuándo conviene la carga intermodal.","minutos":10,"pasos":[{"slug":"movilidad-6.s2.p1","orden":1,"grupo":"movilidad-6.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Del campo al puerto","cuerpo":["Según la Bolsa de Comercio de Rosario, para la cosecha 2023/24 se esperaba que el 83,4 % de las cargas agroindustriales llegara a los puertos en camión, el 16 % en tren y el 0,6 % en barcaza: casi 2,9 millones de viajes en camión y más de 330.000 vagones."],"destacado":{"valor":"≈ 2,9 millones","texto":"de viajes en camión se esperaban para llevar la cosecha 2023/24 a los puertos, según la Bolsa de Comercio de Rosario."}},"solucion":{}},{"slug":"movilidad-6.s2.p2","orden":2,"grupo":"movilidad-6.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un tren lleva 50 vagones de 50 toneladas cada uno. ¿A cuántos camiones de 30 toneladas reemplaza? Redondeá al entero.","unidad":"camiones","decimales":0,"contexto":"50 vagones de 50 t; camiones de 30 t."},"solucion":{"valor":83,"tolerancia":1,"explicacion":"50 × 50 = 2.500 t; ÷ 30 ≈ 83 camiones. Menos camiones en las rutas también significa menos desgaste y menos riesgo de choques."}},{"slug":"movilidad-6.s2.p2.v2","orden":2,"grupo":"movilidad-6.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un tren lleva 60 vagones de 55 toneladas cada uno. ¿A cuántos camiones de 30 toneladas reemplaza? Redondeá al entero.","unidad":"camiones","decimales":0,"contexto":"60 vagones de 55 t; camiones de 30 t."},"solucion":{"valor":110,"tolerancia":1,"explicacion":"60 × 55 = 3.300 t; ÷ 30 ≈ 110 camiones. Menos camiones en las rutas también significa menos desgaste y menos riesgo de choques."}},{"slug":"movilidad-6.s2.p2.v3","orden":2,"grupo":"movilidad-6.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un tren lleva 40 vagones de 50 toneladas cada uno. ¿A cuántos camiones de 30 toneladas reemplaza? Redondeá al entero.","unidad":"camiones","decimales":0,"contexto":"40 vagones de 50 t; camiones de 30 t."},"solucion":{"valor":67,"tolerancia":1,"explicacion":"40 × 50 = 2.000 t; ÷ 30 ≈ 67 camiones. Menos camiones en las rutas también significa menos desgaste y menos riesgo de choques."}},{"slug":"movilidad-6.s2.p3","orden":3,"grupo":"movilidad-6.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La carga intermodal","cuerpo":["La carga intermodal combina modos: el camión hace los tramos cortos y dispersos (del campo al acopio, o del puerto a la fábrica) y el tren o la barcaza, el tramo largo. Cada transbordo cuesta tiempo y dinero, por eso la combinación conviene sobre todo con grandes volúmenes y distancias largas."]},"solucion":{}},{"slug":"movilidad-6.s2.p4","orden":4,"grupo":"movilidad-6.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se mueven 30 toneladas: 50 km en camión (137 g por t-km) y 500 km en tren (25 g por t-km). ¿Cuántos kilos de CO₂e emite el viaje completo? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"30 t; 50 km en camión y 500 km en tren."},"solucion":{"valor":581,"tolerancia":1,"explicacion":"Camión: 30 × 50 × 137 = 205,5 kg. Tren: 30 × 500 × 25 = 375 kg. Total ≈ 581 kg, frente a 2.261 kg si todo fuera en camión."}},{"slug":"movilidad-6.s2.p4.v2","orden":4,"grupo":"movilidad-6.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se mueven 30 toneladas: 30 km en camión (137 g por t-km) y 700 km en tren (25 g por t-km). ¿Cuántos kilos de CO₂e emite el viaje completo? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"30 t; 30 km en camión y 700 km en tren."},"solucion":{"valor":648,"tolerancia":1,"explicacion":"Camión: 30 × 30 × 137 = 123,3 kg. Tren: 30 × 700 × 25 = 525 kg. Total ≈ 648 kg, frente a 3.000 kg si todo fuera en camión."}},{"slug":"movilidad-6.s2.p4.v3","orden":4,"grupo":"movilidad-6.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se mueven 30 toneladas: 80 km en camión (137 g por t-km) y 400 km en tren (25 g por t-km). ¿Cuántos kilos de CO₂e emite el viaje completo? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"30 t; 80 km en camión y 400 km en tren."},"solucion":{"valor":629,"tolerancia":1,"explicacion":"Camión: 30 × 80 × 137 = 328,8 kg. Tren: 30 × 400 × 25 = 300 kg. Total ≈ 629 kg, frente a 1.973 kg si todo fuera en camión."}},{"slug":"movilidad-6.s2.p5","orden":5,"grupo":"movilidad-6.s2.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué los tramos cortos suelen quedar en camión.","items":[{"id":"i1","texto":"La carga sale de muchos campos dispersos"},{"id":"i2","texto":"No hay vías que lleguen a cada campo"},{"id":"i3","texto":"Pasarla al tren exige un transbordo"},{"id":"i4","texto":"Para pocos kilómetros, el transbordo cuesta más de lo que ahorra"},{"id":"i5","texto":"El primer tramo se hace en camión hasta un acopio con vías"},{"id":"i6","texto":"El tren llega a la puerta de cada campo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La combinación eficiente usa cada modo donde es mejor."}},{"slug":"movilidad-6.s2.p6","orden":6,"grupo":"movilidad-6.s2.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué no se mueve toda la carga en tren?","opciones":[{"id":"o1","texto":"Por los transbordos, los tramos sin vías y la infraestructura"},{"id":"o2","texto":"Porque el tren emite más que el camión por tonelada"},{"id":"o3","texto":"Porque la ley prohíbe llevar granos en tren"},{"id":"o4","texto":"Porque los trenes no pueden llevar cargas pesadas"}]},"solucion":{"clave":["o1"],"explicacion":"Para crecer, el tren necesita vías en buen estado, terminales de transferencia y horarios confiables.","por_opcion":{"o3":"No hay tal prohibición: en 2023/24 se esperaba mover el 16 % en tren."}}},{"slug":"movilidad-6.s2.p7","orden":7,"grupo":"movilidad-6.s2.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si la carga pasa del camión al tren, desaparecen los camiones del recorrido.","razones":[{"id":"r1","texto":"Porque siguen haciendo el primer y el último tramo"},{"id":"r2","texto":"Porque el tren también llega a cada casa"},{"id":"r3","texto":"Porque los camiones se prohíben en esas rutas"}]},"solucion":{"valor":false,"explicacion":"Siguen haciendo falta para el primer y el último tramo. Lo que cambia es que hacen trayectos cortos, y el largo va en tren.","clave":["r1"]}},{"slug":"movilidad-6.s2.p8","orden":8,"grupo":"movilidad-6.s2.p8","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada modo con su principal fortaleza.","izquierda":[{"id":"a1","texto":"Camión"},{"id":"a2","texto":"Tren"},{"id":"a3","texto":"Barcaza"},{"id":"a4","texto":"Avión"}],"derecha":[{"id":"b1","texto":"Llega puerta a puerta"},{"id":"b2","texto":"Grandes volúmenes a larga distancia"},{"id":"b3","texto":"Muchísima carga por ríos navegables"},{"id":"b4","texto":"Rapidez para cargas chicas y urgentes"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada modo tiene un lugar: el problema es usar uno solo para todo."}},{"slug":"movilidad-6.s2.p9","orden":9,"grupo":"movilidad-6.s2.p9","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos viajes en camión se esperaban para llevar la cosecha 2023/24 a los puertos.","min":10000,"max":100000000,"paso":1,"unidad":"viajes","escala":"log"},"solucion":{"valor":2900000,"banda":"log","explicacion":"Casi 2,9 millones de viajes, según la Bolsa de Comercio de Rosario."}},{"slug":"movilidad-6.s2.p10","orden":10,"grupo":"movilidad-6.s2.p10","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un primer o último tramo, o un tramo largo troncal?","grupos":[{"id":"g1","nombre":"Primer o último tramo"},{"id":"g2","nombre":"Tramo largo troncal"}],"items":[{"id":"i1","texto":"Del campo al acopio del pueblo"},{"id":"i2","texto":"Del acopio del norte al puerto de Rosario"},{"id":"i3","texto":"Del puerto a la fábrica de la ciudad"},{"id":"i4","texto":"Del puerto de Buenos Aires a una ciudad del sur"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"La idea intermodal: tramos cortos flexibles y tramos largos masivos."}},{"slug":"movilidad-6.s2.p11","orden":11,"grupo":"movilidad-6.s2.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace falta para que el tren mueva más carga? Marcá todo.","opciones":[{"id":"o1","texto":"Vías en buen estado"},{"id":"o2","texto":"Terminales para pasar la carga entre modos"},{"id":"o3","texto":"Horarios confiables"},{"id":"o4","texto":"Conexión directa con los puertos"},{"id":"o5","texto":"Prohibir los camiones en todo el país"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El tren gana carga cuando es confiable y bien conectado, no por prohibición."}},{"slug":"movilidad-6.s2.p12","orden":12,"grupo":"movilidad-6.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta de una cámara empresaria y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Proponemos mejorar las vías que llegan a los puertos."},{"id":"s2","texto":"Si mejoramos el tren, no harán falta más camiones."},{"id":"s3","texto":"Construiremos terminales para pasar la carga del camión al tren."},{"id":"s4","texto":"Para 20 km conviene siempre el tren, aunque haya que hacer dos transbordos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Planificar la carga es combinar modos con criterio, no elegir un ganador.","por_opcion":{"s2":"Siguen haciendo falta para los tramos cortos.","s4":"En tramos cortos, los transbordos suelen costar más de lo que ahorran."}}},{"slug":"movilidad-6.s2.p13","orden":13,"grupo":"movilidad-6.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Combinar camión, tren y barcaza es la carga {{0}}; pasar la carga de un modo a otro es un {{1}}; y para la cosecha 2023/24, el {{2}} % de las cargas agroindustriales iba a llegar a los puertos en tren.","banco":[{"id":"w1","texto":"intermodal"},{"id":"w2","texto":"transbordo"},{"id":"w3","texto":"16"},{"id":"w4","texto":"individual"},{"id":"w5","texto":"peaje"},{"id":"w6","texto":"60"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para pensar la logística de un país extenso."}}]},{"slug":"movilidad-6.s3","orden":3,"tipo":"leccion","titulo_es":"La última milla","bajada_es":"Paquetes a domicilio, camionetas medio vacías, entregas fallidas y bicis de carga.","minutos":10,"pasos":[{"slug":"movilidad-6.s3.p1","orden":1,"grupo":"movilidad-6.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El tramo más caro","cuerpo":["La última milla es el tramo final hasta la casa o el negocio. Es el más caro e ineficiente por unidad: muchas paradas, paquetes chicos, tránsito, entregas fallidas y devoluciones. Según el estudio para la Agencia Europea de Medio Ambiente, las camionetas de reparto emiten por tonelada-kilómetro unas 16 veces más que un camión pesado, porque llevan poca carga en relación con su peso y su consumo."]},"solucion":{}},{"slug":"movilidad-6.s3.p2","orden":2,"grupo":"movilidad-6.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una camioneta de reparto emite 250 g de CO₂ por km, recorre 80 km por día y entrega 100 paquetes. ¿Cuántos gramos corresponden a cada paquete?","unidad":"g por paquete","decimales":0,"contexto":"250 g por km; 80 km; 100 paquetes."},"solucion":{"valor":200,"tolerancia":4,"explicacion":"250 × 80 = 20.000 g; ÷ 100 = 200 g por paquete. Cuantos más paquetes por recorrido, menos emisiones por entrega."}},{"slug":"movilidad-6.s3.p2.v2","orden":2,"grupo":"movilidad-6.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una camioneta de reparto emite 300 g de CO₂ por km, recorre 60 km por día y entrega 120 paquetes. ¿Cuántos gramos corresponden a cada paquete?","unidad":"g por paquete","decimales":0,"contexto":"300 g por km; 60 km; 120 paquetes."},"solucion":{"valor":150,"tolerancia":3,"explicacion":"300 × 60 = 18.000 g; ÷ 120 = 150 g por paquete. Cuantos más paquetes por recorrido, menos emisiones por entrega."}},{"slug":"movilidad-6.s3.p2.v3","orden":2,"grupo":"movilidad-6.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una camioneta de reparto emite 200 g de CO₂ por km, recorre 100 km por día y entrega 80 paquetes. ¿Cuántos gramos corresponden a cada paquete?","unidad":"g por paquete","decimales":0,"contexto":"200 g por km; 100 km; 80 paquetes."},"solucion":{"valor":250,"tolerancia":5,"explicacion":"200 × 100 = 20.000 g; ÷ 80 = 250 g por paquete. Cuantos más paquetes por recorrido, menos emisiones por entrega."}},{"slug":"movilidad-6.s3.p3","orden":3,"grupo":"movilidad-6.s3.p3","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la entrega \"en una hora\" puede aumentar las emisiones.","items":[{"id":"i1","texto":"Se promete entregar cada pedido en una hora"},{"id":"i2","texto":"No hay tiempo para juntar varios pedidos en un recorrido"},{"id":"i3","texto":"Salen más vehículos medio vacíos"},{"id":"i4","texto":"Aumentan los kilómetros por paquete"},{"id":"i5","texto":"Suben las emisiones y el tránsito"},{"id":"i6","texto":"La rapidez obliga a llenar mejor cada camioneta"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La velocidad de entrega tiene un costo ambiental: cuanto más rápido, menos se consolida."}},{"slug":"movilidad-6.s3.p4","orden":4,"grupo":"movilidad-6.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Soluciones","cuerpo":["Hay varias formas de mejorar la última milla: consolidar pedidos para que cada vehículo salga lleno, usar puntos de retiro y casilleros donde se dejan muchos paquetes juntos, repartir en bicis de carga o camionetas eléctricas en zonas densas desde pequeños centros de distribución barriales, y ordenar horarios y zonas de carga y descarga. Del lado de quien compra, ayuda elegir entregas menos urgentes, agrupar compras y evitar devoluciones innecesarias."]},"solucion":{}},{"slug":"movilidad-6.s3.p5","orden":5,"grupo":"movilidad-6.s3.p5","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Reduce o aumenta el impacto de la última milla?","grupos":[{"id":"g1","nombre":"Lo reduce"},{"id":"g2","nombre":"Lo aumenta"}],"items":[{"id":"i1","texto":"Retirar el pedido en un casillero del barrio"},{"id":"i2","texto":"Pedir entrega urgente de un solo producto"},{"id":"i3","texto":"Agrupar varias compras en una sola entrega"},{"id":"i4","texto":"Comprar varias tallas para devolver las que no sirven"},{"id":"i5","texto":"Repartir en bici de carga en el centro"},{"id":"i6","texto":"No estar en casa y pedir un segundo intento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Muchas decisiones de quien compra definen cuántos kilómetros hace el repartidor."}},{"slug":"movilidad-6.s3.p6","orden":6,"grupo":"movilidad-6.s3.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un casillero o punto de retiro reduce las emisiones del reparto?","opciones":[{"id":"o1","texto":"Concentra muchas entregas en una sola parada"},{"id":"o2","texto":"Porque los paquetes pesan menos en un casillero"},{"id":"o3","texto":"Porque los casilleros funcionan con energía solar"},{"id":"o4","texto":"Porque elimina la necesidad de fabricar productos"}]},"solucion":{"clave":["o1"],"explicacion":"Menos paradas y menos entregas fallidas significan menos kilómetros por paquete.","por_opcion":{"o3":"Aunque la usen, lo que ahorra es kilómetros de reparto."}}},{"slug":"movilidad-6.s3.p7","orden":7,"grupo":"movilidad-6.s3.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Comprar por internet siempre contamina menos que ir al negocio.","razones":[{"id":"r1","texto":"Porque depende de cómo se va al negocio y de cómo se entrega"},{"id":"r2","texto":"Porque los paquetes no se transportan"},{"id":"r3","texto":"Porque ir al negocio es siempre en auto"}]},"solucion":{"valor":false,"explicacion":"Depende: si al negocio se va caminando, en bici o en colectivo, o si el pedido llega en entregas urgentes con devoluciones, la compra online puede emitir más. Si se consolida bien, puede emitir menos.","clave":["r1"]}},{"slug":"movilidad-6.s3.p8","orden":8,"grupo":"movilidad-6.s3.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de distribución barrial reemplaza 40 km diarios de camioneta (250 g de CO₂ por km) por bicis de carga. ¿Cuántos kg de CO₂ se evitan por día?","unidad":"kg CO₂","decimales":0,"contexto":"40 km de camioneta por día; 250 g por km."},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"40 × 250 = 10.000 g = 10 kg por día. Además, menos ruido, menos contaminación del aire y menos espacio ocupado en la calle."}},{"slug":"movilidad-6.s3.p8.v2","orden":8,"grupo":"movilidad-6.s3.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de distribución barrial reemplaza 60 km diarios de camioneta (250 g de CO₂ por km) por bicis de carga. ¿Cuántos kg de CO₂ se evitan por día?","unidad":"kg CO₂","decimales":0,"contexto":"60 km de camioneta por día; 250 g por km."},"solucion":{"valor":15,"tolerancia":0.5,"explicacion":"60 × 250 = 15.000 g = 15 kg por día. Además, menos ruido, menos contaminación del aire y menos espacio ocupado en la calle."}},{"slug":"movilidad-6.s3.p8.v3","orden":8,"grupo":"movilidad-6.s3.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de distribución barrial reemplaza 100 km diarios de camioneta (250 g de CO₂ por km) por bicis de carga. ¿Cuántos kg de CO₂ se evitan por día?","unidad":"kg CO₂","decimales":0,"contexto":"100 km de camioneta por día; 250 g por km."},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"100 × 250 = 25.000 g = 25 kg por día. Además, menos ruido, menos contaminación del aire y menos espacio ocupado en la calle."}},{"slug":"movilidad-6.s3.p9","orden":9,"grupo":"movilidad-6.s3.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada solución con cómo ayuda.","izquierda":[{"id":"a1","texto":"Consolidar pedidos"},{"id":"a2","texto":"Punto de retiro"},{"id":"a3","texto":"Bici de carga"},{"id":"a4","texto":"Horario nocturno de descarga"}],"derecha":[{"id":"b1","texto":"Cada vehículo sale más lleno"},{"id":"b2","texto":"Muchas entregas en una sola parada"},{"id":"b3","texto":"Reparto sin emisiones en zonas densas"},{"id":"b4","texto":"Menos choque con el tránsito de la hora pico"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"La logística urbana combina vehículos, lugares y horarios."}},{"slug":"movilidad-6.s3.p10","orden":10,"grupo":"movilidad-6.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un repartidor hace 100 entregas por día. Si el 10 % falla y cada nuevo intento suma 2 km, ¿cuántos km extra recorre por día?","unidad":"km","decimales":0,"contexto":"100 entregas; 10 % fallidas; 2 km por reintento."},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"100 × 10 % = 10 entregas fallidas; × 2 km = 20 km extra por día, solo por no encontrar a nadie."}},{"slug":"movilidad-6.s3.p10.v2","orden":10,"grupo":"movilidad-6.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un repartidor hace 150 entregas por día. Si el 20 % falla y cada nuevo intento suma 1,5 km, ¿cuántos km extra recorre por día?","unidad":"km","decimales":0,"contexto":"150 entregas; 20 % fallidas; 1.5 km por reintento."},"solucion":{"valor":45,"tolerancia":0.9,"explicacion":"150 × 20 % = 30 entregas fallidas; × 1,5 km = 45 km extra por día, solo por no encontrar a nadie."}},{"slug":"movilidad-6.s3.p10.v3","orden":10,"grupo":"movilidad-6.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un repartidor hace 80 entregas por día. Si el 15 % falla y cada nuevo intento suma 3 km, ¿cuántos km extra recorre por día?","unidad":"km","decimales":0,"contexto":"80 entregas; 15 % fallidas; 3 km por reintento."},"solucion":{"valor":36,"tolerancia":0.72,"explicacion":"80 × 15 % = 12 entregas fallidas; × 3 km = 36 km extra por día, solo por no encontrar a nadie."}},{"slug":"movilidad-6.s3.p11","orden":11,"grupo":"movilidad-6.s3.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué puede hacer quien compra para reducir el impacto de sus pedidos? Marcá todo.","opciones":[{"id":"o1","texto":"Elegir una entrega menos urgente"},{"id":"o2","texto":"Agrupar compras en un solo pedido"},{"id":"o3","texto":"Retirar en un punto cercano"},{"id":"o4","texto":"Evitar devoluciones innecesarias"},{"id":"o5","texto":"Pedir cada producto por separado apenas se lo necesita"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La comodidad tiene kilómetros detrás: elegir con información ayuda."}},{"slug":"movilidad-6.s3.p12","orden":12,"grupo":"movilidad-6.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este anuncio de una aplicación de compras y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Ahora podés retirar tus pedidos en casilleros de tu barrio."},{"id":"s2","texto":"Entregamos en 15 minutos, y es la opción más ecológica."},{"id":"s3","texto":"En el centro repartimos con bicis de carga."},{"id":"s4","texto":"Devolvé todo lo que quieras: devolver no tiene impacto."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Rapidez y devoluciones gratis tienen costos ambientales que no aparecen en el precio.","por_opcion":{"s2":"La entrega ultrarrápida impide consolidar y suele sumar kilómetros por paquete.","s4":"Cada devolución es otro viaje y más manipulación."}}},{"slug":"movilidad-6.s3.p13","orden":13,"grupo":"movilidad-6.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El tramo final de una entrega es la última {{0}}; juntar varios pedidos en un mismo recorrido es {{1}}; y en zonas densas se puede repartir en bicis de {{2}}.","banco":[{"id":"w1","texto":"milla"},{"id":"w2","texto":"consolidar"},{"id":"w3","texto":"carga"},{"id":"w4","texto":"ruta"},{"id":"w5","texto":"separar"},{"id":"w6","texto":"paseo"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para ordenar el reparto urbano."}}]},{"slug":"movilidad-6.s4","orden":4,"tipo":"leccion","titulo_es":"Volar","bajada_es":"Cuánto calienta la aviación, quiénes vuelan, los combustibles alternativos y los vuelos que se reemplazan por trenes.","minutos":11,"pasos":[{"slug":"movilidad-6.s4.p1","orden":1,"grupo":"movilidad-6.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una parte chica que pesa más","cuerpo":["Según Our World in Data, en 2019 la aviación generó el 2,5 % de las emisiones de CO₂ de origen fósil y del uso de la tierra. Pero su efecto en el calentamiento es mayor: explica alrededor del 3,5 % del forzamiento radiativo efectivo, porque dos tercios de su efecto vienen de factores distintos del CO₂, sobre todo las estelas de condensación que se forman detrás de los aviones."]},"solucion":{}},{"slug":"movilidad-6.s4.p2","orden":2,"grupo":"movilidad-6.s4.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la aviación genera el 2,5 % del CO₂ pero explica el 3,5 % del calentamiento, ¿cuántas veces más grande es su peso en el calentamiento que en el CO₂? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"2,5 % del CO₂; 3,5 % del forzamiento."},"solucion":{"valor":1.4,"tolerancia":0.1,"explicacion":"3,5 ÷ 2,5 = 1,4 veces. Mirar solo el CO₂ subestima el impacto de volar."}},{"slug":"movilidad-6.s4.p3","orden":3,"grupo":"movilidad-6.s4.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un efecto del CO₂ o un efecto distinto del CO₂ de la aviación?","grupos":[{"id":"g1","nombre":"Efecto del CO₂"},{"id":"g2","nombre":"Efecto distinto del CO₂"}],"items":[{"id":"i1","texto":"Quemar queroseno libera dióxido de carbono"},{"id":"i2","texto":"Estelas de condensación que atrapan calor"},{"id":"i3","texto":"Parte de ese gas queda en el aire durante siglos"},{"id":"i4","texto":"Óxidos de nitrógeno emitidos en altura"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Las estelas duran poco, pero se forman cada día: por eso pesan tanto en el calentamiento actual."}},{"slug":"movilidad-6.s4.p4","orden":4,"grupo":"movilidad-6.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Pocos vuelan mucho","cuerpo":["Un estudio publicado en 2020 estimó que en 2018 solo el 11 % de la población mundial tomó al menos un vuelo, y como mucho el 4 % un vuelo internacional. El 1 % de la población que más vuela sería responsable de más de la mitad de las emisiones de los vuelos de pasajeros."],"destacado":{"valor":"1 %","texto":"de la población mundial que más vuela genera más de la mitad de las emisiones de los vuelos de pasajeros, según un estudio de 2020."}},"solucion":{}},{"slug":"movilidad-6.s4.p5","orden":5,"grupo":"movilidad-6.s4.p5","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La mayoría de la población mundial vuela todos los años.","razones":[{"id":"r1","texto":"Porque solo el 11 % voló en 2018"},{"id":"r2","texto":"Porque volar es obligatorio para trabajar"},{"id":"r3","texto":"Porque todas las personas vuelan al menos una vez por año"}]},"solucion":{"valor":false,"explicacion":"En 2018, solo el 11 % de la población mundial tomó un vuelo. Volar es, sobre todo, una actividad de una minoría.","clave":["r1"]}},{"slug":"movilidad-6.s4.p6","orden":6,"grupo":"movilidad-6.s4.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué implica que el 1 % que más vuela genere más de la mitad de las emisiones de los vuelos de pasajeros?","opciones":[{"id":"o1","texto":"Que medidas dirigidas a quienes vuelan mucho tienen gran efecto"},{"id":"o2","texto":"Que no importa cuánto vuele cada persona"},{"id":"o3","texto":"Que la aviación no tiene ningún impacto climático"},{"id":"o4","texto":"Que todas las personas contaminan lo mismo al viajar"}]},"solucion":{"clave":["o1"],"explicacion":"Cuando las emisiones están tan concentradas, las políticas también pueden concentrarse.","por_opcion":{"o3":"Lo tiene: 2,5 % del CO₂ y más del calentamiento."}}},{"slug":"movilidad-6.s4.p7","orden":7,"grupo":"movilidad-6.s4.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un vuelo de cabotaje de ida y vuelta tiene 700 km por tramo. Con 246 g de CO₂e por pasajero y km, ¿cuántos kilos emite cada pasajero? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"700 km por tramo; 246 g por pasajero y km."},"solucion":{"valor":344,"tolerancia":2,"explicacion":"700 × 2 × 246 = 344.400 g ≈ 344 kg por pasajero, sin contar el efecto de las estelas."}},{"slug":"movilidad-6.s4.p7.v2","orden":7,"grupo":"movilidad-6.s4.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un vuelo de cabotaje de ida y vuelta tiene 1.100 km por tramo. Con 246 g de CO₂e por pasajero y km, ¿cuántos kilos emite cada pasajero? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"1100 km por tramo; 246 g por pasajero y km."},"solucion":{"valor":541,"tolerancia":2,"explicacion":"1.100 × 2 × 246 = 541.200 g ≈ 541 kg por pasajero, sin contar el efecto de las estelas."}},{"slug":"movilidad-6.s4.p7.v3","orden":7,"grupo":"movilidad-6.s4.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un vuelo de cabotaje de ida y vuelta tiene 1.500 km por tramo. Con 246 g de CO₂e por pasajero y km, ¿cuántos kilos emite cada pasajero? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"1500 km por tramo; 246 g por pasajero y km."},"solucion":{"valor":738,"tolerancia":2,"explicacion":"1.500 × 2 × 246 = 738.000 g ≈ 738 kg por pasajero, sin contar el efecto de las estelas."}},{"slug":"movilidad-6.s4.p8","orden":8,"grupo":"movilidad-6.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Combustibles, tecnología y trenes","cuerpo":["Los aviones eléctricos o a hidrógeno, por ahora, sirven solo para distancias cortas. Los combustibles sostenibles de aviación, hechos por ejemplo con aceites usados, crecen pero siguen siendo mínimos: según la IATA, en 2024 se produjo 1 millón de toneladas, apenas el 0,3 % del combustible de aviación del mundo. Y aunque cada avión nuevo es algo más eficiente, el aumento de vuelos se come esas mejoras.","Algunos países reemplazan vuelos por trenes. Francia prohibió desde 2023 los vuelos internos cuando hay una alternativa en tren de hasta dos horas y media, lo que afectó a tres rutas desde París."]},"solucion":{}},{"slug":"movilidad-6.s4.p9","orden":9,"grupo":"movilidad-6.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los combustibles sostenibles son el 0,3 % del combustible de aviación, ¿cuántos litros hay en 1.000.000 litros de combustible?","unidad":"litros","decimales":0,"contexto":"1000000 litros; 0,3 % sostenible."},"solucion":{"valor":3000,"tolerancia":60,"explicacion":"1.000.000 × 0,3 % = 3.000 litros. Todavía es una fracción mínima del total."}},{"slug":"movilidad-6.s4.p9.v2","orden":9,"grupo":"movilidad-6.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los combustibles sostenibles son el 0,3 % del combustible de aviación, ¿cuántos litros hay en 5.000.000 litros de combustible?","unidad":"litros","decimales":0,"contexto":"5000000 litros; 0,3 % sostenible."},"solucion":{"valor":15000,"tolerancia":300,"explicacion":"5.000.000 × 0,3 % = 15.000 litros. Todavía es una fracción mínima del total."}},{"slug":"movilidad-6.s4.p9.v3","orden":9,"grupo":"movilidad-6.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los combustibles sostenibles son el 0,3 % del combustible de aviación, ¿cuántos litros hay en 20.000.000 litros de combustible?","unidad":"litros","decimales":0,"contexto":"20000000 litros; 0,3 % sostenible."},"solucion":{"valor":60000,"tolerancia":1200,"explicacion":"20.000.000 × 0,3 % = 60.000 litros. Todavía es una fracción mínima del total."}},{"slug":"movilidad-6.s4.p10","orden":10,"grupo":"movilidad-6.s4.p10","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la eficiencia sola no baja las emisiones de la aviación.","items":[{"id":"i1","texto":"Cada avión nuevo consume algo menos por pasajero"},{"id":"i2","texto":"Los costos por pasaje bajan"},{"id":"i3","texto":"Vuela más gente, y más seguido"},{"id":"i4","texto":"El total de kilómetros volados crece más rápido que la eficiencia"},{"id":"i5","texto":"Las emisiones totales siguen subiendo"},{"id":"i6","texto":"Aviones más eficientes hacen que la gente vuele menos"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Es un efecto rebote a escala mundial: sin gestionar la demanda, la eficiencia no alcanza."}},{"slug":"movilidad-6.s4.p11","orden":11,"grupo":"movilidad-6.s4.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada medida con su efecto esperado.","izquierda":[{"id":"a1","texto":"Prohibir vuelos cortos con tren alternativo"},{"id":"a2","texto":"Combustible sostenible de aviación"},{"id":"a3","texto":"Rutas que evitan formar estelas"},{"id":"a4","texto":"Cargos más altos para quienes vuelan muy seguido"}],"derecha":[{"id":"b1","texto":"Pasar viajeros al tren"},{"id":"b2","texto":"Menos CO₂ de origen fósil por litro"},{"id":"b3","texto":"Menos calentamiento distinto del CO₂"},{"id":"b4","texto":"Más peso sobre quienes más emiten"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Ninguna medida sola alcanza: la aviación necesita varias a la vez."}},{"slug":"movilidad-6.s4.p12","orden":12,"grupo":"movilidad-6.s4.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cómo puede una persona reducir la huella de sus vuelos? Marcá todo.","opciones":[{"id":"o1","texto":"Viajar en tren o micro en distancias medias"},{"id":"o2","texto":"Hacer menos viajes, pero más largos"},{"id":"o3","texto":"Reemplazar reuniones por videollamadas"},{"id":"o4","texto":"Elegir vuelos directos en vez de con escalas"},{"id":"o5","texto":"Elegir vuelos con varias escalas para \"repartir\" las emisiones"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los despegues consumen mucho: cada escala suma emisiones."}},{"slug":"movilidad-6.s4.p13","orden":13,"grupo":"movilidad-6.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este folleto de una agencia de viajes y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"El tren es una opción de menor huella para viajes medianos."},{"id":"s2","texto":"La aviación ya usa mayormente combustibles sostenibles."},{"id":"s3","texto":"Francia reemplazó algunos vuelos cortos por trenes."},{"id":"s4","texto":"El impacto de volar es solo su CO₂."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La aviación es uno de los sectores más difíciles de descarbonizar: conviene no creer en atajos.","por_opcion":{"s2":"En 2024 eran apenas el 0,3 % del combustible de aviación.","s4":"Las estelas y otros efectos distintos del CO₂ suman bastante más calentamiento."}}},{"slug":"movilidad-6.s4.p14","orden":14,"grupo":"movilidad-6.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las líneas blancas que dejan los aviones y atrapan calor son {{0}} de condensación; en 2018, solo el {{1}} % de la población mundial voló; y en 2024 los combustibles sostenibles eran el {{2}} % del combustible de aviación.","banco":[{"id":"w1","texto":"estelas"},{"id":"w2","texto":"11"},{"id":"w3","texto":"0,3"},{"id":"w4","texto":"nubes"},{"id":"w5","texto":"60"},{"id":"w6","texto":"30"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos para discutir el lugar de la aviación en el clima."}}]},{"slug":"movilidad-6.s5","orden":5,"tipo":"leccion","titulo_es":"Viajes largos y turismo","bajada_es":"Avión, auto o tren para ir lejos, la huella del turismo y los barcos que mueven el comercio mundial.","minutos":11,"pasos":[{"slug":"movilidad-6.s5.p1","orden":1,"grupo":"movilidad-6.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Elegir cómo viajar lejos","cuerpo":["Para distancias medias, de unos cientos de kilómetros, el tren o el micro de larga distancia suelen tener mucha menos huella por pasajero que el avión o el auto con una sola persona. Con los valores de referencia británicos que publica Our World in Data que ya usaste, un vuelo de cabotaje emite unos 246 g de CO₂e por pasajero y km; un auto a nafta, unos 192 g por km, sin importar cuántas personas lleve; y el tren, unos 41 g por pasajero y km."]},"solucion":{}},{"slug":"movilidad-6.s5.p2","orden":2,"grupo":"movilidad-6.s5.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia de cuatro personas viaja 1.000 km en avión (246 g por pasajero y km). ¿Cuántos kilos de CO₂e emite en total en ese tramo? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"4 personas; 1000 km; 246 g por pasajero y km."},"solucion":{"valor":984,"tolerancia":2,"explicacion":"4 × 1.000 × 246 = 984.000 g ≈ 984 kg. En auto, los cuatro juntos emitirían unos 192 kg: con el auto lleno, la comparación cambia mucho."}},{"slug":"movilidad-6.s5.p2.v2","orden":2,"grupo":"movilidad-6.s5.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia de cuatro personas viaja 700 km en avión (246 g por pasajero y km). ¿Cuántos kilos de CO₂e emite en total en ese tramo? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"4 personas; 700 km; 246 g por pasajero y km."},"solucion":{"valor":689,"tolerancia":2,"explicacion":"4 × 700 × 246 = 688.800 g ≈ 689 kg. En auto, los cuatro juntos emitirían unos 134 kg: con el auto lleno, la comparación cambia mucho."}},{"slug":"movilidad-6.s5.p2.v3","orden":2,"grupo":"movilidad-6.s5.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia de cuatro personas viaja 500 km en avión (246 g por pasajero y km). ¿Cuántos kilos de CO₂e emite en total en ese tramo? Redondeá al entero.","unidad":"kg CO₂e","decimales":0,"contexto":"4 personas; 500 km; 246 g por pasajero y km."},"solucion":{"valor":492,"tolerancia":2,"explicacion":"4 × 500 × 246 = 492.000 g ≈ 492 kg. En auto, los cuatro juntos emitirían unos 96 kg: con el auto lleno, la comparación cambia mucho."}},{"slug":"movilidad-6.s5.p3","orden":3,"grupo":"movilidad-6.s5.p3","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Una persona sola viaja 800 km. Ordená estas opciones por sus emisiones, de más a menos (valores de referencia).","items":[{"id":"i1","texto":"Avión: 246 g por km"},{"id":"i2","texto":"Auto a nafta, sola: 192 g por km"},{"id":"i3","texto":"Tren: 41 g por km"}],"extremos":["Más emisiones","Menos emisiones"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Para una sola persona, el tren emite una fracción de lo que emiten el avión o el auto.","valores":{"i1":"≈ 197 kg","i2":"≈ 154 kg","i3":"≈ 33 kg"}}},{"slug":"movilidad-6.s5.p4","orden":4,"grupo":"movilidad-6.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona va y vuelve del trabajo en colectivo, 10 km por tramo, 220 días por año, a 105 g de CO₂e por pasajero y km. ¿Cuántos kilos emite en un año?","unidad":"kg CO₂e","decimales":0,"contexto":"10 km por tramo; 220 días; 105 g por pasajero y km."},"solucion":{"valor":462,"tolerancia":1,"explicacion":"10 × 2 × 220 × 105 = 462.000 g ≈ 462 kg por año. Un solo vuelo de ida y vuelta de 1.000 km por tramo emite unos 492 kg por pasajero: más que todo ese año de colectivo."}},{"slug":"movilidad-6.s5.p4.v2","orden":4,"grupo":"movilidad-6.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona va y vuelve del trabajo en colectivo, 5 km por tramo, 220 días por año, a 105 g de CO₂e por pasajero y km. ¿Cuántos kilos emite en un año?","unidad":"kg CO₂e","decimales":0,"contexto":"5 km por tramo; 220 días; 105 g por pasajero y km."},"solucion":{"valor":231,"tolerancia":1,"explicacion":"5 × 2 × 220 × 105 = 231.000 g ≈ 231 kg por año. Un solo vuelo de ida y vuelta de 1.000 km por tramo emite unos 492 kg por pasajero: más que todo ese año de colectivo."}},{"slug":"movilidad-6.s5.p4.v3","orden":4,"grupo":"movilidad-6.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona va y vuelve del trabajo en colectivo, 20 km por tramo, 220 días por año, a 105 g de CO₂e por pasajero y km. ¿Cuántos kilos emite en un año?","unidad":"kg CO₂e","decimales":0,"contexto":"20 km por tramo; 220 días; 105 g por pasajero y km."},"solucion":{"valor":924,"tolerancia":1,"explicacion":"20 × 2 × 220 × 105 = 924.000 g ≈ 924 kg por año. Un solo vuelo de ida y vuelta de 1.000 km por tramo emite unos 492 kg por pasajero: más de la mitad de todo ese año de colectivo."}},{"slug":"movilidad-6.s5.p5","orden":5,"grupo":"movilidad-6.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La huella del turismo","cuerpo":["Un estudio publicado en 2018 estimó que la huella de carbono del turismo mundial pasó de 3,9 a 4,5 GtCO₂e entre 2009 y 2013: alrededor del 8 % de las emisiones mundiales. No es solo el transporte: también pesan las compras, la comida y el alojamiento. La mayor parte la generan personas de países de ingresos altos. Viajar a destinos más cercanos, quedarse más tiempo en cada lugar y consumir productos locales reduce esa huella."]},"solucion":{}},{"slug":"movilidad-6.s5.p6","orden":6,"grupo":"movilidad-6.s5.p6","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las emisiones mundiales se atribuía al turismo, según el estudio de 2018.","min":0,"max":50,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":8,"banda":"lineal","explicacion":"Alrededor del 8 %, sumando transporte, compras, comida y alojamiento de los turistas."}},{"slug":"movilidad-6.s5.p7","orden":7,"grupo":"movilidad-6.s5.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En un viaje de vacaciones, el transporte es lo único que genera emisiones.","razones":[{"id":"r1","texto":"Porque alojamiento, comida y compras también emiten"},{"id":"r2","texto":"Porque los hoteles no usan energía"},{"id":"r3","texto":"Porque la comida en viaje no tiene huella"}]},"solucion":{"valor":false,"explicacion":"El alojamiento, la comida y las compras también suman. El estudio de 2018 encontró que el turismo pesa alrededor del 8 % de las emisiones mundiales contando todo eso.","clave":["r1"]}},{"slug":"movilidad-6.s5.p8","orden":8,"grupo":"movilidad-6.s5.p8","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una práctica de turismo de menor o de mayor huella?","grupos":[{"id":"g1","nombre":"Menor huella"},{"id":"g2","nombre":"Mayor huella"}],"items":[{"id":"i1","texto":"Ir en tren a un destino cercano y quedarse dos semanas"},{"id":"i2","texto":"Tres escapadas de fin de semana en avión"},{"id":"i3","texto":"Comer productos de la zona"},{"id":"i4","texto":"Un crucero con vuelos de ida y vuelta"},{"id":"i5","texto":"Recorrer el destino caminando o en bici"},{"id":"i6","texto":"Alquilar un auto grande para hacer pocas cuadras"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Viajar menos veces, más cerca y más tiempo es la receta del turismo lento."}},{"slug":"movilidad-6.s5.p9","orden":9,"grupo":"movilidad-6.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los barcos del comercio mundial","cuerpo":["La mayor parte del comercio mundial viaja por mar. Según la Organización Marítima Internacional, en 2018 el transporte marítimo generó el 2,89 % de las emisiones humanas de gases de efecto invernadero. Por tonelada movida es el modo más eficiente, pero mueve cantidades enormes y usa combustibles muy contaminantes. En 2023, la organización acordó reducir sus emisiones al menos un 20 % para 2030 y un 70 % para 2040, respecto de 2008, y llegar a cero neto alrededor de 2050."]},"solucion":{}},{"slug":"movilidad-6.s5.p10","orden":10,"grupo":"movilidad-6.s5.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué acordó la Organización Marítima Internacional en 2023?","opciones":[{"id":"o1","texto":"Llegar a cero neto alrededor de 2050, con metas intermedias"},{"id":"o2","texto":"Prohibir todos los barcos de carga para 2030"},{"id":"o3","texto":"Que el transporte marítimo quede fuera de toda meta climática"},{"id":"o4","texto":"Reemplazar todos los barcos por aviones de carga"}]},"solucion":{"clave":["o1"],"explicacion":"El comercio marítimo es un sector difícil de descarbonizar, pero ya tiene metas acordadas.","por_opcion":{"o3":"Al contrario: fijó metas para 2030, 2040 y 2050."}}},{"slug":"movilidad-6.s5.p11","orden":11,"grupo":"movilidad-6.s5.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué prácticas corresponden al turismo lento? Marcá todas.","opciones":[{"id":"o1","texto":"Elegir destinos más cercanos"},{"id":"o2","texto":"Quedarse más tiempo en cada lugar"},{"id":"o3","texto":"Moverse en tren o micro cuando se puede"},{"id":"o4","texto":"Consumir en comercios y productores locales"},{"id":"o5","texto":"Sumar la mayor cantidad posible de destinos en pocos días"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El turismo lento también suele dejar más ingresos en las comunidades que se visitan."}},{"slug":"movilidad-6.s5.p12","orden":12,"grupo":"movilidad-6.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de un blog de viajes y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Para 500 km, el tren es una buena opción de baja huella."},{"id":"s2","texto":"El avión siempre emite menos que el auto, lleve cuantas personas lleve el auto."},{"id":"s3","texto":"Quedarse más tiempo en un destino reduce la huella por día de viaje."},{"id":"s4","texto":"El turismo no tiene impacto en el clima."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los viajes largos son donde más pesa elegir bien.","por_opcion":{"s2":"Con el auto lleno, el auto puede emitir mucho menos que cuatro pasajes de avión.","s4":"Se estima en alrededor del 8 % de las emisiones mundiales."}}},{"slug":"movilidad-6.s5.p13","orden":13,"grupo":"movilidad-6.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Viajar más cerca, menos veces y por más tiempo es el turismo {{0}}; el turismo representa alrededor del {{1}} % de las emisiones mundiales; y el transporte marítimo se propuso llegar a cero neto alrededor de {{2}}.","banco":[{"id":"w1","texto":"lento"},{"id":"w2","texto":"8"},{"id":"w3","texto":"2050"},{"id":"w4","texto":"rápido"},{"id":"w5","texto":"80"},{"id":"w6","texto":"2025"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para viajar lejos con menos huella."}}]},{"slug":"movilidad-6.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: carga y viajes largos","bajada_es":"Toneladas-kilómetro, carga intermodal, última milla, aviación y turismo, mezclados.","minutos":8,"pasos":[{"slug":"movilidad-6.s6.p1","orden":1,"grupo":"movilidad-6.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Carga, logística y viajes largos». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"movilidad-6.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la cooperativa del norte","bajada_es":"Una cooperativa del Chaco tiene que llevar su cosecha al puerto y mandar a tres personas a un congreso. Compará las opciones con números.","minutos":10,"pasos":[{"slug":"movilidad-6.s7.p1","orden":1,"grupo":"movilidad-6.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["La cooperativa debe llevar 30.000 toneladas de granos a un puerto a 800 km. Opción A: todo en camión. Opción B: 50 km en camión hasta un acopio con vías y 750 km en tren. Usá 137 g de CO₂e por tonelada-kilómetro para el camión y 25 g para el tren. Además, tres integrantes tienen que asistir a un congreso a 1.000 km: pueden ir en avión (246 g por pasajero y km), en micro, o participar por videollamada."]},"solucion":{}},{"slug":"movilidad-6.s7.p2","orden":2,"grupo":"movilidad-6.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas toneladas de CO₂e emite la opción A, todo en camión?","unidad":"t CO₂e","decimales":0,"contexto":"30.000 t; 800 km; 137 g por t-km."},"solucion":{"valor":3288,"tolerancia":5,"explicacion":"30.000 × 800 = 24.000.000 t-km; × 137 g = 3.288.000.000 g = 3.288 toneladas de CO₂e."}},{"slug":"movilidad-6.s7.p3","orden":3,"grupo":"movilidad-6.s7.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas toneladas de CO₂e emite la opción B, camión más tren? Redondeá al entero.","unidad":"t CO₂e","decimales":0,"contexto":"50 km en camión y 750 km en tren."},"solucion":{"valor":768,"tolerancia":2,"explicacion":"Camión: 30.000 × 50 × 137 = 205,5 t. Tren: 30.000 × 750 × 25 = 562,5 t. Total: 768 toneladas de CO₂e."}},{"slug":"movilidad-6.s7.p4","orden":4,"grupo":"movilidad-6.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿En qué porcentaje reduce las emisiones la opción B respecto de la A? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"A: 3.288 t; B: 768 t."},"solucion":{"valor":77,"tolerancia":1,"explicacion":"(3.288 − 768) ÷ 3.288 × 100 ≈ 77 %: más de tres cuartos menos de emisiones moviendo la misma carga."}},{"slug":"movilidad-6.s7.p5","orden":5,"grupo":"movilidad-6.s7.p5","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la opción B igual necesita camiones?","opciones":[{"id":"o1","texto":"Porque las vías no llegan a cada campo"},{"id":"o2","texto":"Porque el tren no puede transportar granos"},{"id":"o3","texto":"Porque el camión emite menos que el tren"},{"id":"o4","texto":"Porque la ley obliga a usar los dos modos"}]},"solucion":{"clave":["o1"],"explicacion":"El camión hace el tramo corto y disperso; el tren, el largo y masivo.","por_opcion":{"o3":"Es al revés: emite más por tonelada-kilómetro."}}},{"slug":"movilidad-6.s7.p6","orden":6,"grupo":"movilidad-6.s7.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kilos de CO₂e emitirían las tres personas si viajan en avión, ida y vuelta?","unidad":"kg CO₂e","decimales":0,"contexto":"3 personas; 1.000 km por tramo; 246 g por pasajero y km."},"solucion":{"valor":1476,"tolerancia":5,"explicacion":"3 × 1.000 × 2 × 246 = 1.476.000 g = 1.476 kg, sin contar el efecto de las estelas."}},{"slug":"movilidad-6.s7.p7","orden":7,"grupo":"movilidad-6.s7.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué opciones reducen la huella del viaje al congreso? Marcá todas.","opciones":[{"id":"o1","texto":"Participar por videollamada"},{"id":"o2","texto":"Viajar en micro de larga distancia"},{"id":"o3","texto":"Mandar a una sola persona que comparta lo aprendido"},{"id":"o4","texto":"Aprovechar el viaje para varias reuniones en la misma ciudad"},{"id":"o5","texto":"Ir cada uno en su propio vuelo en días distintos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Muchas veces la mejor opción combina menos viajes con viajes más eficientes."}},{"slug":"movilidad-6.s7.p8","orden":8,"grupo":"movilidad-6.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La cooperativa redacta su informe de sustentabilidad. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Pasar al tren el tramo largo reduce cerca de un 77 % las emisiones de la carga."},{"id":"s2","texto":"Con el tren eliminamos por completo el uso de camiones."},{"id":"s3","texto":"Una integrante participará del congreso por videollamada."},{"id":"s4","texto":"El viaje en avión no tiene impacto porque es una sola vez al año."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un informe creíble muestra los números y no exagera los logros.","por_opcion":{"s2":"Los camiones siguen haciendo los 50 km hasta el acopio.","s4":"Un solo viaje de ida y vuelta de tres personas suma unos 1.476 kg de CO₂e."}}}]}]}$ac$::jsonb);
